 [aliases,traceAliases].forEach(function(m){Object.keys(m||{}).forEach(function(k){var target=m[k];if(typeof target==='string'&&records[target])add(alt,k,target);});});
 function resolve(value){var k=typeof value==='string'?value:'';if(records[k])return {requested:k,status:'exact-id',keys:[k],key:k};var n=norm(k),a=tags[n]||alt[n]||[];return {requested:k,status:a.length===1?'unique-exact-tag':a.length?'ambiguous':'missing',keys:a.slice(),key:a.length===1?a[0]:null};}
