 S.ownerKeys.concat([S.notebookKey]).forEach(function(k){var n=I[k],matched=(Array.isArray(rows)?rows:Object.values(rows)).filter(function(r){return r&&(r.assetId===k||r.key===k);});if(!n&&!matched.length){missing.push(k);return;}var p={definition:'CF_SOURCE_12NV',owner:k,moduleId:'stabilizer',notebookKey:S.notebookKey,factIds:S.newEntries.map(function(f){return f.id;})},link={moduleId:'stabilizer',owner:k,geometry:'ILLUSTRATIVE_TRAINING_CONTEXT'};if(n){n.sourceReview12NV=p;n.d=n.d||[];var text='12NV: same stabilizer lesson includes feed filters/preheater/flash, solids filters, product cooler/parallel pumps, distinct product and return branches, and C-5700 recovery. Current retained source routes govern;1394 receiver nozzle remains pending. No new plant equipment, controls or measured values.';if(!n.d.includes(text))n.d.push(text);n.stabilizerSystemTraining12NV=link;}found.push(k);matched.forEach(function(r){r.sourceReview12NV=p;r.stabilizerSystemTraining12NV=link;});});
 if(H.sourceDefinitions&&!H.sourceDefinitions.some(function(d){return d.name==='CF_SOURCE_12NV';}))H.sourceDefinitions.push({name:'CF_SOURCE_12NV',value:S});return {build:'12NV',owners:found,missing:missing,newPhysicalEquipment:0,newPlates:0,storageWrites:0};
