 var nn=cfApplyDemethPresentation12NN({info:INFO,records:CF3D_DEVICE_RECORDS});[CF3D_DEVICE_DATA,CF_TRACE_DATA_12IZ.components].forEach(function(set){if(set)CF_SOURCE_12NN.ownerKeys.forEach(function(k){if(set[k]&&INFO[k])set[k].sourceReview12NN=INFO[k].sourceReview12NN;});});result.presentation12NN=nn;
