  var r=CF_TRACE_DATA_12IZ.components[k];if(CF3D_DEVICE_RECORDS[k]||!r||!INFO[k]||!(/^(equipment|pump|vessel|tank|filter|exchanger|compressor|motor|heater|blower)$/.test(r.kind||'')))return;
