  var a=matches[0],brief={};['tag','status','category','retained','missing','conflicts','photoIds','referenceOnly','build','latestReviewBuild'].forEach(function(f){if(a[f]!==undefined)brief[f]=Array.isArray(a[f])?a[f].slice():a[f];});
