function cfApplyCompressorTraining12MO(H,S){
 'use strict';var I=H.info||{},sets=[H.records,H.deviceData,H.trace],ids=S.newEntries.map(function(f){return f.id;}),updated=[];
 function get(set,key){return Array.isArray(set)?set.find(function(r){return (r.assetId||r.key)===key;}):set&&set[key];}
 S.models.forEach(function(m){var found=false;sets.forEach(function(set){var r=get(set,m.owner);if(!r)return;found=true;r.sourceReview12MO={definition:'CF_SOURCE_12MO',factIds:ids,notebookKey:S.notebookKey};r.internalTraining12MO={family:m.id,representativeOwner:m.owner,independentClock:true,installedPartsAssigned:false};});if(!found)throw Error('Training owner missing: '+m.owner);if(I[m.owner])I[m.owner].sourceReview12MO={definition:'CF_SOURCE_12MO',factIds:ids,notebookKey:S.notebookKey};updated.push(m.owner);});
 if(!I[S.notebookKey])I[S.notebookKey]={t:S.title,d:['Training > Compressor Internals Studio: one inlet KBZ/6, one residue KBZ/6 and the overhead JGQ/2. Independent play/pause/rewind, gas-cycle cutaway, clickable training parts and complete current owner records. Future expander/refrigeration/regeneration categories are not implemented yet.','Generic internal parts, ideal pressure cycles and illustrative crank timing are separate from installed specifications, plant controls and approved operating procedures. No part number, rating or sister serial is inferred from the cutaway.'],sourceReview12MO:{definition:'CF_SOURCE_12MO',factIds:ids}};
 if(H.sourceDefinitions&&!H.sourceDefinitions.some(function(x){return x.name==='CF_SOURCE_12MO';}))H.sourceDefinitions.push({name:'CF_SOURCE_12MO',value:S});
 if(H.categories){var name='Training / Compressor Internals Studio',cat=H.categories.find(function(c){return c[0]===name;});if(!cat){cat=[name,[]];H.categories.push(cat);} [S.notebookKey].concat(S.ownerKeys).forEach(function(k){if(cat[1].indexOf(k)<0)cat[1].push(k);});}
 return {build:'12MO',sourceOwner:'CF_SOURCE_12MO',owners:updated,newPhysicalEquipment:0,controlsChanged:false,storageSchemasChanged:false,scope:'Separate on-demand teaching workspace; not manufacturing CAD or an installed BOM'};
}
