 function wrap(a){return (a%TAU+TAU)%TAU;}
 function escape(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
 var V={add:function(a,b){return[a[0]+b[0],a[1]+b[1],a[2]+b[2]];},sub:function(a,b){return[a[0]-b[0],a[1]-b[1],a[2]-b[2]];},mul:function(a,s){return[a[0]*s,a[1]*s,a[2]*s];},dot:function(a,b){return a[0]*b[0]+a[1]*b[1]+a[2]*b[2];},cross:function(a,b){return[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];},len:function(a){return Math.hypot(a[0],a[1],a[2]);},norm:function(a){var l=Math.hypot(a[0],a[1],a[2])||1;return[a[0]/l,a[1]/l,a[2]/l];}};
