 function routePoint12MQ(f,t){t=(t%1+1)%1;if(!f._distanceCache){var lengths=[],total=0;for(var j=1;j<f.points.length;j++){var l=V.len(V.sub(f.points[j],f.points[j-1]));lengths.push(l);total+=l;}f._distanceCache={lengths:lengths,total:total};}var d=t*f._distanceCache.total;for(var j=0;j<f._distanceCache.lengths.length;j++){var l=f._distanceCache.lengths[j];if(d<=l)return V.add(f.points[j],V.mul(V.sub(f.points[j+1],f.points[j]),l?d/l:0));d-=l;}return f.points[f.points.length-1].slice();}

 function configureScrewUI12MQ(){var screw=state.model&&state.model.kind==='screw';$('ci-screw-lessons').hidden=!screw;$('ci-demo').closest('.ci-group').hidden=!!screw;D.querySelector('label[for="ci-throw"]').textContent=screw?'Assembly / section':'Cylinder / throw';$('ci-isolate').parentNode.lastChild.textContent=screw?'Isolate this assembly':'Focus on this throw';$('ci-focus-cylinder').textContent=screw?'Zoom to assembly':'Zoom to cylinder';D.querySelector('[data-view="side"]').textContent=screw?'Rotor section':'Cylinder section';D.querySelector('label[for="ci-timeline"]').textContent=screw?'Male rotor angle':'Crank angle';$('ci-timeline').setAttribute('aria-label',screw?'Male rotor angle':'Crank angle');$('ci-labels').parentNode.lastChild.textContent=screw?'Assembly labels':'Cylinder labels';$('ci-search').placeholder=screw?'Rotor, oil, slide, coalescer...':'Piston, packing, valve...';var sel=$('ci-oil-circuit');sel.innerHTML=screw?'<option value="all">All oil circuits</option><option value="frame">Oil circulation / injection</option><option value="hydraulic">Hydraulic control oil</option><option value="return">Coalescer bleed / return</option>':'<option value="all">All circuits</option><option value="frame">Circulating frame oil</option><option value="forcefeed">Cylinder / packing force-feed</option><option value="drain">Packing vent / drain boundaries</option>';state.slidePosition=80;state.vi=3;state.demandPump=false;state.economizer=true;$('ci-slide').value='80';$('ci-vi').value='3';$('ci-slide-out').value='80% position';$('ci-vi-out').value='3.00';$('ci-demand').checked=false;$('ci-econ').checked=true;}
 function screwView12MQ(name){var s=state.scene,sec=s.sections[state.throwIndex];if(name==='overview'){camera.target=s.center.slice();camera.distance=s.distance;camera.azimuth=.8;camera.elevation=.38;state.isolate=false;state.oilOnly=false;$('ci-isolate').checked=false;$('ci-oil-only').checked=false;}else if(name==='oil'){camera.target=s.oilView12MP.target.slice();camera.distance=s.oilView12MP.distance;camera.azimuth=.8;camera.elevation=.65;state.oil=true;state.oilOnly=false;state.oilCircuit='all';state.isolate=false;state.gas=false;state.opacity=.05;state.mode='xray';$('ci-oil').checked=true;$('ci-gas').checked=false;$('ci-isolate').checked=false;$('ci-oil-only').checked=false;$('ci-oil-circuit').value='all';$('ci-mode').value='xray';$('ci-opacity').value=5;$('ci-opacity-out').value='5%';}else if(name==='side'||name==='cylinder'){if(name==='side'){state.throwIndex=0;$('ci-throw').value='0';sec=s.sections[0];}camera.target=sec.target.slice();camera.distance=sec.distance;camera.azimuth=.45;camera.elevation=.37;state.isolate=true;state.oilOnly=false;$('ci-isolate').checked=true;$('ci-oil-only').checked=false;if(state.throwIndex===2||state.throwIndex===3){state.oil=true;$('ci-oil').checked=true;}}else if(name==='top'){camera.target=s.center.slice();camera.distance=s.distance*.8;camera.azimuth=0;camera.elevation=1.52;}else if(name==='drive'){camera.target=[0,7,-10];camera.distance=105;camera.azimuth=PI;camera.elevation=.2;}markDirty();}
