 var frickControls=D.createElement('div');frickControls.id='ci-screw-lessons';frickControls.className='ci-group';frickControls.hidden=true;frickControls.innerHTML='<label for="ci-slide">Capacity-slide position <output id="ci-slide-out">80% position</output></label><input id="ci-slide" type="range" min="0" max="100" step="5" value="80"><label for="ci-vi">Volume-ratio lesson <output id="ci-vi-out">3.00</output></label><input id="ci-vi" type="range" min="2" max="4.1" step=".1" value="3"><label class="ci-check"><input id="ci-demand" type="checkbox">Demand oil-pump demonstration</label><label class="ci-check"><input id="ci-econ" type="checkbox" checked>Dry economizer-vapor example</label><p class="ci-mini">Separate teaching positions, not live plant commands or calibrated capacity. Oil cooling and filter arrangement reuse existing records; dynamic splits are illustrative.</p>';$('ci-demo').closest('.ci-group').after(frickControls);
