 // 12MS: source-qualified Sundyne vertical integrally geared regeneration-compressor trainer.
 function buildSundyne12MS(model){
  var out={model:model,meshes:[],parts:{},moving:[],throws:[],labels:[],flow:[],productRoutes12MR:[],oilRoutes12MP:[],oilFlow12MP:[],R:2.2,L:9,extent:38,zLength:55,center:[0,6,0],distance:78,ratioBasis:'Qualitative pressure/temperature rise only; no installed performance calculation'};
  var C={body:[.15,.42,.56],metal:[.68,.76,.81],shaft:[.80,.85,.88],gear:[.77,.61,.27],pinion:[.40,.72,.82],gas:[.18,.76,.96],hot:[1,.42,.14],oil:[.98,.71,.16],seal:[.63,.45,.86],dark:[.12,.20,.25],white:[.91,.97,1],green:[.25,.82,.61]};
  function part(id,name,role,motion,sec,source){var k=model.owner+':training:'+id;out.parts[k]={id:k,name:name,type:id,role:role,motion:motion||'Stationary',sourceId:source||'sundyne-lmc-12ms',throwIndex:sec==null?null:sec,ownerKey:model.owner,manufacturerPartNumber:null,installedRating:null,drawingItem:null,evidence:[],verificationStatus:'GENERIC_SUNDYNE_TRAINING_NOT_INSTALLED_BOM',referenceClass:'Operator-confirmed vertical Sundyne arrangement / generic OEM mechanism'};return k;}
  function mesh(g,m,col,id,layer,sec,alpha){var n={g:g,m:m,color:(C[col]||col).slice(),part:id,layer:layer||'solid',throwIndex:sec==null?null:sec,baseAlpha:alpha==null?1:alpha,alpha:alpha==null?1:alpha,visible:true,pick:true,metal:/metal|shaft|gear|pinion/.test(col)?.72:.28};out.meshes.push(n);return n;}
  function box(id,p,s,col,layer,sec,a){return mesh(geometry('box'),matrix(p,s),col,id,layer,sec,a);}
  function cyl(id,a,b,r,col,layer,sec,alpha,tube){return mesh(geometry(tube?'tube':'cylinder',24,tube||undefined),segment(a,b,r),col,id,layer,sec,alpha);}
  function sphere(id,p,r,col,layer,sec,a){return mesh(geometry('sphere',10,7),matrix(p,[r,r,r]),col,id,layer,sec,a);}
  function rotY(p,s,a){var c=Math.cos(a),n=Math.sin(a);return[c*s[0],0,-n*s[0],0,s[1],0,n*s[2],0,c*s[2],p[0],p[1],p[2]];}
  function path(id,name,pts,phase,col,sec,radius,circuit){var k=part(id,name,'Functional teaching path; spatial route and diameter are illustrative.','Moving explanatory markers',sec,'sundyne-lmc-12ms');out.parts[k].circuit=circuit||'process';var members=[];for(var j=1;j<pts.length;j++)members.push(cyl(k,pts[j-1],pts[j],radius,col,circuit?'lube':'flowpipe',sec,.78));pts.forEach(function(p){members.push(sphere(k,p,radius*1.12,col,circuit?'lube':'flowpipe',sec,.82));});var route={part:k,name:name,points:pts.map(function(p){return p.slice();}),phase:phase,radius:radius,throwIndex:sec,active:function(){return true;}};if(circuit){route.circuit=circuit;out.oilRoutes12MP.push({part:k,name:name,points:route.points,circuit:circuit,active:route.active});members.forEach(function(n){n.layer='lube';n.circuit=circuit;});}else out.productRoutes12MR.push(route);return k;}
  var skid=part('skid','C-1111 package support','Supports the vertical motor, gearbox and gas end. Dimensions are schematic.','Stationary',null);box(skid,[0,-13,0],[24,1.3,24],'dark');
  var casing=part('gas-casing','Pressure casing and collector','Contains the impeller, diffuser and collector. Transparent view is a teaching aid, not a window in the real casing.','Stationary',0);cyl(casing,[0,-10,0],[0,1,0],8.2,'body','shell',0,.13);cyl(casing,[0,-8,0],[0,-1,0],6.8,'body','shell',0,.12);for(var a=0;a<12;a++){var q=a*TAU/12;box(casing,[7.1*Math.cos(q),-3,7.1*Math.sin(q)],[.45,6,.28],'metal','shell',0,.16);}
  var inlet=part('suction-nozzle','Regeneration-gas suction / line330 boundary','Scrubbed regeneration gas enters from V-1418 through the retained suction boundary.','Stationary',0);cyl(inlet,[0,-5,20],[0,-5,7],2.4,'gas','flowpipe',0,.35);cyl(inlet,[0,-5,21],[0,-5,19],3.3,'metal','solid',0,1,.72);
  var outlet=part('discharge-nozzle','Compressed-gas discharge boundary','Discharge continues to the retained return choices before F-1412; no fixed branch split is imposed.','Stationary',0);cyl(outlet,[7,-2,0],[20,-2,0],1.9,'hot','flowpipe',0,.38);cyl(outlet,[19,-2,0],[21,-2,0],2.8,'metal','solid',0,1,.70);
  var shaft=part('high-speed-shaft','High-speed pinion and impeller shaft','Carries the pinion and overhung centrifugal impeller. Exact speed, criticals and dimensions are not assigned.','High-speed rotation',0);cyl(shaft,[0,-8,0],[0,8,0],.72,'shaft','solid',0);
  var imp=part('impeller','Overhung centrifugal impeller','Shaft work accelerates the gas; the impeller raises total pressure and temperature. Blade geometry is illustrative.','High-speed rotation',0);var hub=cyl(imp,[0,-8.8,0],[0,-6.7,0],2.25,'pinion','solid',0);var blades=[];for(var j=0;j<10;j++){var q=j*TAU/10,b=box(imp,[3.6*Math.cos(q),-7.6,3.6*Math.sin(q)],[5.5,.45,1.05],'pinion','solid',0);blades.push({m:b,q:q});}
  var diffuser=part('diffuser','Diffuser vanes and pressure recovery','Slows the high-velocity gas and converts part of velocity head into static pressure.','Stationary',0);for(var j=0;j<14;j++){var q=j*TAU/14;box(diffuser,[6.1*Math.cos(q),-5.8,6.1*Math.sin(q)],[2.6,.45,.30],'metal','solid',0);}
  var motor=part('motor','Top-mounted electric motor','Drives the low-speed input shaft. Motor plate and exact rotor construction remain in the existing owner record.','Rotating rotor inside stationary frame',2);cyl(motor,[0,19,0],[0,31,0],5.2,'body','shell',2,.18);for(var j=0;j<18;j++){var q=j*TAU/18;box(motor,[5.25*Math.cos(q),25,5.25*Math.sin(q)],[.22,10,.42],'metal','solid',2);}
  var motorRotor=cyl(motor,[0,18,0],[0,31,0],1.3,'shaft','solid',2),fanBlades=[];for(var j=0;j<7;j++){var q=j*TAU/7,bb=box(motor,[2.5*Math.cos(q),30.2,2.5*Math.sin(q)],[3.3,.25,.65],'metal','solid',2);fanBlades.push({m:bb,q:q});}
  var gearbox=part('gearbox','Pressurized integrally geared gearbox','Motor input drives a bull gear and offset high-speed pinion. Exact ratio, tooth form and bearing type are unverified.','Stationary housing / rotating gears',1);box(gearbox,[0,10,0],[18,9,16],'body','shell',1,.12);box(gearbox,[0,10,-8.1],[18,9,.5],'metal','shell',1,.17);
  var bull=part('bull-gear','Low-speed bull gear','Transfers motor torque to the high-speed pinion. Tooth count and ratio are illustrative.','Rotating with input shaft',1);var bullDisc=cyl(bull,[0,9.2,0],[0,10.8,0],6,'gear','solid',1),bullTeeth=[];for(var j=0;j<24;j++){var q=j*TAU/24,t=box(bull,[6.35*Math.cos(q),10,6.35*Math.sin(q)],[.65,1.8,.45],'gear','solid',1);bullTeeth.push({m:t,q:q});}
  var pin=part('pinion','High-speed pinion','Meshes with the bull gear and drives the compressor shaft. Ratio is not a real unit value.','Counter-rotating high-speed teaching motion',1);var pinDisc=cyl(pin,[5.6,9.2,0],[5.6,10.8,0],2.25,'pinion','solid',1),pinTeeth=[];for(var j=0;j<14;j++){var q=j*TAU/14,t=box(pin,[5.6+2.55*Math.cos(q),10,2.55*Math.sin(q)],[.48,1.8,.34],'pinion','solid',1);pinTeeth.push({m:t,q:q});}
  var coupling=part('coupling','Motor-to-input coupling','Transmits motor torque into the gearbox.','Rotating',2);cyl(coupling,[0,15,0],[0,19,0],1.7,'metal','solid',2);
  var bearings=part('bearings','Input and high-speed bearing groups','Support radial and thrust loads. Exact ball/roller/journal configuration is not established.','Inner members rotate; outer supports stationary',1);[[-0.0,14],[0,6],[5.6,13],[0,-2]].forEach(function(p){cyl(bearings,[p[0],p[1]-.45,0],[p[0],p[1]+.45,0],1.45,'metal','solid',1,1,.72);});
  var seal=part('shaft-seal','Gas-end shaft seal boundary','Separates process gas from the gearbox; exact seal technology and materials require the vendor package.','Rotating/stationary sealing interface',4);cyl(seal,[0,-2.5,0],[0,-.5,0],1.8,'seal','solid',4,1,.72);cyl(seal,[0,-2.4,0],[0,-.6,0],.95,'shaft','solid',4);
  var sump=part('oil-sump','Gearbox oil sump','Reservoir for the pressurized gearbox-lube teaching circuit. No installed capacity or oil grade is assigned here.','Stationary liquid inventory',3);box(sump,[-7,4,0],[5,3,8],'dark','solid',3);var pump=part('lube-pump','Gearbox lube pump','Circulates oil through filter/cooler to bearings and gear mesh. Exact installed pump arrangement is unverified.','Illustrative rotating gears',3);cyl(pump,[-10,5,0],[-8,5,0],1.6,'gear','solid',3);var filter=part('oil-filter','Lube-oil filter','Removes particles before the pressurized oil reaches gears and bearings.','Stationary',3);cyl(filter,[-11,9,-4],[-11,15,-4],1.45,'metal','solid',3);var cooler=part('oil-cooler','Lube-oil cooler','Removes friction and compression-related heat from the gearbox oil circuit.','Stationary heat exchanger role',3);box(cooler,[-11,12,5],[4,7,2.4],'metal','solid',3);
  path('oil-supply','Sump -> pump -> filter -> cooler -> bearing gallery',[[-7,5,0],[-10,5,0],[-11,9,-4],[-11,12,5],[-4,13,5],[0,13,0],[5.6,13,0]],'liquid','oil',3,.22,'gearbox');
  path('oil-return','Bearings / gear mesh -> sump',[[5.6,8,0],[2,5,0],[-7,5,0]],'liquid','oil',3,.20,'return');
  path('seal-supply','Clean dry seal-gas boundary -> shaft seal',[[-16,2,-6],[-8,2,-6],[-3,0,-3],[0,-1,0]],'vapor','seal',4,.20,'seal');
  path('seal-vent','Mechanical-seal vent1761 -> qualified safe-location boundary',[[0,-1,0],[-3,-1,-4],[-12,-1,-4]],'vapor','seal',4,.16,'drain');
  path('regen-suction','V-1418 / line330 -> impeller eye',[[0,-5,24],[0,-5,10],[0,-7,2]],'vapor','gas',0,.46,null);
  var spiral=[];for(var j=0;j<=28;j++){var u=j/28,q=1.2+u*5.0,a=-1.4+u*5.2;spiral.push([q*Math.cos(a),-7+u*1.2,q*Math.sin(a)]);}path('impeller-flow','Impeller eye -> rotating passages -> diffuser',spiral,'vapor','gas',0,.38,null);
  path('regen-discharge','Collector -> discharge -> retained return branches',[[6,-5,0],[9,-3,0],[20,-2,0],[24,-2,0]],'vapor','hot',0,.42,null);
  out.moving.push(function(a){motorRotor.m=segment([0,18,0],[0,31,0],1.3);bullDisc.m=segment([0,9.2,0],[0,10.8,0],6);pinDisc.m=segment([5.6,9.2,0],[5.6,10.8,0],2.25);bullTeeth.forEach(function(t){var q=t.q+a*.35;t.m.m=rotY([6.35*Math.cos(q),10,6.35*Math.sin(q)],[.65,1.8,.45],-q);});pinTeeth.forEach(function(t){var q=t.q-a*1.25;t.m.m=rotY([5.6+2.55*Math.cos(q),10,2.55*Math.sin(q)],[.48,1.8,.34],-q);});blades.forEach(function(t){var q=t.q+a*1.25;t.m.m=rotY([3.6*Math.cos(q),-7.6,3.6*Math.sin(q)],[5.5,.45,1.05],-q);});fanBlades.forEach(function(t){var q=t.q+a*.35;t.m.m=rotY([2.5*Math.cos(q),30.2,2.5*Math.sin(q)],[3.3,.25,.65],-q);});});
  out.sections=[{target:[0,-5,0],distance:48},{target:[2.5,10,0],distance:52},{target:[0,25,0],distance:44},{target:[-8,10,1],distance:48},{target:[0,0,0],distance:38}];out.sections.forEach(function(s){out.throws.push({section:s,ce:0,he:1,z:0,side:1});});out.oilView12MP={target:[-7,10,0],distance:52};out.processView12MR={target:[2,-3,1],distance:55};
  out.labels=[{text:'C-1111 / vertical Sundyne arrangement',p:[0,34,0],throwIndex:2},{text:'SUCTION / V-1418 /330',p:[0,-2,22],throwIndex:0},{text:'DISCHARGE /331-332 returns',p:[23,1,0],throwIndex:0},{text:'Bull gear / pinion',p:[2,17,0],throwIndex:1},{text:'Pressurized gearbox oil',p:[-10,17,2],throwIndex:3,circuit:'gearbox'},{text:'Seal gas / vent boundary',p:[-11,4,-6],throwIndex:4,circuit:'seal'}];
  out.coverage12MP=[['Source and owner','One existing C-1111. Operator-confirmed vertical Sundyne motor-on-top arrangement; retained M2115 routes and C-1111 dossier remain authoritative.'],['Moving internals','Motor/input shaft, bull gear, pinion/high-speed shaft, bearings and centrifugal impeller. Exact model, tooth count, ratio, rotor dynamics and clearances are not assigned.'],['Gas process','Scrubbed regeneration gas enters from V-1418, receives shaft work, then diffuser/collector pressure recovery before the retained return branches. Gas is shown as vapor.'],['Support systems','Qualified pressurized gearbox-oil and separate seal-gas/vent lessons. Exact lube console and seal technology require the vendor package.'],['Not established','Installed catalog model, performance curve, impeller, gear ratio, bearings, seals, materials, tube schedule, part numbers and ratings remain pending.']];
  out.processSteps12MR=[];
  out.update=function(a,o){out.moving.forEach(function(fn){fn(a,o);});out.meshes.forEach(function(n){n.visible=!(o.isolate&&n.throwIndex!=null&&n.throwIndex!==o.throwIndex);n.alpha=n.baseAlpha;if(n.layer==='shell'){n.visible=n.visible&&o.mode!=='internals';n.alpha=o.mode==='solid'?1:o.opacity;}if(n.layer==='flowpipe'||n.layer==='flow')n.visible=n.visible&&o.gas;if(n.layer==='lube')n.visible=n.visible&&o.oil&&(o.oilCircuit==='all'||n.circuit===o.oilCircuit);if(o.oilOnly&&n.layer!=='lube')n.visible=false;});};out.update(.6,{mode:'xray',opacity:.12,gas:true,oil:false,oilCircuit:'all',throwIndex:0});return out;
 }
 function configureSundyneUI12MS(){var on=state.model&&state.model.kind==='sundyne';if(!on)return;$('ci-screw-lessons').hidden=true;$('ci-pump-lessons').hidden=true;$('ci-condensate-wrap').hidden=true;$('ci-demo').closest('.ci-group').hidden=true;D.querySelector('label[for="ci-throw"]').textContent='Assembly / section';$('ci-isolate').parentNode.lastChild.textContent='Isolate this assembly';$('ci-focus-cylinder').textContent='Zoom to assembly';D.querySelector('[data-view="side"]').textContent='Gas-end section';D.querySelector('label[for="ci-timeline"]').textContent='Teaching shaft angle';$('ci-timeline').setAttribute('aria-label','Sundyne teaching shaft angle');$('ci-labels').parentNode.lastChild.textContent='Assembly labels';$('ci-search').placeholder='Impeller, bull gear, pinion, seal, oil...';$('ci-oil-circuit').innerHTML='<option value="all">All support circuits</option><option value="gearbox">Gearbox pressure oil</option><option value="return">Oil return</option><option value="seal">Seal gas / vent</option><option value="drain">Qualified drain / vent boundaries</option>';}
