  if(/bearing|crosspin|pin.bushing|oil.film|guiding.surface|thrust.*bearing/.test(text))return 'bearings';
  if(c==='frame'||c==='return'||c==='gearbox'||/oil.sump|oil.filter|oil.cooler|oil.pump|oil.strainer|pre.lube|breather|sightglass|oiler|oil.ring/.test(text))return 'oil';
  if(/coupling|motor|shaft|crank|connecting.rod|conrod|crosshead|piston|impeller|rotor|bull.gear|pinion|expander.wheel|stretch.rod|chain/.test(text)&&!/housing|casing|guard|guide/.test(text))return 'motion';
  if(/suction|discharge|gas|propane|product|liquid|gallery|manifold|diffuser|volute|clearance|head.end|valve|cylinder|barrel|coalescer|separator|flow|screen|inlet|outlet|nozzle|pocket|check|throat|wear.ring|bottle|scrubber/.test(text)||c==='process'||c==='product'||c==='propane')return 'process';
