 el('strong',S.title,box);el('p','20 new practical questions linked to the existing PetroSkills notes. The re-upload matches the retained source exactly: no duplicate chapter or engineering facts were added.',box);
 var b=el('button','Practice: PetroSkills pumps (20)',box);b.type='button';b.style.cssText='min-height:36px;padding:7px 12px;white-space:normal';b.onclick=cfStartPumpPractice12MI;
