 // Longitudinal seams stay on the side faces, not across nozzle penetrations.
 [-1,1].forEach(function(s){K.box(len-.8,.018,.013,0,.28,s*Math.sqrt(r*r-.28*.28),M.edge,'longitudinal-jacket-seam');});
 [-1,1].forEach(function(s){var sx=s*(len/2-.018);K.ring(r+.006,.017,sx,0,0,M.edge,'x','head-seam');});
 // Retain original thin support heights; detailed feet meet the inherited raised deck.
 var legH=r+1+liftY;
 [-1,1].forEach(function(s){K.box(.25,legH,.9,s*len*.28,-legH/2,0,M.edge,'primary-support',true);K.box(.70,.10,1.20,s*len*.28,-r+.01,0,M.edge,'saddle-foot');[-.26,.26].forEach(function(dx){[-.46,.46].forEach(function(dz){K.cyl(.042,.08,s*len*.28+dx,-r+.07,dz,M.bolt,'y','saddle-fastener');});});});
