function cfProductCooler12IC(k,x,z,mat,nfan){
 var w=nfan*4.2,K=cfNglParts12IC(k,x,0,z,0),M=K.m;pad(x,z,w+3,10);
 // Original 8.4 x 3.6 x 7.5 outer frame extent retained, now open rather than a solid box.
 [-1,1].forEach(function(s){K.box(w,.16,.18,0,5.78,s*3.66,M.edge,'primary-frame',true);K.box(w,.16,.18,0,9.22,s*3.66,M.edge,'primary-frame',true);K.box(.18,3.6,7.5,s*(w/2-.09),7.5,0,M.edge,'primary-header-box',true);});
 K.box(w-.6,2.7,6.65,0,7.5,0,M.dark,'primary-core',true);
 // Finned bundle fascia, separate panels and regular tube-fin accents.
 [-1,1].forEach(function(s){for(var i=0;i<27;i++)K.box(.045,2.66,.09,-w/2+.38+i*(w-.76)/26,7.5,s*3.375,M.fin,'bundle-fin');[-2,0,2].forEach(function(px){K.box(.08,3.28,.12,px,7.5,s*3.59,M.edge,'bundle-panel-divider');});});
 [-1,1].forEach(function(s){for(var i=0;i<6;i++)[-1,1].forEach(function(v){K.cyl(.044,.075,s*(w/2+.038),6.08+i*.57,v*3.36,M.bolt,'x','header-fastener');});});
 // Two distinct horizontal fan rotors. Rotation is visual-only and reads existing red-tag availability.
 for(var i=0;i<nfan;i++){
  var fx=-w/2+2.1+i*4.2;
  K.ring(1.7,.10,fx,9.6,0,M.edge,'y','fan-shroud',true);
  var rotor=new THREE.Group();rotor.position.set(fx,9.6,0);K.g.add(rotor);rotor.userData.key=k;
  K.cyl(.22,.25,0,0,0,M.bolt,'y','fan-hub',true,rotor);
  for(var b=0;b<4;b++){var a=b*Math.PI/2,blade=K.box(1.20,.065,.28,Math.cos(a)*.83,0,Math.sin(a)*.83,M.alt,'fan-blade',false,rotor);blade.rotation.y=-a;}
  // Low-profile cage hoops and crossbars stay above the sweep, never through the rotor.
  [.65,1.15,1.64].forEach(function(rad){K.ring(rad,.014,fx,9.81,0,M.fin,'y','fan-guard');});
  K.box(3.28,.03,.032,fx,9.81,0,M.fin,'guard-crossbar');K.box(.032,.03,3.28,fx,9.81,0,M.fin,'guard-crossbar');
  K.record.fans.push({rotor:rotor,index:i,redTagKey:'a1322fan'+(i+1),running:false});
 }
 // Manual louver representation in the side fascia; no new louver controller or unknown motor.
 [-1,1].forEach(function(s){for(var j=0;j<8;j++){var blade=K.box(w-.7,.12,.18,0,6.2+j*.35,s*3.58,M.alt,'manual-louver');blade.rotation.x=s*.18;}});
 var GY=-1.9,legTop=5.7,legH=legTop-GY;
 [-1,1].forEach(function(a){[-1,1].forEach(function(b){K.box(.3,legH,.3,a*(w/2-.6),(legTop+GY)/2,b*3.4,M.edge,'primary-leg',true);K.box(.64,.10,.64,a*(w/2-.6),GY+.03,b*3.4,M.edge,'foot-plate');[-.23,.23].forEach(function(dx){[-.23,.23].forEach(function(dz){K.cyl(.038,.09,a*(w/2-.6)+dx,GY+.12,b*3.4+dz,M.bolt,'y','foot-bolt');});});});});
 K.plaque('A-1322','DEMETHANIZED PRODUCT COOLER',5.4,.78,0,6.03,3.79,0);
 // Reproduce the three original connection objects exactly (including legacy top interface).
 var nozM=new THREE.MeshStandardMaterial({color:0x3a3f46,roughness:.4,metalness:.5});
 [[x-w/2,7.5,z,0],[x+w/2,7.5,z,Math.PI],[x,9.6,z,0]].forEach(function(p,idx){var rr=idx<2?.4:.22,ll=idx<2?2.2:1.1,stub=new THREE.Mesh(cfCylinderGeometry12JG(rr,rr,ll,12),nozM);if(idx<2){stub.rotation.z=Math.PI/2;stub.position.set(p[0]+(idx===0?-ll/2:ll/2),p[1],p[2]);}else stub.position.set(p[0],p[1]+ll/2,p[2]);add(stub,k);var fl=new THREE.Mesh(cfTorusGeometry12JG(rr*1.1,.035,6,14),mFlange);if(idx<2){fl.rotation.y=Math.PI/2;fl.position.set(p[0]+(idx===0?-ll:ll),p[1],p[2]);}else{fl.rotation.x=Math.PI/2;fl.position.set(p[0],p[1]+ll,p[2]);}add(fl,k);});
 K.record.envelope={width:w,height:3.6,depth:7.5,center:[x,7.5,z],fanCount:nfan};
 return {inlet:new THREE.Vector3(x-w/2-2.2,7.5,z),outlet:new THREE.Vector3(x+w/2+2.2,7.5,z),top:new THREE.Vector3(x,10.7,z)};
}
function cfUpdateNGLVisual12IC(dt){
 if(typeof PLANT==='undefined'||!PLANT)return;
 CF_NGL_VISUALS_12IC.forEach(function(r){r.fans.forEach(function(f){f.running=!(PLANT.redtag&&PLANT.redtag[f.redTagKey]);if(f.running)f.rotor.rotation.y=(f.rotor.rotation.y+Math.min(.1,Math.max(0,Number(dt)||0))*3.8)%(Math.PI*2);});});
}
