 var th=new THREE.Mesh(cfSphereGeometry12JG(r*0.86,26,16),mat); th.scale.y=0.55; th.position.set(x,h-1.5+GY,z); add(th,k);
 var bh=new THREE.Mesh(cfSphereGeometry12JG(r*0.9,26,16),mat); bh.scale.y=0.55; bh.position.set(x,2.5+GY,z); add(bh,k);
 /* Head-to-shell seam rings, same reasoning as bVert/bHoriz above. */
 [h-1+GY,3+GY].forEach(function(sy){var sr=new THREE.Mesh(cfTorusGeometry12JG(r*0.86*0.98,r*0.045,6,26),mFlange); sr.rotation.x=Math.PI/2; sr.position.set(x,sy,z); add(sr,k); boltRing(x,sy,z,r*0.86*0.98,'y',k);});
 /* Platforms previously were bare flat discs with nothing around the edge --
    real access platforms have a guardrail (top + mid rail on posts) around the
    open perimeter; without it they read as floating pancakes, not something
    anyone could actually stand on. */
 var railM=new THREE.MeshStandardMaterial({color:0x2e343c,roughness:0.6,metalness:0.6});
 [0.35,0.55,0.75].forEach(function(f){
  var py=3+f*(h-6)+GY;
  var p=new THREE.Mesh(cfCylinderGeometry12JG(r*1.1,r*1.1,0.1,24),mSteel); p.position.set(x,py,z); add(p,k);
  var postN=10;
  for(var pi=0;pi<postN;pi++){
   var pa=(pi/postN)*Math.PI*2;
   var post=new THREE.Mesh(cfCylinderGeometry12JG(0.025,0.025,0.9,6),railM);
   post.position.set(x+Math.cos(pa)*r*1.1,py+0.45,z+Math.sin(pa)*r*1.1); add(post,k);
  }
  [0.28,0.85].forEach(function(ry){var rail=new THREE.Mesh(cfTorusGeometry12JG(r*1.1,0.018,5,24),railM); rail.rotation.x=Math.PI/2; rail.position.set(x,py+ry,z); add(rail,k);});
 });
 /* caged access ladder up one side */
 var lad=new THREE.Mesh(cfCylinderGeometry12JG(r*1.12,r*1.12,h-4,10,1,true,0,0.5),new THREE.MeshStandardMaterial({color:0x2e343c,roughness:0.7,transparent:true,opacity:0.35,side:THREE.DoubleSide}));
 lad.position.set(x,h/2+1+GY,z); add(lad,k);
