 var actions=el('div',null);actions.style.cssText='display:flex;gap:8px;flex-wrap:wrap';
 var card=el('button','Open C-1111 equipment card',actions);card.type='button';card.onclick=function(){cfRefOpenSource({type:'info',key:'c1111'});};
 if(typeof cfRefFlyButton==='function')cfRefFlyButton('c1111',host);
