 var links=el('details',null);el('summary','Manufacturer research and source limits',links);S.research.forEach(function(r){var p=el('p',null,links),a=el('a',r.publisher+' - '+r.id,p);a.href=r.url;a.target='_blank';a.rel='noopener noreferrer';el('p',r.scope+' Reviewed '+r.accessed+'.',links);});
