  connections:extra.connections||(isPsv?v.connectionReference||'':''),failPosition:extra.failPosition||'',
  setPressure:extra.setPressure||(isPsv&&v.setPsig!=null?String(v.setPsig)+' psig (source reference only)':''),
  source:extra.source||v.source||'',status:extra.status||v.status||v.identityStatus||'SOURCE DATA PENDING',
