function cf3dEnsureReferenceValves12GU(){
 [['XV-1711A','cf3d_cv_xv1711a','H-1711 regeneration heater HEAT-path valve'],
  ['XV-1711B','cf3d_cv_xv1711b','H-1711 regeneration heater bypass / COOL-path valve']].forEach(function(def){
  var same=Object.keys(CF3D_DEVICE_RECORDS).filter(function(k){return cf3dDeviceNorm(CF3D_DEVICE_RECORDS[k].tag)===cf3dDeviceNorm(def[0]);});
  if(same.length)return; // Existing identity always wins; do not create another record.
  var r=cf3dRegisterDeviceRecord({key:def[1],tag:def[0],kind:'sequence',equipment:'H-1711',service:def[2],aliases:[def[0].toLowerCase().replace(/-/g,'')]},false);
  r.referenceRecordOnly=true;r.parentAssetId='h1711';
 });
}
