 var full=false,zoom=document.createElement('button');zoom.type='button';zoom.textContent='Actual size';zoom.onclick=function(){full=!full;img.style.width=full?src.width+'px':'100%';zoom.textContent=full?'Fit width':'Actual size';};head.appendChild(zoom);
