function cf3dDeviceKnowledge12GI(question){
 if(typeof CF3D_DEVICE_RECORDS==='undefined')return '';
 var q=String(question||'');
 if(typeof cf3dVerificationKnowledge12HH==='function'){var verification=cf3dVerificationKnowledge12HH(q);if(verification)return verification;}
 var exact=[],general=/\bpsvs?\b|pressure safety valves?/i.test(q)&&/set\s*(?:points?|pressure)|list|all|information|info/i.test(q);
 Object.keys(CF3D_DEVICE_RECORDS).forEach(function(k){var r=CF3D_DEVICE_RECORDS[k];if(!r.tagConfirmed)return;var matched=[r.tag].concat(r.aliases||[]).filter(function(t){return /^[A-Z][A-Z0-9]*-\d+[A-Z0-9-]*$/i.test(t);}).some(function(t){var tokens=t.toUpperCase().match(/[A-Z]+|[0-9]+[A-Z]*/g)||[];var rx=new RegExp('\\b'+tokens.join('[\\s-]*')+'\\b','i');return rx.test(q);});if(matched)exact.push(r);});
 if(/\bPSV[\s-]*101\b/i.test(q)&&CF3D_DEVICE_RECORDS.cf3d_psv_1321&&exact.indexOf(CF3D_DEVICE_RECORDS.cf3d_psv_1321)<0)exact.push(CF3D_DEVICE_RECORDS.cf3d_psv_1321);
 // Explicit service names retrieve their existing record; a mistyped numeric tag is not an alias.
 function includeDescriptionDevice(key){var r=CF3D_DEVICE_RECORDS[key];if(r&&exact.indexOf(r)<0)exact.push(r);}
 if(/\bGSP\b|\bOrtloff\b/i.test(q))includeDescriptionDevice('cf3d_cv_fcv1222');
 if(/\bJ[\s-]*T\b|\bJoule[\s-]*Thomson\b/i.test(q))includeDescriptionDevice('cf3d_cv_pcv1121a');
 // 12HH: corrected anti-surge tag and service resolve to one existing component.
 if(/\banti[\s-]*surge\b|\bantisurge\b/i.test(q))includeDescriptionDevice('cf3d_fcv1211a');
 // 12HA: named service retrieves the same source-labelled, photo-backed valve.
 if(/\bcold[\s-]*spin\b|\bsnowball(?:ing)?\b/i.test(q))includeDescriptionDevice('cf3d_tcv1421');
 // 12HD: source retrieval only. A descriptive reference to 1222B is not a new device.
 if(/\b1222\s*B\b/i.test(q)&&/\b(?:valve|pdcv|pdic|differential|diff|dp)\b/i.test(q))includeDescriptionDevice('cf3d_cv_pdcv1222b');
 // 12HE: specific operator service or loop number retrieves the same blowdown record.
 if((/\b1121\s*E\b/i.test(q)&&/\b(?:valve|pcv|pic|blow[ -]*down|pressure)\b/i.test(q))||(/\b(?:high[ -]*pressure|tower|plant)\b/i.test(q)&&/\bblow[ -]*down\b/i.test(q)&&/\bvalve\b/i.test(q)))includeDescriptionDevice('cf3d_cv_pcv1121e');
 // 12HF: operator-named RSV pressure service retrieves the existing pressure valve,
 // never the distinct FCV-1438 flow valve or an inferred new device.
 if(/\bPIC[\s-]*1438\b/i.test(q)||(/\bRSV\b/i.test(q)&&/\bpressure[ -]*(?:control(?:ler)?|valve)\b/i.test(q)&&!/\bFCV[\s-]*1438\b/i.test(q)))includeDescriptionDevice('cf3d_cv_pcv1438');
 // 12HG: retrieve the operator-identified NGL valve without merging the two outlets.
 if(/\b1623\b/i.test(q)&&/\b(?:valve|pressure|pcv|pic|outlet|liquid)\b/i.test(q))includeDescriptionDevice('cf3d_cv_pcv1623');
 if(/\bNGL\b/i.test(q)&&/\boutlet\b/i.test(q)&&/\bpressure\b/i.test(q)&&/\bvalves?\b/i.test(q)&&!/\b(?:PCV|PV|PIC)[\s-]*162[34]\b/i.test(q)&&!/\b162[34]\b/.test(q)){includeDescriptionDevice('cf3d_cv_pcv1623');includeDescriptionDevice('cf3d_cv_pcv1624');}
 // A full photographed serial can retrieve its existing record, never a nearby number.
 Object.keys(CF3D_DEVICE_RECORDS).forEach(function(k){var r=CF3D_DEVICE_RECORDS[k];if(!r.photoIds||!r.photoIds.length)return;var serials=String(r.serial||'').match(/\b(?:F\d{8,}|\d{7,}(?:\.\d+)?|P\d{6,}(?:-\d+)?)\b/g)||[];if(serials.some(function(sn){return new RegExp('(^|[^A-Z0-9])'+sn.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?=$|[^A-Z0-9])','i').test(q);}))includeDescriptionDevice(k);});
 // Compact index for broad questions; individual full records remain available by tag.
 var nameplateList=!exact.length&&!general&&/\b(?:all|list|which|new|recent|uploaded|added|have)\b/i.test(q)&&/\b(?:nameplates?|valve\s+(?:info(?:rmation)?|data|records?|photos?))\b/i.test(q);
 if(nameplateList){
  var named=Object.keys(CF3D_DEVICE_RECORDS).map(function(k){return CF3D_DEVICE_RECORDS[k];}).filter(function(r){return r.kind!=='psv'&&(r.photoIds||[]).length>0;});
  var inventory=['CURRENT PHOTO-BACKED VALVE RECORD INDEX - '+named.length+' records in this build, not a complete facility register. Each row points to one existing component and its original sources. Ask by valve tag for the full nameplate fields, pending items and conflicts. These are source records, not new operating setpoints.'];
  named.forEach(function(r){inventory.push(r.tag+' | '+r.model+' | serial '+r.serial+' | aliases '+(r.aliases||[]).join(', ')+' | sources '+r.photoIds.join(', ')+' | '+r.status);});
  return inventory.join('\n');
 }
 if(!exact.length&&general)exact=Object.keys(CF3D_DEVICE_RECORDS).map(function(k){return CF3D_DEVICE_RECORDS[k];}).filter(function(r){return r.kind==='psv';});
 if(!exact.length)return '';
 var out=['CURRENT DEVICE SOURCE RECORDS - source-labelled reference, NOT a change to live SP/trips. Photo/nameplate CWP and actuator pneumatic range are not operating pressure setpoints. Current device-specific source facts supersede older generic placeholders for that device; disclose conflicts and do not replace pending fields with guesses.'];
 exact.slice(0,general?40:6).forEach(function(r){out.push('\n'+r.tag+' | '+r.kind+' | '+r.service,'P&ID: '+(r.drawings.join(', ')||'PENDING')+'; page '+(r.page||'PENDING')+'; revision '+(r.revision||'PENDING')+'; location '+(r.drawingLocation||'PENDING'),'SOURCE: '+r.source+'; STATUS: '+r.status,'PHYSICAL LOCATION: '+(r.location||r.placement||'PENDING'));
 if(r.kind==='psv')out.push('Protected equipment: '+(r.equipment||'PENDING')+'; PSV set pressure: '+(r.setPressure||'PENDING')+'; sizes: '+(r.connections||'PENDING'),'Discharge: '+(r.discharge||'PENDING')+'; basis '+(r.dischargeStatus||'PENDING')+'; isolation '+(r.isolation||'PENDING'));
 else out.push('Manufacturer/model: '+(r.manufacturer||'PENDING')+' / '+(r.model||'PENDING')+'; serial '+(r.serial||'PENDING')+'; fail position '+(r.failPosition||'PENDING'));
 (r.specifications||[]).forEach(function(p){out.push(p[0]+': '+p[1]);});if(r.conflict)out.push('CONFLICT: '+r.conflict);
 var fd=r.functionalDescription;if(fd&&fd.requestedByOperator===true){out.push('REQUESTED SHORT FUNCTION DESCRIPTION: '+fd.text,'PLANT BASIS: '+fd.plantBasis,'GENERIC RESEARCH BASIS: '+fd.researchBasis);(fd.sourceIds||[]).forEach(function(id){var src=CF3D_DESCRIPTION_SOURCES[id];if(src)out.push('DESCRIPTION SOURCE: '+src.title+' | '+(src.url||src.sourceFile||'Existing Reference Library')+(src.sourcePages?' | '+src.sourcePages:''));});}

 if(typeof RYAN_CACHE!=='undefined'&&RYAN_CACHE){var docs=cf3dExactValveDocuments(r);docs.forEach(function(d){out.push('Linked upload: '+(d.title||d.sourceLabel||d.id));(RYAN_CACHE.proposals||[]).filter(function(p){return p&&p.sourceDocumentId===d.id&&['staged','approved'].indexOf(p.status)>=0&&Array.isArray(p.equipmentIds)&&p.equipmentIds.some(function(t){return cf3dDeviceNorm(t)===cf3dDeviceNorm(r.tag);});}).slice(0,10).forEach(function(p){out.push(String(p.statement||'')+' [source '+(d.title||d.id)+', page '+(p.sourcePage||'PENDING')+', '+(p.verificationStatus||'DOCUMENT_EXTRACTED_UNVERIFIED')+']');});});}
 });return out.join('\n').slice(0,18000);
}
