function ryanQaRestoreThread(){
 if(typeof RYAN_AI_HISTORY==='undefined'||!Array.isArray(RYAN_AI_HISTORY))return;
 RYAN_AI_HISTORY.forEach(function(m){if(m.role!=='assistant'||!m.qaArchiveId)return;var r=RYAN_QA_STATE.rows.find(function(x){return x.id===m.qaArchiveId;});if(r)m.content=ryanQaCurrentDeviceReference12HD(r,r.question);});
}
function ryanQaDbRead(db){return new Promise(function(resolve,reject){libReadStore(db,'answers',function(rows,ok){if(ok)resolve(rows);else reject(new Error('Questions Asked storage read did not complete.'));});});}
function ryanQaDbWrite(db,rows){return new Promise(function(resolve,reject){if(!rows.length){resolve(true);return;}libWriteStore(db,'answers',rows,function(ok){if(ok)resolve(true);else reject(new Error('Questions Asked storage write did not complete.'));});});}
function ryanQaFallbackSave(){
 try{localStorage.setItem(RYAN_QA_FALLBACK_KEY,JSON.stringify(RYAN_QA_STATE.rows));RYAN_QA_STATE.storage='localStorage';RYAN_QA_STATE.warning='IndexedDB is unavailable. Answers are saved in browser localStorage; export a backup regularly.';return true;}
 catch(e){RYAN_QA_STATE.storage='memory';RYAN_QA_STATE.warning='NOT SAVED PERSISTENTLY: browser storage is blocked or full. Export Questions Asked before closing this page.';return false;}
}
function ryanQaPublish(){
 RYAN_QA_STATE.revision++;ryanQaSyncInfo();ryanQaRestoreThread();
 document.querySelectorAll('[data-qa-storage]').forEach(function(el){el.textContent=ryanQaStorageText();});
 try{if(RYAN_QA_STATE.channel)RYAN_QA_STATE.channel.postMessage('changed');}catch(e){}
}
function ryanQaReady(){
 if(RYAN_QA_STATE.promise)return RYAN_QA_STATE.promise;
 ryanQaMerge(ryanQaReadLocal(RYAN_QA_STORE_KEY));ryanQaMerge(ryanQaReadLocal(RYAN_QA_FALLBACK_KEY));
 RYAN_QA_STATE.promise=new Promise(function(resolve){
  var done=false,req=null,timer=setTimeout(function(){finish(null);},3500);
  function finish(db){if(done){if(db)db.close();return;}done=true;clearTimeout(timer);RYAN_QA_STATE.db=db;
   if(!db){ryanQaFallbackSave();ryanQaPublish();resolve();return;}
   db.onversionchange=function(){db.close();RYAN_QA_STATE.db=null;RYAN_QA_STATE.warning='Archive database changed in another tab. Reload this page before further saves.';};
   ryanQaDbRead(db).then(function(rows){var saved=Object.create(null);rows.forEach(function(r){if(r&&r.id)saved[r.id]=r;});ryanQaMerge(rows);var pending=RYAN_QA_STATE.rows.filter(function(r){return !saved[r.id]||Number(r.updatedAt)>Number(saved[r.id].updatedAt||0);});return ryanQaDbWrite(db,pending);})
    .then(function(){RYAN_QA_STATE.storage='indexedDB';RYAN_QA_STATE.warning='';ryanQaPublish();resolve();})
    .catch(function(){ryanQaFallbackSave();ryanQaPublish();resolve();});
  }
  try{req=indexedDB.open('ClearforkRyanQuestionsAsked',1);req.onupgradeneeded=function(e){var db=e.target.result;if(!db.objectStoreNames.contains('answers'))db.createObjectStore('answers',{keyPath:'id'});};req.onsuccess=function(){finish(req.result);};req.onerror=req.onblocked=function(){finish(null);};}catch(e){finish(null);}
 }).then(function(){
  try{if(typeof BroadcastChannel!=='undefined'&&!RYAN_QA_STATE.channel){RYAN_QA_STATE.channel=new BroadcastChannel('ClearforkQuestionsAsked');RYAN_QA_STATE.channel.onmessage=function(){ryanQaReload().then(function(){if(typeof libSel!=='undefined'&&String(libSel.key||'').indexOf('ryanqa_')===0&&document.getElementById('library').style.display==='block')libRenderDetail();});};}}catch(e){}
 });
 return RYAN_QA_STATE.promise;
}
async function ryanQaReload(){
 await ryanQaReady();
 if(RYAN_QA_STATE.db){try{ryanQaMerge(await ryanQaDbRead(RYAN_QA_STATE.db));}catch(e){RYAN_QA_STATE.warning='Could not refresh the shared local archive; showing the last loaded answers.';}}
 else ryanQaMerge(ryanQaReadLocal(RYAN_QA_FALLBACK_KEY));
 ryanQaSyncInfo();ryanQaRestoreThread();
}
async function ryanQaPersist(rows){
 await ryanQaReady();var ok=false;
 if(RYAN_QA_STATE.db){try{await ryanQaDbWrite(RYAN_QA_STATE.db,rows);ok=true;RYAN_QA_STATE.storage='indexedDB';RYAN_QA_STATE.warning='';}catch(e){ok=ryanQaFallbackSave();}}
 else ok=ryanQaFallbackSave();
 ryanQaPublish();return ok;
}
async function ryanQaArchive(question,answer,mode,cost,meta){
 question=String(question||'').trim();answer=String(answer||'');if(!question||!answer.trim())return null;
 await ryanQaReady();meta=meta||{};
 var id=(typeof crypto!=='undefined'&&crypto.randomUUID)?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
 var sh=meta.sharedHistory||null;if(sh&&sh.id)id='shared-'+sh.id;
 var rec=ryanQaNormalizeRecord({schemaVersion:2,id:id,question:question,answer:answer,mode:mode||'qa',answeredAt:meta.answeredAt===null?null:(meta.answeredAt||Date.now()),updatedAt:Date.now(),firstAskedAt:Date.now(),
  sharedId:sh&&sh.id||'',sharedStatus:sh?(sh.saved&&sh.status==='complete'?'saved':'pending'):'',contextKey:meta.contextKey!=null?meta.contextKey:ryanQaContextKey(question),reusable:meta.reusable!==false&&ryanQaEligible(question,mode),partial:!!meta.partial,workplan:meta.workplan||null,
  costUsd:cost&&cost.usd!=null?cost.usd:null,source:meta.source||'Ryan AI',sourceBuild:typeof RYAN_BUILD_ID!=='undefined'?RYAN_BUILD_ID:''});
 ryanQaMerge([rec]);var ok=await ryanQaPersist([rec]);if(!sh&&typeof cfRyanPublishNew12NG==='function')await cfRyanPublishNew12NG(rec);return {record:rec,durable:ok};
}
function ryanQaCachedAnswer(question,mode,contextKey){
 if(!ryanQaEligible(question,mode))return null;
 var norm=ryanQaNorm(question),scope=contextKey!=null?contextKey:ryanQaContextKey(question);
 if(scope==='unresolved-followup')return null;
 var rows=ryanQaLoad().filter(function(r){return r.norm===norm&&/^(qa|qa_fast)$/.test(r.mode)&&r.contextKey===scope&&r.sourceBuild===RYAN_BUILD_ID&&!r.partial&&r.reusable&&!r.reuseDisabled&&r.answer; /*12JT: archive retained, cross-build auto-reuse blocked.*/});
 rows.sort(function(a,b){return Number(b.answeredAt||0)-Number(a.answeredAt||0);});return rows[0]||null;
}
async function ryanQaMarkReused(r){r.reuseCount=(r.reuseCount||0)+1;r.askCount=(r.askCount||1)+1;r.lastReusedAt=Date.now();r.updatedAt=Date.now();return ryanQaPersist([r]);}
function ryanQaStorageText(){return RYAN_QA_STATE.warning||(RYAN_QA_STATE.storage==='indexedDB'?'Saved on this browser/device (IndexedDB).':(RYAN_QA_STATE.storage==='loading'?'Loading saved answers...':'Saved on this browser/device.'));}
function ryanQaStamp(r){return r.answeredAt?new Date(r.answeredAt).toLocaleString():'Original answer date not supplied';}
