 if(typeof LIB_CATS==='undefined'||!LIB_CATS||typeof INFO==='undefined')return;
 if(!force&&RYAN_QA_STATE.synced===RYAN_QA_STATE.revision)return;RYAN_QA_STATE.synced=RYAN_QA_STATE.revision;
 Object.keys(INFO).forEach(function(k){if(k.indexOf('ryanqa_')===0)delete INFO[k];});
 var keys=[RYAN_QA_DOC_KEY];INFO[RYAN_QA_DOC_KEY]={t:'Questions Asked',d:['Saved Ryan questions and answers. Historical AI responses, not verified plant facts. Open this file to search, read, export or import the archive.'],qaArchive:true};
 ryanQaLoad().sort(function(a,b){return Number(b.answeredAt||b.importedAt||0)-Number(a.answeredAt||a.importedAt||0);}).forEach(function(r){var key='ryanqa_'+r.id;keys.push(key);INFO[key]={t:'Q: '+r.question,d:['ARCHIVED AI ANSWER - NOT VERIFIED. '+ryanQaStamp(r),'QUESTION: '+r.question],qaArchive:true,qaRecordId:r.id};});
 var idx=-1;for(var i=0;i<LIB_CATS.length;i++){if(LIB_CATS[i][0]===RYAN_QA_CAT_NAME||LIB_CATS[i][0]==='Questions/Answers Asked to Ryan'){idx=i;break;}}
 if(idx<0)LIB_CATS.push([RYAN_QA_CAT_NAME,keys]);else LIB_CATS[idx]=[RYAN_QA_CAT_NAME,keys];
