function ryanQaInline(text){return ryanQaEsc(text).replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`\n]+)`/g,'<code>$1</code>');}
function ryanQaAnswerHtml(text){
 // Deliberately small, escaped Markdown renderer. Raw HTML never executes.
 var lines=String(text||'').split(/\r?\n/),out=[],code=false,table=false;
 function closeTable(){if(table){out.push('</tbody></table></div>');table=false;}}
 lines.forEach(function(line){
  if(/^```/.test(line)){closeTable();code=!code;out.push(code?'<pre class="qa-code">':'</pre>');return;}
  if(code){out.push(ryanQaEsc(line)+'\n');return;}
  if(/^\s*\|/.test(line)){if(/^\s*\|?[\s:|\-]+\|\s*$/.test(line))return;if(!table){out.push('<div class="qa-tablewrap"><table class="qa-table"><tbody>');table=true;}var cells=line.trim().replace(/^\||\|$/g,'').split('|');out.push('<tr>'+cells.map(function(c){return '<td>'+ryanQaInline(c.trim())+'</td>';}).join('')+'</tr>');return;}
  closeTable();var h=line.match(/^(#{1,6})\s+(.*)$/);if(h){var n=Math.min(5,h[1].length+1);out.push('<h'+n+'>'+ryanQaInline(h[2])+'</h'+n+'>');}
  else if(/^\s*---+\s*$/.test(line))out.push('<hr>');
  else if(/^\s*[-*]\s+/.test(line))out.push('<div class="qa-bullet">&#8226; '+ryanQaInline(line.replace(/^\s*[-*]\s+/,''))+'</div>');
  else out.push(line.trim()?'<div class="qa-line">'+ryanQaInline(line)+'</div>':'<div class="qa-gap"></div>');
 });closeTable();if(code)out.push('</pre>');return out.join('');
}
function ryanQaExpanderRevisionNote(r){
 if(r&&/refrig|suction|1438|1140|1141|1142|9220|5700/i.test(String(r.question||''))&&r.sourceBuild!=='RYAN-2026-10-04-12HN')return '12GA correction (2026-10-02): refrigeration suction pressure is an actual capacity/heat-load response, not a value clipped to SP. In AUTO lower SP requests loading, higher SP unloading; colder feed affects C3 and rejection reboil duty. Current starting lineup is C-1140 only, with C-1141/C-1142, C-5700 and V-9220 stopped. F-1438 change threshold is 10 PSID, existing RSV-path trip 15 PSID. Original answer below remains historical AI output; see Refrigeration Suction / Filter Update in the Reference Library.';

 if(!r||r.sourceBuild==='RYAN-2026-10-04-12HN'||!/expander|\bigv\b|hic.?101|1521d|\bj[ -]?t\b|\bc3\b|propane.*recover|residue.*propane/i.test(r.question||''))return '';
 return '12FY operator correction (2026-10-02): only JT and EX are alternative main gas paths. A stopped expander carries no forward gas; continuing gas uses JT. Usual C3 recovery is 77-85% JT-only versus 95-98% with EX operating normally; more C3 remains in residue on JT. These are operator-observed recovery percentages, not residue C3 concentration or limits. LOCAL 20%, independent board MANUAL match 20%, REMOTE, JT SP below EX SP, then EX AUTO remains the handover. Both controllers regulate tower pressure. Original historical answer retained unchanged.';
}
