 var pending=false;function layout(){if(pending)return;pending=true;requestAnimationFrame(function(){pending=false;cfControlLayout12NB();});}
 if(typeof ResizeObserver!=='undefined'){var ro=new ResizeObserver(layout);ro.observe(root.querySelector('.ehead'));ro.observe(root.querySelector('.ebar'));}
 window.addEventListener('resize',layout,{passive:true});if(window.visualViewport)window.visualViewport.addEventListener('resize',layout,{passive:true});
