  var t=e.target.closest('[data-act]');if(!t||!screen.contains(t))return;var a=t.getAttribute('data-act'),v=CF_SCHEDULE_VIEW_12NB;
  if(a==='schedcell'){v.returnScroll=cfScheduleCapture12NB(screen);v.pending='editor';}
