function ryanOperatingProfileScore(q,p){var toks=String(q||'').toLowerCase().split(/[^a-z0-9-]+/).filter(function(t){return t.length>2&&!CF_STOPWORDS[t];}),head=(String(p.title||'')+' '+String(p.system||'')+' '+(p.equipmentIds||[]).join(' ')+' '+(p.tags||[]).join(' ')+' '+String(p.sourceLabel||'')).toLowerCase(),all=(head+' '+String(p.summary||'')+' '+(p.conditions||[]).join(' ')+' '+(p.responses||[]).join(' ')+' '+(p.relationships||[]).join(' ')+' '+(p.troubleshootingCues||[]).join(' ')).toLowerCase(),score=0;toks.forEach(function(t){if(head.indexOf(t)>=0)score+=6;else if(all.indexOf(t)>=0)score+=2;});if(/report|shift|histor|normal|usual|previous|past/i.test(q)&&/REPORT/.test(p.sourceType||''))score+=3;if(/trend|changed|first|drift|oscillat/i.test(q)&&/TREND/.test(p.sourceType||''))score+=3;return score;}
function ryanOperatingExperienceText(q,maxChars){var active=(RYAN_CACHE.operatingProfiles||[]).filter(function(p){return !p.status||p.status==='active'||p.status==='provisional';}),ranked=active.map(function(p){return {p:p,score:ryanOperatingProfileScore(q,p)};}).sort(function(a,b){return b.score-a.score||String(b.p.updatedAt||b.p.createdAt||'').localeCompare(String(a.p.updatedAt||a.p.createdAt||''));}),chosen=ranked.filter(function(x){return x.score>0;}).slice(0,18);if(!chosen.length)chosen=ranked.slice(0,6);if(!chosen.length)return '(no stored operating experience yet)';var lines=['SOURCE-LABELLED HISTORICAL OPERATING EXPERIENCE — comparison/troubleshooting evidence only; LIVE state and verified limits remain authoritative.'];chosen.forEach(function(x){var p=x.p,window=(p.startTime||p.endTime)?((p.startTime||'?')+' to '+(p.endTime||'?')):'time window not supplied';lines.push('\n['+(p.sourceType||'HISTORICAL')+' | '+(p.trust||'HISTORICAL_OPERATING_EVIDENCE')+' | '+String(p.confidence||'medium').toUpperCase()+' | evidence '+(p.evidenceCount||'?')+'] '+p.title);lines.push('Source: '+(p.sourceLabel||p.provenance||'stored operating experience')+' | Window: '+window);if(p.summary)lines.push('Summary: '+p.summary);if(p.conditions&&p.conditions.length)lines.push('Observed conditions: '+p.conditions.join(' | '));if(p.responses&&p.responses.length)lines.push('Observed responses: '+p.responses.join(' | '));if(p.relationships&&p.relationships.length)lines.push('Relationship candidates (not automatic proof): '+p.relationships.join(' | '));if(p.normalRanges&&p.normalRanges.length)lines.push('Historical comparison ranges: '+p.normalRanges.join(' | '));if(p.outliers&&p.outliers.length)lines.push('Outliers/suspect data: '+p.outliers.join(' | '));if(p.troubleshootingCues&&p.troubleshootingCues.length)lines.push('Troubleshooting cues: '+p.troubleshootingCues.join(' | '));if(p.doNotTreatAs&&p.doNotTreatAs.length)lines.push('Do not treat as: '+p.doNotTreatAs.join(' | '));});return lines.join('\n').slice(0,maxChars||14000);}
function ryanOperatingExperiencePanelHtml(){var list=(RYAN_CACHE.operatingProfiles||[]).slice().sort(function(a,b){return String(b.updatedAt||b.createdAt||'').localeCompare(String(a.updatedAt||a.createdAt||''));}),reports=list.filter(function(x){return /REPORT/.test(x.sourceType||'');}).length,trends=list.filter(function(x){return /TREND/.test(x.sourceType||'');}).length,h='<div style="background:#10242b;border:1px solid #326276;border-radius:7px;padding:11px 12px;"><div style="font-weight:700;color:#c9f7ff;">📚 Ryan Operational Experience</div><div style="font-size:11px;color:#8fb0bf;line-height:1.45;margin-top:4px;">Shift/2-hour/12-hour report patterns and historian windows stored here are automatically retrieved for later Clear Fork troubleshooting. Real report evidence stays separate from simulator trend evidence; neither becomes a trip limit or proof of causation.</div><div style="font-size:10.5px;color:#6f8b98;margin-top:6px;">'+list.length+' record(s): '+reports+' report-derived · '+trends+' trend-derived</div><button id="ryanLearn12hNow" style="margin-top:8px;background:#173a40;border:1px solid #3f7f89;color:#c9f7ff;border-radius:4px;padding:6px 11px;font-weight:700;cursor:pointer;">🧠 Install latest plant-wide 12h trends</button></div>';if(!list.length)return h+'<div style="color:#718491;font-size:11px;margin-top:10px;">No operating episodes installed yet. Analyze an archived shift report or open a 12h/24h/72h trend window.</div>';h+=list.slice(0,100).map(function(p){var src=/REPORT/.test(p.sourceType||'')?'REAL REPORT':'SIM TREND',c=src==='REAL REPORT'?'#8ee3a5':'#8fcfff',window=(p.startTime||p.endTime)?('<div style="font-size:9.5px;color:#68818f;">'+ryanEscape((p.startTime||'?')+' → '+(p.endTime||'?'))+'</div>'):'';return '<div style="background:#101a20;border:1px solid #2a4652;border-radius:6px;padding:8px 10px;margin-top:7px;"><div style="display:flex;justify-content:space-between;gap:8px;align-items:flex-start;"><div><span style="font-size:9px;font-weight:800;color:'+c+';">'+src+' · '+ryanEscape(String(p.confidence||'medium').toUpperCase())+'</span><div style="font-size:12px;color:#e3f1f6;font-weight:700;margin-top:2px;">'+ryanEscape(p.title||'Operating experience')+'</div>'+window+'</div><button data-opdelete="'+p.id+'" style="font-size:9px;padding:2px 6px;min-height:24px;">Delete</button></div><div style="font-size:10.8px;color:#b9cad1;white-space:pre-wrap;line-height:1.4;margin-top:5px;">'+ryanEscape(String(p.summary||'').slice(0,1200))+'</div><div style="font-size:9.5px;color:#6f8792;margin-top:4px;">Source: '+ryanEscape(p.sourceLabel||p.provenance||p.sourceType||'')+' · evidence '+ryanEscape(String(p.evidenceCount||'?'))+'</div></div>';}).join('');return h;}

