 el.innerHTML='<div style="max-width:1050px;margin:auto;background:#111820;border:1px solid #46586a;border-radius:8px;color:#dce6ee;font:12.5px/1.5 -apple-system,Segoe UI,Arial,sans-serif;box-shadow:0 14px 50px #000;padding:18px;">'+
 '<div style="display:flex;justify-content:space-between;gap:10px;align-items:start;"><div><div style="font-size:19px;font-weight:800;color:#fff;">'+ryanEscape(d.title||'Ryan Draft LOTO / Work Plan')+'</div><div style="color:#ffb1a8;font-weight:800;margin-top:3px;">DRAFT — NOT APPROVED — FIELD VERIFICATION REQUIRED</div><div style="font-size:10px;color:#7f91a2;">Created '+ryanEscape(new Date(rec.createdAt).toLocaleString())+'</div></div><button data-close-loto="1" style="background:#7a2929;border:1px solid #b14a4a;color:#fff;border-radius:4px;padding:7px 13px;font-weight:700;cursor:pointer;">Close</button></div>'+ 
 '<div style="margin-top:14px;background:#1b2026;border-left:4px solid #ffb347;padding:9px 11px;"><b>Scope:</b> '+ryanEscape(d.scope||'')+'<br><b>Work boundary:</b> '+ryanEscape(d.workBoundary||'PENDING VERIFICATION')+'<br><b>Equipment:</b> '+ryanEscape((d.equipment||[]).join(', ')||'PENDING VERIFICATION')+'<br><b>Source drawings:</b> '+ryanEscape((d.sourceDrawings||[]).join(', ')||'PENDING VERIFICATION')+'<br><b>Execution blocked:</b> '+(d.executionBlocked?'YES — unresolved boundary/source issue':'NO — still NOT APPROVED and field verification remains required')+'</div>'+
 '<h3 style="color:#bfe0ff;margin-bottom:3px;">Source evidence / continuations</h3><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;"><div>'+ryanLotoList(d.sourceEvidence,'No source-evidence list returned.')+'</div><div>'+ryanLotoList(d.continuationDrawings,'No continuation list returned.')+'</div></div>'+
 '<h3 style="color:#bfe0ff;margin-bottom:3px;">Energy-path trace</h3>'+ryanLotoList(d.energyPathTrace,'No energy-path trace returned.')+
 '<h3 style="color:#bfe0ff;margin-bottom:3px;">Work plan</h3>'+ryanLotoList(d.workPlanSteps,'No steps returned.')+
 '<h3 style="color:#bfe0ff;margin-bottom:3px;">Energy sources / hazards</h3><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;"><div>'+ryanLotoList(d.energySources,'No source-backed energy list.')+'</div><div>'+ryanLotoList(d.hazards,'No source-backed hazards listed.')+'</div></div>'+ 
 '<h3 style="color:#ffcf9f;margin-bottom:5px;">Isolation / blowdown / PSV markup</h3>'+ryanLotoSchematic(d)+
 '<div style="display:grid;grid-template-columns:1fr;gap:10px;margin-top:10px;"><div><b style="color:#ffcf9f;">Isolation points</b>'+ryanLotoMarkerRows(d.isolationPoints,'isolation')+'</div><div><b style="color:#9fe7ff;">Blowdown / bleed points</b>'+ryanLotoMarkerRows(d.blowdownPoints,'blowdown')+'</div><div><b style="color:#ffaaaa;">PSVs / relief protection</b>'+ryanLotoMarkerRows(d.psvMarkers,'PSV')+'</div></div>'+ 
 '<h3 style="color:#bfe0ff;margin-bottom:3px;">Field verification checklist</h3>'+ryanLotoList(d.verificationChecklist,'Field verification checklist not returned.')+
 '<h3 style="color:#bfe0ff;margin-bottom:3px;">Zero-energy criteria</h3>'+ryanLotoList(d.zeroEnergyCriteria,'Zero-energy criteria not returned.')+
 '<h3 style="color:#ffd38a;margin-bottom:3px;">Conflicts / ambiguities / approval holds</h3><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;"><div>'+ryanLotoList(d.conflictsAndAmbiguities,'No conflicts returned; field verification is still mandatory.')+'</div><div>'+ryanLotoList(d.approvalRequirements,'Site approval requirements not returned.')+'</div></div>'+
 '<h3 style="color:#bfe0ff;margin-bottom:3px;">Restoration / return to service</h3>'+ryanLotoList(d.restorationSteps,'Restoration steps require site procedure/field verification.')+
 '<h3 style="color:#ffd38a;margin-bottom:3px;">Missing information / holds</h3>'+ryanLotoList(d.missingInformation,'No gaps reported by Ryan; field verification is still mandatory.')+
 '<div style="margin-top:14px;background:#3a1717;border:2px solid #a84848;color:#ffd4d4;border-radius:6px;padding:12px;font-weight:800;text-align:center;font-size:14px;">NOT APPROVED — FIELD VERIFICATION REQUIRED</div></div>';
 document.body.appendChild(el);el.querySelector('[data-close-loto]').addEventListener('click',function(){el.remove();});
