function ryanLearnedFactsForQuestion(q,limit){
 try{
  limit=Math.max(1,Math.min(Number(limit)||32,48));
  var props=(RYAN_CACHE.proposals||[]).filter(function(p){return p&&p.statement&&(p.status==='staged'||p.status==='approved');});
  if(!props.length)return [];
  var docs={};(RYAN_CACHE.documents||[]).forEach(function(d){docs[String(d.id)]=d;});
  var latest=ryanLatestLearnedDocument();
  var t=String(q||'').toLowerCase(), general=ryanIsLearnedDocumentQuery(q);
  var terms=t.split(/[^a-z0-9-]+/).filter(function(x){return x.length>2&&!/^(what|did|have|you|learn|learned|from|the|this|that|with|about|tell|show|according|based|pid|document|drawing)$/.test(x);});
  if(!general&&!terms.length)return [];
  var ranked=props.map(function(p){
   var d=docs[String(p.sourceDocumentId)]||{};var hay=(String(p.statement)+' '+String(p.classification||'')+' '+String(p.sourcePage||'')+' '+String(d.title||'')+' '+(p.equipmentIds||[]).join(' ')).toLowerCase();
   var score=0;terms.forEach(function(term){if(hay.indexOf(term)>=0)score+=3;});
   if(latest&&String(p.sourceDocumentId)===String(latest.id))score+=general?20:4;
   if(p.status==='approved')score+=1;
   return {p:p,d:d,score:score};
  }).sort(function(a,b){return b.score-a.score||String(b.d.importedAt||'').localeCompare(String(a.d.importedAt||''));});
  if(!general&&terms.length){if(ranked.some(function(x){return x.score>4;}))ranked=ranked.filter(function(x){return x.score>4;});else return [];}
  else if(general&&latest)ranked=ranked.filter(function(x){return String(x.p.sourceDocumentId)===String(latest.id);});
  return ranked.slice(0,limit).map(function(x){return {statement:String(x.p.statement||'').slice(0,1200),source:(x.d.title||x.p.sourceDocumentId||'learned document'),page:x.p.sourcePage||null,verificationStatus:x.p.verificationStatus||'DOCUMENT_EXTRACTED_UNVERIFIED',classification:x.p.classification||'other',equipmentIds:Array.isArray(x.p.equipmentIds)?x.p.equipmentIds.slice(0,12):[],confidence:x.p.confidence||null};});
 }catch(e){return [];}
}
