  RYAN_AI_HISTORY.push({role:'user',content:q});RYAN_AI_HISTORY.push({role:'assistant',content:localLearned,mode:'qa',cost:{usd:0,inputTokens:0,outputTokens:0},localLearnedSummary:true,qaArchiveId:localSave&&localSave.record.id,qaAnsweredAt:localSave&&localSave.record.answeredAt,qaDurable:localSave&&localSave.durable});
  if(RYAN_AI_HISTORY.length>20)RYAN_AI_HISTORY=RYAN_AI_HISTORY.slice(-20);ryanSaveConversationHistory();out.innerHTML='';renderRyanAiThread();return;
