  if(isImage){out.innerHTML='<div style="color:#8a97a4;font-style:italic;font-size:12px;">Preparing image for Ryan vision…</div>';ryanPrepareImageForUpload(attachment,function(uploadAttachment){if(uploadAttachment&&uploadAttachment._uploadError){out.innerHTML='<div style="color:#ffb0b0;font-size:12.5px;">'+ryanEscape(uploadAttachment._uploadError)+'</div>';return;}var note=(uploadAttachment&&uploadAttachment._optimizedForRyan)?' <span style="color:#6faac8;">Large photo optimized automatically for upload; readable resolution retained.</span>':'';out.innerHTML='<div style="color:#8a97a4;font-style:italic;font-size:12px;">Ryan is inspecting the image in one bounded vision pass…'+note+'</div>';ryanFetch({mode:'image_learn',message:'Learn the visible plant-specific facts from this image.'+(attachment.description?' Operator description: '+attachment.description:''),context:ryanDigestExistingPidContext(),history:[],password:RYAN_AI_PW,attachment:uploadAttachment}).then(function(res){if(res.status===403){ryanAiLock();askRyanRender();return;}if(!res.ok||(res.d&&res.d.error)){out.innerHTML='<div style="color:#ffb0b0;font-size:12.5px;">Image learning failed: '+ryanBackendError(res)+'</div>';return;}var ing=res.d&&res.d.ingestion;var _sa=ryanSemanticAnchor(attachment.description||'',attachment.label||'');var job={sourceLabel:attachment.label||'image',fileId:'image-'+Date.now(),documentType:'image',contentFingerprint:attachment.contentFingerprint||ryanAttachmentFingerprint(attachment),operatorDescription:_sa.description,anchorEquipmentIds:_sa.equipmentIds,anchorIndexEquipmentIds:_sa.indexEquipmentIds,anchorRelatedEquipmentIds:_sa.relatedEquipmentIds,anchorSystem:_sa.system,referenceBinding:Object.assign({},(res.d&&res.d.referenceBinding)||{},_sa.referenceBinding||{})};ryanStageInteractiveFacts(job,{facts:(ing&&ing.facts)||[],passes:[{index:0,id:'image_vision',ok:!!(ing&&ing.facts&&ing.facts.length),facts:(ing&&ing.facts&&ing.facts.length)||0,error:(ing&&ing.warnings||[]).join(' | ')}]},out);}).catch(function(e){out.innerHTML='<div style="color:#ffb0b0;font-size:12.5px;">Image learning failed before Netlify timeout: '+ryanEscape(e.message)+'</div>';});});return;}
  if(attachment.base64){var approxBytes=Math.floor(String(attachment.base64).replace(/\s/g,'').length*3/4);if(approxBytes>4*1024*1024){out.innerHTML='<div style="background:#3a2b12;border:1px solid #7a5a24;border-radius:6px;padding:10px 12px;color:#ffd38a;font-size:12.5px;"><b>Local PDF is '+Math.round(approxBytes/1024/1024)+' MB.</b><br>This exceeds the safe browser-to-Netlify payload. Split/export it into smaller PDF sections or page images and drop those here. HTTPS is optional; Ryan will not silently truncate the file.</div>';return;}}
