/* ═══ Ryan Scan: audits the program's own quiz bank and source code, one
   batch/section at a time. See globals declared with RYANFN_URL above. ═══ */
function ryanScanQuizBatchInfo(){
 var total=QUIZ_BANK.length;
 var start=parseInt(localStorage.getItem('ryanScanQuizIdx')||'0',10); if(!(start>=0&&start<total))start=0;
 var end=Math.min(start+RYAN_SCAN_QUIZ_BATCH,total);
 return {start:start,end:end,total:total};
}
function ryanScanQuizContext(info){
 var batch=QUIZ_BANK.slice(info.start,info.end);
 var text=batch.map(function(q,i){
  return 'Q'+(info.start+i+1)+' [category: '+(q.c||'')+']\nQuestion: '+q.q+'\nMarked CORRECT answer: '+q.a+'\nDistractors (marked WRONG): '+(q.w||[]).join(' | ');
 }).join('\n\n');
 return text;
}
function ryanScanCodeSections(src){
 var lines=src.split('\n');
 var starts=[];
 for(var i=0;i<lines.length;i++){if(/\/\*.*[\u2550\u2501]{2,}/.test(lines[i]))starts.push(i);}
 if(!starts.length)starts=[0]; /* fallback: whole file as one giant section, shouldn't happen in practice */
 var sections=[];
 for(var j=0;j<starts.length;j++){
  var from=starts[j], to=(j+1<starts.length)?starts[j+1]:lines.length;
  var chunkLines=lines.slice(from,to);
  var label=chunkLines[0].replace(/\/\*+|\*+\//g,'').replace(/[\u2550\u2501]/g,'').trim().slice(0,90)||('Section near line '+(from+1));
  sections.push({label:label,text:chunkLines.join('\n'),startLine:from+1,endLine:to});
 }
 return sections;
}
function ryanScanFetchSrc(cb){
 if(RYAN_SCAN_SRC){cb(RYAN_SCAN_SRC);return;}
 fetch(location.href).then(function(r){return r.text();}).then(function(t){RYAN_SCAN_SRC=t;cb(t);}).catch(function(){cb(null);});
}
function ryanScanCodeBatchInfo(cb){
 ryanScanFetchSrc(function(src){
  if(!src){cb(null);return;}
  var sections=ryanScanCodeSections(src);
  var idx=parseInt(localStorage.getItem('ryanScanCodeIdx')||'0',10); if(!(idx>=0&&idx<sections.length))idx=0;
  cb({sections:sections,idx:idx,total:sections.length});
 });
}
function doRyanScan(kind){
 var out=document.getElementById('askRyanAiOut'); if(!out)return;
 if(ryanAiSessionExpired()){
  ryanAiLock(); askRyanRender();
  var errEl0=document.getElementById('askRyanPwErr'); if(errEl0)errEl0.textContent='Your 45-minute session expired \u2014 please re-enter the password.';
  return;
 }
 out.innerHTML='<div style="color:#8a97a4;font-style:italic;font-size:12px;">Running Ryan Scan\u2026</div>';
 function runScan(userLabel,scanLabel,context,advance){
  ryanFetch({message:'(Ryan Scan \u2014 see attached batch)',context:context,mode:'scan',scanLabel:scanLabel,history:[],password:RYAN_AI_PW,attachment:null}).then(function(res){
   if(res.status===403){ryanAiLock(); askRyanRender(); var errEl=document.getElementById('askRyanPwErr'); if(errEl)errEl.textContent='Incorrect password.'; return;}
   if(!res.ok||res.d.error){out.innerHTML='<div style="background:#3a1c1c;border:1px solid #6a3030;border-radius:6px;padding:10px 12px;color:#ffb0b0;font-size:12.5px;">Ryan Scan failed: '+((res.d&&res.d.error)||'unknown error')+'</div>';return;}
   advance(); /* only move the rotation pointer forward on a real success */
   RYAN_AI_HISTORY.push({role:'user',content:userLabel});
   RYAN_AI_HISTORY.push({role:'assistant',content:res.d.reply||'',mode:'scan',scanLabel:scanLabel,cost:res.d.cost});
   if(RYAN_AI_HISTORY.length>20)RYAN_AI_HISTORY=RYAN_AI_HISTORY.slice(-20);ryanSaveConversationHistory();
   out.innerHTML='';
   askRyanRender(); /* full re-render so the button captions pick up the new rotation position */
   var thread=document.getElementById('askRyanThread'); if(thread)thread.scrollIntoView({block:'end'});
  }).catch(function(e){
   cfRyanError12MK(out,e,'response');
  });
 }
 if(kind==='quiz'){
  var qi=ryanScanQuizBatchInfo();
  if(!qi.total){out.innerHTML='<div style="color:#ffcf9f;font-size:12.5px;">Quiz bank is empty \u2014 nothing to scan.</div>';return;}
  var scanLabel='Pop Quiz batch, questions '+(qi.start+1)+'\u2013'+qi.end+' of '+qi.total;
  RYAN_SCAN_LAST={type:'quiz',start:qi.start,end:qi.end,total:qi.total};
  runScan('Ryan Scan: '+scanLabel,scanLabel,ryanScanQuizContext(qi),function(){
   var next=qi.end>=qi.total?0:qi.end;
   localStorage.setItem('ryanScanQuizIdx',String(next));
  });
 } else if(kind==='code'){
  ryanScanCodeBatchInfo(function(ci){
   if(!ci){out.innerHTML='<div style="color:#ffb0b0;font-size:12.5px;">Could not fetch the page\u2019s own source to scan (self-fetch failed) \u2014 try again.</div>';return;}
   var sec=ci.sections[ci.idx];
   var truncated=sec.text.length>RYAN_SCAN_CODE_CHARCAP;
   var body=truncated?sec.text.slice(0,RYAN_SCAN_CODE_CHARCAP):sec.text;
   var scanLabel='Source code section '+(ci.idx+1)+' of '+ci.total+' (lines '+sec.startLine+'\u2013'+sec.endLine+'): \u201c'+sec.label+'\u201d'+(truncated?' [truncated to first '+RYAN_SCAN_CODE_CHARCAP+' chars \u2014 section is longer than that]':'');
   RYAN_SCAN_LAST={type:'code',idx:ci.idx,total:ci.total,label:sec.label};
   runScan('Ryan Scan: '+scanLabel,scanLabel,body,function(){
    var next=(ci.idx+1>=ci.total)?0:ci.idx+1;
    localStorage.setItem('ryanScanCodeIdx',String(next));
   });
  });
 }
}
