var showMV=true, showInst=true, showFlow=false;
function applyLayers(){mvalGroup.forEach(function(o){o.visible=showMV;}); instGroup.forEach(function(o){o.visible=showInst;}); flowGroup.forEach(function(o){o.visible=showFlow;}); CF3D_FIELD_INFILL.forEach(function(x){x.mesh.visible=!(x.manual?showMV:showInst);}); updateLabels();}
applyLayers();
setInterval(cf3dRefreshFieldReadings,1000);
var sel=[], selKey=null, showAll=false;
function updateLabels(){sprites.forEach(function(s){var r=cf3dDeviceRecord(s.userData.key),allowed=!(r&&r.fieldDevice)||(r.kind==='manual'?showMV:showInst);s.visible=!!(allowed&&(showAll||(selKey&&s.userData.key===selKey)));});}
