function enterWalk(){walk=true; goalPos=null; goalTgt=null; savedPos.copy(cam.position); savedTgt.copy(ctl.target); ctl.enabled=false;
 /* drop into walk mode wherever the orbit camera currently is, facing roughly where it was looking */
 var d=ctl.target.clone().sub(cam.position); d.y=0; if(d.lengthSq()<0.0001)d.set(0,0,-1); d.normalize();
 cam.position.set(cam.position.x,EYE,cam.position.z);
 yaw=Math.atan2(-d.x,-d.z); pitch=0;
 cam.rotation.order='YXZ'; cam.rotation.set(pitch,yaw,0); walkbtn.textContent='\u25A0 Exit walk'; dpad.style.display='block'; lpad.style.display='block'; hint.style.display='block';}
function exitWalk(){walk=false; ctl.enabled=true; cam.position.copy(savedPos); ctl.target.copy(savedTgt); walkbtn.textContent='\u25B6 Walk mode'; dpad.style.display='none'; lpad.style.display='none'; hint.style.display='none'; if(typeof stowPole==='function')stowPole();}
walkbtn.addEventListener('click',function(){walk?exitWalk():enterWalk();});
