var PONDX=250,PONDZ=400,PBASE=30,_ph=[Math.random()*6.28,Math.random()*6.28,Math.random()*6.28];
function pondR(t){return PBASE*(1+0.18*Math.sin(t*1.7+_ph[0])+0.11*Math.sin(t*2.9+_ph[1])+0.07*Math.sin(t*4.3+_ph[2]));}
function inPond(x,z){var dx=x-PONDX,dz=z-PONDZ;return Math.hypot(dx,dz)<pondR(Math.atan2(dz,dx))-0.6;}
function pondDisc(rOff,color,opacity,rough,y){var N=84,v=[0,0,0],idx=[],i;for(i=0;i<=N;i++){var t=i/N*Math.PI*2,r=pondR(t)+rOff;v.push(Math.cos(t)*r,0,Math.sin(t)*r);}for(i=0;i<N;i++)idx.push(0,i+1,i+2);var g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(v,3));g.setIndex(idx);g.computeVertexNormals();var m=new THREE.Mesh(g,new THREE.MeshStandardMaterial({color:color,roughness:rough,metalness:opacity<1?0.25:0,transparent:opacity<1,opacity:opacity,side:THREE.DoubleSide}));m.position.set(PONDX,y,PONDZ);scene.add(m);return m;}
function pondBank(rIn,rOut,color,y){var N=84,v=[],idx=[],i;for(i=0;i<=N;i++){var t=i/N*Math.PI*2,ri=pondR(t)+rIn,ro=pondR(t)+rOut;v.push(Math.cos(t)*ri,0,Math.sin(t)*ri,Math.cos(t)*ro,0,Math.sin(t)*ro);}for(i=0;i<N;i++){var a=i*2;idx.push(a,a+2,a+1,a+1,a+2,a+3);}var g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(v,3));g.setIndex(idx);g.computeVertexNormals();var m=new THREE.Mesh(g,new THREE.MeshStandardMaterial({color:color,roughness:1,side:THREE.DoubleSide}));m.position.set(PONDX,y,PONDZ);scene.add(m);return m;}
