 aS('aPdi',EXP.pdi.toFixed(0)+' "H2O');aS('aCompVibX',EXP.compVibX.toFixed(2)+' MILS');aS('aCompVibY',EXP.compVibY.toFixed(2)+' MILS');
 aS('aSealDP',EXP.sealDP.toFixed(0)+' PSID');aS('aCompBrg',EXP.compBrgT.toFixed(0)+' \u00B0F');
 var st=document.getElementById('aStatus');if(st){st.textContent=EXP.run?'RUNNING':'STOPPED';st.className=EXP.run?'arun':'astop';}
