 var sl=document.getElementById('aSlider');if(sl){sl.disabled=state.remote||!EXP.run;if(document.activeElement!==sl)sl.value=EXP.localDemand.toFixed(0);}
 ['aDn','aUp'].forEach(function(id){var el=document.getElementById(id);if(el)el.disabled=state.remote||!EXP.run;});
