var EXP_CONTROL_12FX={revision:'12FX-20261002',startupPct:20,matchDisplayDecimals:0};
var EXP_CONTROL_DRAG=false;
function expControlState(){
 var ex=PLANT.L.PIC1521DEX,jt=PLANT.L.PIC1521DJT;
 if(typeof EXP.remote!=='boolean')EXP.remote=EXP.auto!==false;
 if(!isFinite(EXP.localDemand))EXP.localDemand=clmp(EXP.igv,0,100);
 EXP.auto=EXP.remote&&!ex.man;
 return {ex:ex,jt:jt,remote:EXP.remote,local:!EXP.remote,auto:EXP.auto,
  matched:Math.round(ex.out)===Math.round(EXP.igv)&&Math.round(ex.out)===Math.round(EXP.localDemand),
  below:jt.sp<ex.sp};
}
function expControlMessage(message){EXP.controlMessage=String(message||'');if(message&&typeof alarm==='function')alarm('EX-1121: '+message);}
function expSetManual(manual,source){
 var s=expControlState();manual=!!manual;
 if(!manual){
  if(!EXP.run){expControlMessage('AUTO not selected: expander must be running.');return false;}
  if(!s.remote){expControlMessage('AUTO not selected: outside operator must transfer HIC-101 to REMOTE first.');return false;}
  if(!s.below){expControlMessage('AUTO not selected: work JT SP below EX SP first (simulator handover guard).');return false;}
  if(PLANT.esd){expControlMessage('AUTO not selected: facility ESD is active.');return false;}
  EXP.startupPending=false;
 }else if(!s.ex.man){s.ex.out=clmp(EXP.igv,0,100);}
 s.ex.man=manual;EXP.auto=EXP.remote&&!manual;EXP.cascade=false;
 if(EXP.remote)EXP.igvSP=clmp(s.ex.out,0,100);
 expControlMessage(manual?'Board EX controller MANUAL; '+(EXP.remote?'board output owns IGV demand.':'outside operator still owns the local IGVs.'):'Board EX controller AUTO; EX and JT regulate the same tower pressure.');
 return true;
}
function expSetRemote(remote){
 var s=expControlState();remote=!!remote;
 if(remote===EXP.remote)return true;
 if(remote){
  if(!EXP.run){expControlMessage('REMOTE not selected: start the expander in LOCAL first.');return false;}
  if(!s.ex.man||!s.matched){expControlMessage('REMOTE not selected: board must be MANUAL and match actual/local IGV at the displayed whole-percent value.');return false;}
  if(EXP.startupPending&&Math.round(EXP.igv)!==EXP_CONTROL_12FX.startupPct){expControlMessage('Startup REMOTE handover not selected: match local and board at 20% first (training guard).');return false;}
  EXP.remote=true;EXP.auto=false;EXP.igvSP=s.ex.out;
  expControlMessage('REMOTE accepted at '+s.ex.out.toFixed(0)+'%; board remains MANUAL. Work JT SP below EX SP, then select EX AUTO.');
 }else{
  EXP.remote=false;EXP.auto=false;EXP.cascade=false;EXP.localDemand=clmp(EXP.igv,0,100);EXP.igvSP=EXP.localDemand;
  s.ex.man=true;s.ex.out=EXP.localDemand;
  expControlMessage('LOCAL selected without a vane-position jump. Outside operator owns IGVs; board MANUAL output can be matched independently.');
 }
 return true;
}
function expSetLocalDemand(value){
 var s=expControlState();if(s.remote||!EXP.run){expControlMessage('Local IGV command ignored: select LOCAL on a running expander first.');return false;}
 if(!isFinite(value))return false;
 EXP.localDemand=clmp(Math.round(value),0,100);EXP.igvSP=EXP.localDemand;
 EXP.controlMessage='LOCAL command '+EXP.localDemand.toFixed(0)+'%. Actual vanes travel toward demand; independently match the board output.';
 return true;
}
function expSetBoardDemand(value){
 var s=expControlState();if(!s.ex.man){expControlMessage('Board output command ignored: select EX MANUAL first.');return false;}
 if(!isFinite(value))return false;
 s.ex.out=clmp(Math.round(value),0,100);
 if(s.remote)EXP.igvSP=s.ex.out;
 EXP.controlMessage=s.remote?'REMOTE / MANUAL: board output owns IGV demand.':'LOCAL: board output is staged only; it does not move the outside operator\'s IGVs.';
 return true;
}
function expSetRunning(run){
 run=!!run;var s=expControlState();if(run===EXP.run)return true;
 if(run){
  if(PLANT.esd){expControlMessage('START blocked: facility ESD active; use the existing reset/permissive checks.');return false;}
  if(PLANT.redtag&&PLANT.redtag.ex1121){expControlMessage('START blocked: EX-1121/C-1121 is RED TAGGED.');return false;}
  /* Existing plant tick still enforces package interlocks. No protection is bypassed. */
  EXP.run=true;PLANT.valves.xv1121b=1;EXP.remote=false;EXP.auto=false;EXP.cascade=false;EXP.localDemand=0;EXP.igvSP=0;s.ex.out=0;s.ex.man=true;EXP.startupPending=true;
  expControlMessage('START accepted in simulator, LOCAL / board MANUAL. Open local IGVs to 20%, match the board to 20%, then transfer REMOTE.');
 }else{
  cfUpdateExpanderRouting12FY();var prep=cfRundownStatus12NA();if(!prep.normalStopReady){expControlMessage('NORMAL STOP NOT READY (training guard): '+prep.reasons.join('; ')+'. Protective trips/ESD remain immediate.');return false;}
  PLANT.v._normalExpStop12NA=true;PLANT.valves.xv1121b=0;EXP.run=false;EXP.remote=false;EXP.auto=false;EXP.cascade=false;EXP.localDemand=0;EXP.igvSP=0;s.ex.out=0;s.ex.man=true;EXP.startupPending=true;
  cfUpdateExpanderRouting12FY();
  expControlMessage('STOP: EX forward flow is zero. Continuing main gas uses JT only; JT control and isolation remain authoritative.');
 }
 return true;
}
function expExecuteCommand(action,value,source){
 var s=expControlState(),ok=false;
 if(action==='local')ok=expSetRemote(false);
 else if(action==='remote')ok=expSetRemote(true);
 else if(action==='manual')ok=expSetManual(true,source);
 else if(action==='auto')ok=expSetManual(false,source);
 else if(action==='mode')ok=expSetManual(!s.ex.man,source);
 else if(action==='localDemand')ok=expSetLocalDemand(Number(value));
 else if(action==='boardDemand')ok=expSetBoardDemand(Number(value));
 else if(action==='match')ok=expSetBoardDemand(Math.round(EXP.igv));
 else if(action==='run')ok=expSetRunning(!EXP.run);
 else if(action==='exSP'&&isFinite(value)){s.ex.sp=clmp(Number(value),225,350);ok=true;}
 else if(action==='jtSP'&&isFinite(value)){s.jt.sp=clmp(Number(value),225,350);ok=true;}
 else if(action==='jtMode'){s.jt.man=!s.jt.man;s.jt.out=clmp(PLANT.valves.pcv1121a_bypass||0,0,100);ok=true;}
 else if(action==='jtCV'&&isFinite(value)&&s.jt.man){s.jt.out=clmp(Number(value),0,100);ok=true;}
 expRender();if(typeof cfBroadcastSnapshot==='function'&&!EXP_CONTROL_DRAG)cfBroadcastSnapshot();return ok;
}
function expDispatch(action,value,source){
 /* Use commands, not replayed DOM clicks: a second-screen operator must still be
    able to hand over when the host is looking at a different screen. */
 if(typeof IS_CLIENT!=='undefined'&&IS_CLIENT){
  if(!window.opener||window.opener.closed){expControlMessage('Primary window is unavailable; command was not applied.');expRender();return false;}
  window.opener.postMessage({kind:'cfExpanderCommand12FX',action:action,value:value,source:source||'SECOND SCREEN'},location.origin==='null'?'*':location.origin);return true;
 }
 return expExecuteCommand(action,value,source);
}
function setExpanderControlManual(manual,source){return expDispatch(manual?'manual':'auto',null,source);}
function setExpanderIGVManualCommand(cmd,source){return expDispatch('localDemand',Number(cmd),source);}
function aSetIGV(v){return expDispatch('localDemand',Number(v),'LOCAL IGV SLIDER');}
function acmtcNudgeIGV(d){return expDispatch('localDemand',EXP.localDemand+(d<0?-1:1),'ACMTC');}
function acmtcToggleAuto(){return expDispatch(EXP.remote?'local':'remote',null,'ACMTC LOCAL/REMOTE');}
function expAdvanceControls(){
 var s=expControlState(),V=PLANT.v,ex=s.ex,jt=s.jt,pv=PLANT.L.PIC1521.pv;
 ex.pv=pv;jt.pv=pv;ex.sp=clmp(ex.sp,225,350);jt.sp=clmp(jt.sp,225,350);
 if(V._expWasRunning===undefined)V._expWasRunning=EXP.run;
 if(V._expWasRunning&&!EXP.run){
  EXP.remote=false;EXP.auto=false;EXP.cascade=false;EXP.localDemand=0;EXP.igvSP=0;ex.man=true;ex.out=0;EXP.startupPending=true;
  V._jtTripAssistTicks=V._normalExpStop12NA?0:10;if(!V._normalExpStop12NA)expControlMessage('Expander lost: IGV closing; JT AUTO backup is taking pressure-control duty.');V._normalExpStop12NA=false;PLANT.valves.xv1121b=0;
 }
 if(!V._expWasRunning&&EXP.run)V._expRunTicks=0;
 V._expRunTicks=EXP.run?((V._expRunTicks||0)+1):0;V._expWasRunning=EXP.run;
 var expPath=EXP.run&&(PLANT.valves.xv1121b==null||PLANT.valves.xv1121b>0);
 var jtPath=PLANT.valves.xv1121a==null||PLANT.valves.xv1121a>0;
 if(EXP.run){
  if(EXP.remote){
   if(!ex.man){
    /* Empirical controller tuning; not a site gain. Lower PV opens the feed path. */
    var jtPriority=jtPath&&!jt.man&&jt.sp>ex.sp;
    var jtActual=clmp(Number(PLANT.valves.pcv1121a_bypass)||0,0,100);
    var exTarget=jtPriority?clmp(94*Math.max(0,1-jtActual/80),0,100):clmp(94+2.0*(ex.sp-pv),0,100); /*12NA complementary transfer; nominal80% JT capacity remains model calibration.*/
    ex.out+=clmp(exTarget-ex.out,-3,3); /* bumpless MAN -> AUTO, no immediate 20 -> 100 jump */
   }
   EXP.igvSP=clmp(ex.out,0,100);
  }else{EXP.auto=false;EXP.igvSP=clmp(EXP.localDemand,0,100);}
 }else EXP.igvSP=0;
 EXP.igv=clmp(EXP.igv+(EXP.igvSP-EXP.igv)*(EXP.run?0.22:0.28),0,100);
 if(Math.abs(EXP.igv-EXP.igvSP)<0.02)EXP.igv=EXP.igvSP;
 /* Feedforward shares the same letdown duty; feedback trims against tower PV.
    Nominal full-flow openings (EX 94%, JT 80%) are simulator calibration ONLY. */
 var expCapacity=expPath?clmp(EXP.igv/94,0,1.064):0;
 var jtPriority=jtPath&&!jt.man&&(!expPath||(EXP.remote&&!ex.man&&jt.sp>ex.sp));
 var jtNeed=clmp((jtPriority?80:80*Math.max(0,1-expCapacity))+2.0*(jt.sp-pv),0,100);
 if(EXP.remote&&!ex.man&&expPath&&ex.sp>jt.sp&&expCapacity>=1)jtNeed=clmp(2.0*(jt.sp-pv),0,100);
 if(!jt.man)jt.out=jtNeed;
 var cur=clmp(Number(PLANT.valves.pcv1121a_bypass)||0,0,100),target=jtPath?jt.out:0;
 var travel=(!EXP.run&&V._jtTripAssistTicks>0&&!jt.man)?0.32:0.22;
 if(V._jtTripAssistTicks>0)V._jtTripAssistTicks--;
 PLANT.valves.pcv1121a_bypass=clmp(cur+(target-cur)*travel,0,100);
 if(Math.abs(PLANT.valves.pcv1121a_bypass-target)<0.03)PLANT.valves.pcv1121a_bypass=target;
 var exAuto=expPath&&EXP.remote&&!ex.man,jtAuto=jtPath&&!jt.man;
 V.towerPressureController=exAuto&&(!jtAuto||ex.sp>jt.sp)?'PIC-1521D EX':(jtAuto?'PIC-1521D JT':'MANUAL LETDOWN');
 V.towerPressureControlSP=V.towerPressureController==='PIC-1521D EX'?ex.sp:(V.towerPressureController==='PIC-1521D JT'?jt.sp:null);
 V.expanderControlOwner=EXP.remote?(ex.man?'REMOTE / BOARD MANUAL':'REMOTE / EX AUTO'):'LOCAL / OUTSIDE OPERATOR';
}
