/* ═══════ TREND HISTORY: every temp/pressure/flow instrument on every control board
   now records a rolling history each tick, so the TREND buttons actually work instead
   of being decorative labels. Click any TREND button or trended value to see a real
   chart of how it's moved. ═══════ */
var TREND_LOG = {};
var TREND_TIME = {}; /* parallel timestamp array; keeps TREND_LOG numeric for all existing calculations */
var TREND_RETENTION_MS = 72*60*60*1000; /* operator request: retain up to 72 hours */
var TREND_MIN_SAMPLE_MS = 60000; /* 1-minute historian samples; 72 h = 4320 points/tag */
var TREND_MAX = Math.ceil(TREND_RETENTION_MS/TREND_MIN_SAMPLE_MS)+16;
function trendAvg(key){
 /* Honest approximation, not a real time-windowed shift average: TREND_LOG only
    keeps a timestamped rolling 72-hour history, so
    this is "average of recent trend history," not "average since shift start."
    Labeled as such everywhere it's displayed rather than implying more precision
    than the underlying data actually has. */
 var arr=TREND_LOG[key];
 if(!arr||!arr.length)return 0;
 var sum=0; for(var i=0;i<arr.length;i++)sum+=arr[i];
 return sum/arr.length;
}
function sparkline(key,w,h,color){
 var arr=TREND_LOG[key];
 w=w||80;h=h||20;color=color||'#5fa8f5';
 if(!arr||arr.length<2)return '<svg width="'+w+'" height="'+h+'"></svg>';
 var lo=Math.min.apply(null,arr),hi=Math.max.apply(null,arr);
 var range=(hi-lo)||1;
 var pts=arr.map(function(v,i){var x=(i/(arr.length-1))*w;var y=h-((v-lo)/range)*h;return x.toFixed(1)+','+y.toFixed(1);}).join(' ');
 return '<svg width="'+w+'" height="'+h+'" style="vertical-align:middle;"><polyline points="'+pts+'" fill="none" stroke="'+color+'" stroke-width="1.3"/></svg>';
}
function shiftExportCSV(){
 var rows=[['Field','Value']];
 var h=computePlantHealth();
 rows.push(['Exported',new Date().toLocaleString()]);
 rows.push(['Plant Health Score',h.score.toFixed(0)]);
 rows.push(['Operating Mode',PLANT.esd?'TRIPPED (ESD)':(PLANT.mode||'RUNNING')]);
 rows.push(['Avg Inlet Flow (recent trend, MMSCFD)',trendAvg('flow').toFixed(1)]);
 rows.push(['Avg Residue Rate (recent trend, MMSCFD)',trendAvg('resrate').toFixed(1)]);
 rows.push(['Avg NGL C2 (recent trend, mol%)',trendAvg('c2ngl').toFixed(2)]);
 rows.push(['Active Concerns',h.concerns.length]);
 h.concerns.forEach(function(c){rows.push(['Concern',c[0]+': '+c[1]]);});
 (SCEN.log||[]).slice(0,20).forEach(function(e){rows.push(['Log '+new Date(e.t).toLocaleTimeString(),e.m]);});
 (PLANT.shiftNotes||[]).forEach(function(e){rows.push(['Note '+new Date(e.t).toLocaleTimeString(),e.m]);});
 var csv=rows.map(function(r){return r.map(function(c){return '"'+String(c).replace(/"/g,'""')+'"';}).join(',');}).join('\r\n');
 var blob=new Blob([csv],{type:'text/csv'});
 var url=URL.createObjectURL(blob);
 var aEl=document.createElement('a');
 aEl.href=url; aEl.download='clearfork_shift_'+Date.now()+'.csv';
 document.body.appendChild(aEl); aEl.click(); document.body.removeChild(aEl);
 URL.revokeObjectURL(url);
}
function recordTrend(key, value){
 if(value==null || isNaN(value)) return;
 var now=Date.now();
 var arr=TREND_LOG[key];if(!arr){arr=[];TREND_LOG[key]=arr;}
 var ta=TREND_TIME[key];if(!ta){ta=[];TREND_TIME[key]=ta;}
 /* Keep long trends readable and browser-friendly: one point every 60 s, but update
    the newest point in between so CURRENT remains live. */
 if(ta.length && now-ta[ta.length-1] < TREND_MIN_SAMPLE_MS){arr[arr.length-1]=value;return; /* retain bucket start; moving it every tick prevented all later 60-second samples */}
 arr.push(value);ta.push(now);
 var cutoff=now-TREND_RETENTION_MS;
 while(ta.length && (ta[0]<cutoff || arr.length>TREND_MAX)){ta.shift();arr.shift();}
}
