 ['Suction Press,'+c57.suc.toFixed(0),'Disch. Press,'+c57.dis.toFixed(0),'Oil Press,'+(c57.oilP==null?'N/A':Number(c57.oilP).toFixed(0)),'Throw 1 Temp,'+(c57.discT-9).toFixed(0),'Throw 2 Temp,'+(c57.discT-10).toFixed(0),'Oil Temp,'+c57.oilT.toFixed(0),'Motor Speed,'+(c57.run?(c57.rpm||1780):0)].forEach(function(row,i){
  var parts=row.split(','),yy=390+i*20;
  s+='<text x="860" y="'+yy+'" fill="#8fa0b2" font-size="8">'+parts[0]+'</text><text x="1050" y="'+yy+'" fill="#1cd840" font-size="9" font-family="Consolas,monospace" text-anchor="end" font-weight="700">'+parts[1]+'</text>';
 });
 s+='<text x="960" y="545" fill="#607080" font-size="7" text-anchor="middle">(click for full compressor panel)</text>';
 s+='</g>';
 s+='<text x="720" y="325" fill="'+(c57.run?'#138a3a':'#c0392b')+'" font-size="8" font-weight="700">OVERHEAD COMPRESSOR '+(c57.run?'RUNNING':'STOPPED')+'</text>';
 s+=pt(1000,265,'FIT-5500',V.fit5500.toFixed(2),'MMSCFD');
