 s+=mValve(1080,310,'xv5755a')+mPipe('M1075 283 V310 H1080')+mPipe('M960 330 V310 H1080');
 s+='<rect x="1000" y="292" width="155" height="42" rx="2" fill="#c6ccd2" opacity="0.96"/>';
