 s+='<text x="700" y="18" fill="#080e18" font-size="14" font-weight="700" text-decoration="underline" letter-spacing="1.5" text-anchor="middle">REFRIG COMPRESSORS (Frick C-1140/41/42)</text>';
 s+=mPipe('M40 60 H970'); /* common suction header -- trimmed at C-1142 suction branch; no dead-end tail */
 s+=mArr(40,60,'',false); s+='<text x="45" y="50" fill="#283038" font-size="7" font-weight="700">FROM V-1441 / PCV-1441A · MAIN SUCTION HEADER</text>';
 s+='<rect x="1050" y="18" width="240" height="38" rx="3" fill="#071018" stroke="#34495e"/><text x="1060" y="30" fill="#9fb0c0" font-size="7">PIC-1441C REFRIG SUCTION SP (8-28 PSIG)</text><g data-act="rsp" data-d="-1" style="cursor:pointer"><rect x="1060" y="36" width="18" height="14" rx="2" fill="#152638" stroke="#54708a"/><text x="1069" y="47" fill="#d8ecff" font-size="11" text-anchor="middle">−</text></g><text x="1190" y="49" fill="#22e34a" font-size="13" font-family="Consolas,monospace" font-weight="700" text-anchor="middle">'+(PLANT.L.PIC1441C.sp||17).toFixed(2)+' PSIG</text><g data-act="rsp" data-d="1" style="cursor:pointer"><rect x="1260" y="36" width="18" height="14" rx="2" fill="#152638" stroke="#54708a"/><text x="1269" y="47" fill="#d8ecff" font-size="11" text-anchor="middle">+</text></g>';
 /* Verified economizer-vapor interstage header: V-1442 top vapor -> PCV-1442 -> compressor interstage. Kept separate from main suction. */
 s+=mPipe('M40 82 H1055'); s+=mArr(40,82,'',false); /* trimmed at C-1142 interstage branch */ s+='<text x="45" y="78" fill="#283038" font-size="6.5" font-weight="700">FROM V-1442 / PCV-1442 · INTERSTAGE HEADER</text>';
 s+=mPipe('M40 260 H1280'); /* common discharge header */
