function alarmHistSave(){try{localStorage.setItem('clearforkAlarmHistory',JSON.stringify(ALARM_HISTORY.slice(-1500)));}catch(_e){}}
function alarmType(m){var x=String(m||'').toUpperCase();return /ESD/.test(x)?'ESD':(/TRIP|SHUTDOWN|HI-HI|LO-LO|HIHI|LOLO/.test(x)?'TRIP':(/ACK|RESET|START|STOP/.test(x)?'EVENT':'ALARM'));}
function alarmHistoryRecord(m){var now=Date.now(),last=ALARM_HISTORY[ALARM_HISTORY.length-1];if(last&&last.m===m&&!last.clearAt){last.lastSeen=now;last.count=(last.count||1)+1;}else ALARM_HISTORY.push({firstIn:now,lastSeen:now,m:m,type:alarmType(m),ackAt:0,clearAt:0,count:1});if(ALARM_HISTORY.length>1500)ALARM_HISTORY.splice(0,ALARM_HISTORY.length-1500);alarmHistSave();}
function alarmHistAck(){var now=Date.now();ALARM_HISTORY.forEach(function(x){if(!x.clearAt&&!x.ackAt)x.ackAt=now;});alarmHistSave();}
function alarmHistClear(){var now=Date.now();ALARM_HISTORY.forEach(function(x){if(!x.clearAt)x.clearAt=now;});alarmHistSave();}
function openAlarmTrend(){var old=document.getElementById('alarmTrendPanel');if(old)old.remove();var el=document.createElement('div');el.id='alarmTrendPanel';el.style.cssText='position:fixed;inset:2vh 2vw;z-index:99999;background:#0b1016;border:1px solid #405060;border-radius:8px;color:#dce6ee;padding:14px;overflow:auto;font:12px Consolas,monospace;';function ts(v){return v?new Date(v).toLocaleString():'—';}function dur(x){var e=x.clearAt||Date.now(),s=x.firstIn||e;var q=Math.max(0,Math.round((e-s)/1000));return q<60?q+'s':(q<3600?(q/60).toFixed(1)+'m':(q/3600).toFixed(1)+'h');}var rows=ALARM_HISTORY.slice().reverse().map(function(x){return '<tr><td>'+ts(x.firstIn)+'</td><td>'+x.type+'</td><td style="min-width:420px">'+String(x.m).replace(/</g,'&lt;')+'</td><td>'+ts(x.ackAt)+'</td><td>'+ts(x.clearAt)+'</td><td>'+dur(x)+'</td><td>'+x.count+'</td></tr>';}).join('');el.innerHTML='<div style="display:flex;justify-content:space-between;align-items:center"><h2>ALARM / EVENT TREND — retained chronological history</h2><button id="alarmTrendClose">CLOSE</button></div><div style="color:#8fa0b0;margin-bottom:10px">ACK does not erase history. RESET marks active events clear. Repeated active calls increment Hits; every later recurrence creates a new chronological event.</div><table style="width:100%;border-collapse:collapse"><thead><tr><th>FIRST IN</th><th>TYPE</th><th>ALARM / EVENT</th><th>ACK</th><th>CLEAR / RESET</th><th>DURATION</th><th>HITS</th></tr></thead><tbody>'+rows+'</tbody></table>';document.body.appendChild(el);document.getElementById('alarmTrendClose').onclick=function(){el.remove();};}
function alarm(m){
 alarmHistoryRecord(m);
 /* Real bug fix (from the ChatGPT alarm-banner note, verified against actual
    behavior before fixing): this used to unshift a new banner row on every
    single call, and several control-loop call sites re-call alarm() with the
    IDENTICAL message every tick for as long as a condition holds -- flooding
    the banner with duplicates instead of behaving like a real DCS (generate
    once, stay active, don't re-announce every second). Fix: if the same exact
    message is still sitting at the top of the log, treat it as the same
    ongoing event and just refresh its timestamp rather than adding a
    duplicate row. A genuinely NEW/different alarm still pushes normally.
    Per-instrument faceplate indicators are unaffected by this -- they already
    compare live PV vs. limits fresh on every render, independent of this log. */
 if(SCEN.log.length&&SCEN.log[0].m===m){SCEN.log[0].t=Date.now();return;}
 SCEN.log.unshift({t:Date.now(),m:m});if(SCEN.log.length>40)SCEN.log.pop();SCEN.acked=false;alarmToast(m);
}
/* Alarms/trips were only visible if you happened to be looking at the scenario log
   inside the EQT board -- any other popup open on top (compressor data, valve info,
   library, etc.) hid them completely. This toast renders at the highest z-index in
   the app, above every other overlay, and stacks so nothing gets missed. */
function alarmToast(m){
 var host=document.getElementById('alarmToastHost');
 if(!host){
  host=document.createElement('div');
  host.id='alarmToastHost';
  host.style.cssText='position:fixed;top:14px;left:50%;transform:translateX(-50%);z-index:100000;display:flex;flex-direction:column;gap:6px;align-items:center;pointer-events:none;max-width:92vw;';
  document.body.appendChild(host);
 }
 var t=document.createElement('div');
 t.style.cssText='background:#3a0e0e;border:1.5px solid #ff5a3c;color:#ffd9c8;padding:9px 18px;border-radius:6px;font:700 13px Consolas,monospace;box-shadow:0 6px 22px rgba(0,0,0,0.55);white-space:nowrap;max-width:92vw;overflow:hidden;text-overflow:ellipsis;';
 t.textContent='\u26a0 '+m;
 host.appendChild(t);
 if(host.children.length>4) host.removeChild(host.firstChild);
 setTimeout(function(){ if(t.parentNode){ t.style.transition='opacity 0.6s'; t.style.opacity='0'; setTimeout(function(){if(t.parentNode)t.parentNode.removeChild(t);},650);} },6000);
}
/* ═══ Gas detection thresholds (added this session): real 5%/10% LEL logic on
   top of the FG_DETECTORS/CMD_FG_STATE pair that already existed (previously
   only a manual Command Center drill tool with no automatic consequence).
   Below 5%: normal. \u226525%... no -- \u22655% LEL: gas alarm (edge-triggered, once
   per rise above threshold, using the same "don't flood the banner" pattern
   as every other alarm() call in this file). \u226510% LEL: this specific
   detector trips the facility ESD (if not already tripped) exactly like every
   other real process trip in this file (PT-1521A, TE-1421A, PDT-1223A, etc.),
   stops rotating equipment, and -- ONLY for the inlet-area detector, since
   that's the one tied to the real slug-catcher-nipple scenario below --
   automatically starts the matching unplanned 8-hour repair outage. These
   Clear Fork thresholds (5%/10%) are operator-provided simulator training
   values, not yet a confirmed fire-and-gas cause-and-effect document -- see
   the Reference Library note on this if one gets added. */
function fgCheckThresholds(){
 var fg=window.CMD_FG_STATE; if(!fg)return;
 if(!fg._alarmed)fg._alarmed={};
 if(!fg._esd)fg._esd={};
 Object.keys(FG_DETECTORS).forEach(function(k){
  var v=fg[k]||0;
  if(v>=5&&!fg._alarmed[k]){fg._alarmed[k]=true;if(!fg.firstOut)fg.firstOut=k;alarm('GAS ALARM \u2014 '+k+' \u2014 5% LEL or higher (area gas detector)');}
  if(v<5&&fg._alarmed[k])fg._alarmed[k]=false; /* allow a fresh alarm if it climbs again after clearing */
  if(v>=10){
   if(!PLANT.esd){
    PLANT.esd=true;
    alarm('*** GAS ESD \u2014 '+k+' at 10%+ LEL \u2014 facility ESD activated on gas detection ***');
    ['c41','c42','c61','c62','c63','c57'].forEach(function(kk){if(PLANT.cmp[kk])(PLANT.cmp[kk].run=false,cfResetInletStopped12MF(PLANT.cmp[kk]));});
    if(EXP)EXP.run=false;
    /* Deliberately re-asserts every tick the reading is still \u226510% and ESD
       has been cleared out from under it (e.g. someone hit the generic ESD
       RESET button while the gas reading itself never actually came down) --
       a real gas ESD can't be reset away just because the alarm banner was
       cleared. alarm() already dedupes an identical repeated message, so
       this doesn't flood the log even though it re-checks every second. */
   }
   if(!fg._esd[k]){fg._esd[k]=true;if(k==='GD_INLET_01'&&!PLANT.outageState.gas_slugnip_repair)outageStart('gas_slugnip_repair');}
  }
  if(v<10&&fg._esd[k])fg._esd[k]=false;
 });
}
function snapshot(){return {flow:PLANT.in.flow,c41:PLANT.cmp.c41.step,c42:PLANT.cmp.c42.step,cres:PLANT.cmp.c61.step+PLANT.cmp.c62.step+PLANT.cmp.c63.step,pic1521sp:PLANT.L.PIC1521.sp};}
var EVENTS={
 EXP_TRIP:{name:'Expander trip (EX-1121)',hint:'Pressure let-down lost \u2014 demethanizer pressure is climbing and expander refrigeration is gone. Reduce throughput and manage demeth pressure.',
  fire:function(){if(EXP)EXP.run=false;alarm('EVENT: Expander EX-1121 TRIPPED');},
  checks:function(s){return [['Reduce plant throughput \u2265 20 MMSCFD',PLANT.in.flow<=s.flow-20],['Demeth pressure PIC-1521 to MAN or SP lowered',PLANT.L.PIC1521.man||PLANT.L.PIC1521.sp<s.pic1521sp-3],['Demeth pressure held below 350 psig',PLANT.L.PIC1521.pv<350]];}},
 PIG_SLUG:{name:'Liquid slug from pig run',hint:'A pig is pushing a liquid slug into the slug catchers / cold separator. Cut throughput and drain levels before the cold separator floods and carries over to the expander.',
  fire:function(){SCEN.slug=25;alarm('EVENT: Liquid slug inbound (pig run)');},
  checks:function(s){return [['Reduce plant throughput \u2265 20 MMSCFD',PLANT.in.flow<=s.flow-20],['Cold separator kept below carryover (92%)',PLANT.L.LIC1421.pv<92],['LIC-1421 actively draining (MAN or CV>55%)',PLANT.L.LIC1421.man||PLANT.L.LIC1421.out>55]];}},
 LOSS_INLET:{name:'Inlet compressor trip',hint:'Lost an inlet compressor \u2014 the running machine\u2019s discharge will climb to HI-HI and trip too unless throughput is cut.',
  fire:function(){var k=PLANT.cmp.c41.run?'c41':'c42';if(!PLANT.cmp.c41.run&&!PLANT.cmp.c42.run)return;(PLANT.cmp[k].run=false,cfResetInletStopped12MF(PLANT.cmp[k]));alarm('EVENT: '+PLANT.cmp[k].name+' TRIPPED');},
  checks:function(s){return [['Reduce plant throughput \u2265 30 MMSCFD',PLANT.in.flow<=s.flow-30],['No cascade (an inlet machine still running)',(PLANT.cmp.c41.run||PLANT.cmp.c42.run)],['Inlet discharge below HI-HI (1075)',Math.max(PLANT.cmp.c41.run?PLANT.cmp.c41.dis:0,PLANT.cmp.c42.run?PLANT.cmp.c42.dis:0)<1075]];}},
 LOSS_RESIDUE:{name:'Residue compressor trip',hint:'Lost a residue compressor \u2014 header pressure is rising. Raise load steps on the remaining machines and cut throughput, or they trip on HI-HI discharge.',
  fire:function(){var ks=['c61','c62','c63'].filter(function(k){return PLANT.cmp[k].run;});if(!ks.length)return;PLANT.cmp[ks[0]].run=false;alarm('EVENT: '+PLANT.cmp[ks[0]].name+' TRIPPED');},
  checks:function(s){return [['Reduce plant throughput \u2265 30 MMSCFD',PLANT.in.flow<=s.flow-30],['No cascade (\u2265 2 residue machines running)',['c61','c62','c63'].filter(function(k){return PLANT.cmp[k].run;}).length>=2],['Residue header below HI-HI (1060)',PLANT.v.resHdr<1060]];}},
 HOTOIL_TRIP:{name:'Hot oil heater trip (H-7100)',hint:'Lost reboiler heat \u2014 demethanizer bottoms are falling, so C2 can no longer be rejected and creeps into the NGL. Cut throughput so residual heat holds the bottoms.',
  fire:function(){PLANT.in.heaterRun=false;alarm('EVENT: Hot oil heater H-7100 TRIPPED — heater shut down');},
  checks:function(s){return [['Reduce plant throughput \u2265 30 MMSCFD',PLANT.in.flow<=s.flow-30],['Bottoms held above 150 \u00b0F',PLANT.v.demBot>150],['C2 in NGL kept in spec (< 4 mol%)',PLANT.v.c2ngl<4]];}},
 GAS_LEAK:{name:'Gas leak / area gas alarm',hint:'Combustible gas detected at the compressor building \u2014 inlet pressure is bleeding off. Cut throughput hard (toward ESD) and isolate the inlet.',
  fire:function(){alarm('EVENT: Combustible gas leak detected');},
  checks:function(s){return [['Cut throughput \u2265 60 MMSCFD (toward ESD)',PLANT.in.flow<=s.flow-60],['Isolate the inlet (PV-1010 closed)',!PLANT.valves.pv1010]];}},
 REFRIG_TRIP:{name:'Refrigeration compressor trip',hint:'Lost a propane refrig compressor \u2014 the chiller is warming, the cold separator warms and NGL recovery drops. Reduce throughput to match remaining refrigeration.',
  fire:function(){if(QHD){var ks=['c1142','c1141','c1140'];for(var i=0;i<ks.length;i++){if(QHD.units[ks[i]]){QHD.units[ks[i]]=0;alarm('EVENT: Refrig compressor '+ks[i].toUpperCase()+' TRIPPED');return;}}}alarm('EVENT: Refrig compressor tripped');},
  checks:function(s){return [['Reduce plant throughput \u2265 20 MMSCFD',PLANT.in.flow<=s.flow-20],['Chiller recovered below -2 \u00b0F',PLANT.v.chill<-2]];}},
 EXP_OVERSPEED_PUSH:{name:'Expander pushed hard \u2014 ethane creeping into NGL',hint:'The expander IGV has been run wide open chasing extra liquid volume, and ethane is now slipping into the NGL faster than the trim reboiler can reject it. Back the IGV down or raise TIC-1225 to hold spec.',
  fire:function(){if(EXP){EXP.igv=100;} alarm('EVENT: Expander run wide open \u2014 C2 in NGL trending up');},
  checks:function(s){return [['C2 in NGL brought back into spec (< 3 mol%)',PLANT.v.c2ngl<3],['Either IGV backed off or TIC-1225 raised to compensate',(EXP&&EXP.igv<95)||PLANT.L.TIC1225.sp>s.pic1521sp||PLANT.L.TIC1225.pv>176]];}},
 RSV_LOOP_PLUG:{name:'RSV recycle filter plugging (F-1438)',hint:'F-1438 on the RSV recycle loop is fouling \u2014 differential pressure is climbing and recycle flow back to the inlet and demethanizer is falling off, hurting recovery. Cut throughput until the filter can be swapped.',
  fire:function(){alarm('EVENT: F-1438 RSV recycle filter differential pressure rising \u2014 recycle flow falling');},
  checks:function(s){return [['Reduce plant throughput \u2265 15 MMSCFD to protect recovery',PLANT.in.flow<=s.flow-15],['NGL rate held above 10 MMSCFD despite the lost recycle',PLANT.v.nglRate>10]];}},
 ETHANE_MARKET_CALL:{name:'Ethane market call \u2014 switch toward recovery',hint:'Ethane pricing has turned favorable and the pipeline wants more ethane recovered instead of rejected. Switch HS-1224B to RECOVERY and back off the trim reboiler duty so more ethane stays in the NGL.',
  fire:function(){PLANT.mode='FULL REJECTION';alarm('EVENT: Ethane market call \u2014 pipeline requesting RECOVERY mode');},
  checks:function(s){return [['HS-1224B switched to RECOVERY',PLANT.mode==='RECOVERY'],['C2 in NGL raised toward recovery levels (> 4 mol%)',PLANT.v.c2ngl>4]];}},
 SLUG_NIPPLE_LEAK:{name:'Slug catcher nipple failure \u2014 gas release',hint:'A small-bore nipple on the inlet slug catcher piping has failed \u2014 high-pressure gas is releasing into the inlet area. GD_INLET_01 (the inlet-area gas detector) climbs on its own from here; get ahead of it by isolating the inlet (PV-1010) and cutting throughput BEFORE it reaches 10% LEL. If it reaches 10%, the plant ESDs on gas detection automatically \u2014 no operator action needed to trip it \u2014 and this becomes an unplanned ~8-hour repair outage (see Outages panel), not a normal restart.',
  fire:function(){window.CMD_FG_STATE.GD_INLET_01=1.5;alarm('EVENT: Small-bore nipple failure \u2014 inlet slug catcher piping \u2014 gas release in progress');},
  checks:function(s){return [
   ['Inlet isolated (PV-1010 closed)',!(PLANT.valves&&PLANT.valves.pv1010)],
   ['Throughput cut \u2265 20 MMSCFD before/at the gas ESD',PLANT.in.flow<=s.flow-20||PLANT.esd],
   ['Gas alarm acknowledged',SCEN.acked||!SCEN.log.length]
  ];}}
};
function fireEvent(id){if(SCEN.active)return;var ev=EVENTS[id];if(!ev)return;SCEN.active=id;SCEN.t=0;SCEN.snap=snapshot();SCEN.result=null;SCEN._cs=0;ev.fire();}
function evalEvent(){if(!SCEN.active)return;var ev=EVENTS[SCEN.active];var chk=ev.checks(SCEN.snap);var done=0;chk.forEach(function(c){if(c[1])done++;});SCEN.result={name:ev.name,checks:chk,score:done,total:chk.length,ok:done>=chk.length};}
function scenClear(){
 if(SCEN.active==='SLUG_NIPPLE_LEAK'){var fg=window.CMD_FG_STATE;fg.GD_INLET_01=0;if(fg._alarmed)fg._alarmed.GD_INLET_01=false;if(fg._esd)fg._esd.GD_INLET_01=false;if(fg.firstOut==='GD_INLET_01')fg.firstOut=null;}
 SCEN.active=null;SCEN.t=0;SCEN.slug=0;SCEN.result=null;SCEN._cs=0;
}
function scenBar(){
 /* collapsed: one-line pill that gets out of the way */
 if(SCEN.hidden){
  var dot=SCEN.active?'<span style="color:#ff9a3c;margin:0 4px">&#9888; '+EVENTS[SCEN.active].name+'</span>':'';
  return '<div class="scen" style="padding:3px 8px;display:flex;align-items:center;gap:6px;">'+
   '<button data-act="scshow" style="padding:1px 8px;font-size:10px;">&#9660; Scenario drills</button>'+dot+'</div>';
 }
 var s='<div class="scen" style="position:relative">';
 s+='<button data-act="schide" style="position:absolute;right:4px;top:4px;padding:1px 8px;font-size:10px;" title="Minimize scenario panel">&#9650; Hide</button>';
 s+='<b>Scenario drills</b> &mdash; inject a random upset, then mitigate it. ';
 s+='<button data-act="sctgl">'+(SCEN.auto?'Auto-random: ON':'Auto-random: OFF')+'</button>';
 s+='<button data-act="scfire" data-e="EXP_TRIP">Expander trip</button><button data-act="scfire" data-e="PIG_SLUG">Pig slug</button><button data-act="scfire" data-e="LOSS_INLET">Inlet comp trip</button><button data-act="scfire" data-e="LOSS_RESIDUE">Residue comp trip</button><button data-act="scfire" data-e="HOTOIL_TRIP">Hot oil trip</button><button data-act="scfire" data-e="GAS_LEAK">Gas leak</button><button data-act="scfire" data-e="REFRIG_TRIP">Refrig trip</button><button data-act="scfire" data-e="EXP_OVERSPEED_PUSH">Expander pushed hard</button><button data-act="scfire" data-e="RSV_LOOP_PLUG">RSV filter plugging</button><button data-act="scfire" data-e="ETHANE_MARKET_CALL">Ethane market call</button><button data-act="scfire" data-e="SLUG_NIPPLE_LEAK">Slug catcher nipple leak</button><button data-act="scrand">Random</button>';
 if(SCEN.active){var ev=EVENTS[SCEN.active];s+='<div class="scact">&#9888; ACTIVE ('+SCEN.t+'s): <b>'+ev.name+'</b> &mdash; '+ev.hint+'<br><button data-act="sceval">Evaluate my response</button><button data-act="scclr">Clear scenario</button></div>';}
 if(SCEN.result){var r=SCEN.result;s+='<div class="scres '+(r.ok?'good':'bad')+'"><b>'+(r.ok?'\u2714 Handled correctly':'\u2718 Mitigation incomplete')+'</b> ('+r.score+'/'+r.total+')<ul>';r.checks.forEach(function(c){s+='<li>'+(c[1]?'\u2714':'\u2718')+' '+c[0]+'</li>';});s+='</ul></div>';}
 return s+'</div>';}
