function computeNotifications(){var V=PLANT.v,L=PLANT.L;
 /* Ryan Notification Center -- built from a ChatGPT "Master Update" ask (this
    message). Same standing position as every big copy-paste before it: real,
    buildable core only. Deliberately NOT built (explained where each is skipped
    below rather than faked): a "learns your operating style" pattern-recognition
    engine (this is a single offline HTML file with no persistence substrate for
    genuine cross-session learning -- localStorage/IndexedDB aren't wired for
    behavioral history, only the existing Ryan Core facts pool is), and automatic
    "maintenance due" notifications (no real last-serviced timestamp exists for any
    equipment in this file, so a countdown would have to assume "just serviced now"
    at page load, which is fabricated, not real).
    Smart filtering IS real: PY-1623/1624 and low residue suction only escalate to
    a notification after being sustained past a threshold (tracked against the real
    PLANT.simSeconds clock), not on the first tick they're true -- matching the
    literal "don't notify on PV-6050A opening, only if it stays open" example from
    the spec. Threshold values (60 sim-sec) are simulator-tuning choices for a
    reasonable demo pace, not confirmed real Clear Fork alarm-delay setpoints --
    labeled as such wherever shown. */
 if(PLANT.notifSince==null)PLANT.notifSince={};
 if(PLANT.notifDismissed==null)PLANT.notifDismissed={};
 if(PLANT.notifSnoozeUntil==null)PLANT.notifSnoozeUntil={};
 var now=PLANT.simSeconds||0;
 var SUSTAIN=60; /* sim-seconds; simulator tuning choice, not a real Clear Fork delay setpoint */
 function track(id,cond){
  if(cond){if(PLANT.notifSince[id]==null)PLANT.notifSince[id]=now;}
  else{PLANT.notifSince[id]=null;}
  return cond && PLANT.notifSince[id]!=null && (now-PLANT.notifSince[id])>=SUSTAIN;
 }
 var notifs=[];
 function add(id,sev,cat,msg){
  if(PLANT.notifDismissed[id])return;
  if(PLANT.notifSnoozeUntil[id]&&now<PLANT.notifSnoozeUntil[id])return;
  notifs.push({id:id,sev:sev,cat:cat,msg:msg});
 }
 if(PLANT.esd)add('esd','CRITICAL','Recommendation','Facility ESD is active -- review before restart');
 Object.keys(PLANT.redtag||{}).forEach(function(k){if(PLANT.redtag[k])add('redtag_'+k,'NORMAL','Maintenance',k.toUpperCase()+' remains red-tagged');});
 if(track('lowsuction',!!(L.PIC6050B&&L.PIC6050B.pv<250))){
  add('lowsuction','HIGH','Recommendation','Residue recycle has remained elevated for a while -- consider checking plant throughput and compressor loading');
 }
 if(track('py1623',!V.py1623ok)){
  add('py1623','HIGH','Recommendation','PY-1623 flow permit blocked -- FT-1422 below 265.00 GPM; PCV-1623 forced closed until FT-1422 exceeds 291.50 GPM');
 }
 if(track('py1624',!V.py1624ok)){
  add('py1624','HIGH','Recommendation','PY-1624 flow permit blocked -- FT-1422 below 265.00 GPM; PCV-1624 forced closed until FT-1422 exceeds 291.50 GPM');
 }
 if(V.lshh1460)add('lshh1460','CRITICAL','Recommendation','V-1460 fuel gas scrubber has an abnormal level -- LSHH-1460 tripped');
 /* Alarm intelligence: group recent SCEN.log entries by a shared tag-root instead
    of listing near-duplicates one by one. */
 var groups={};
 (SCEN.log||[]).slice(0,10).forEach(function(e){
  var m=e.m.match(/([A-Z]+-\d+)/);
  var key=m?m[1].replace(/[A-Z]$/,''):null;
  if(key){groups[key]=(groups[key]||0)+1;}
 });
 Object.keys(groups).forEach(function(k){if(groups[k]>=3)add('grp_'+k,'NORMAL','Information',groups[k]+' recent alarms are all related to '+k);});
 Object.keys(FILTER_RULES||{}).forEach(function(k){var r=FILTER_RULES[k],dp=filterDP(k),svc=filterInService(k);if(!svc&&['inlet','residue','rsv','hotoil'].indexOf(r.group)<0)return;if(r.trip!=null&&dp>=r.trip)add('filter_trip_'+k,'CRITICAL','Maintenance',r.name+' DP '+dp.toFixed(1)+' '+r.unit+' — shutdown threshold '+r.trip+' reached');else if(r.change!=null&&dp>=r.change)add('filter_change_'+k,'HIGH','Maintenance',r.name+' DP '+dp.toFixed(1)+' '+r.unit+' — send operator to change/swap filter');});
 if(notifs.length===0)add('ok','INFO','Information','No notifications -- plant conditions nominal');
 return notifs;
}
function schedHolidayInfo(ds){
 /* US federal holiday display for My Schedule. Uses actual calendar dates plus
    the standard observed weekday when a fixed-date holiday lands on a weekend. */
 var d=new Date(ds+'T00:00:00');
 var y=d.getFullYear();
 function key(dt){return dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0')+'-'+String(dt.getDate()).padStart(2,'0');}
 function observed(month,day){var x=new Date(y,month,day);var dow=x.getDay();if(dow===6)x.setDate(x.getDate()-1);else if(dow===0)x.setDate(x.getDate()+1);return key(x);}
 function nthDow(month,dow,n){var x=new Date(y,month,1);var add=(dow-x.getDay()+7)%7;x.setDate(1+add+(n-1)*7);return key(x);}
 function lastDow(month,dow){var x=new Date(y,month+1,0);x.setDate(x.getDate()-((x.getDay()-dow+7)%7));return key(x);}
 var holidays={};
 holidays[observed(0,1)]='New Year\'s Day';
 holidays[nthDow(0,1,3)]='Martin Luther King Jr. Day';
 holidays[nthDow(1,1,3)]='Presidents Day';
 holidays[lastDow(4,1)]='Memorial Day';
 holidays[observed(5,19)]='Juneteenth';
 holidays[observed(6,4)]='Independence Day';
 holidays[nthDow(8,1,1)]='Labor Day';
 holidays[nthDow(9,1,2)]='Columbus Day';
 holidays[observed(10,11)]='Veterans Day';
 holidays[nthDow(10,4,4)]='Thanksgiving Day';
 holidays[observed(11,25)]='Christmas Day';
 return holidays[ds]||'';
}
function schedIsPayday(ds){
 /* Biweekly Wednesday payday cadence supplied by the operator, anchored to
    Wednesday 2026-08-12. Only exact 14-day intervals on/after the anchor count. */
 var anchor=new Date('2026-08-12T00:00:00');
 var d=new Date(ds+'T00:00:00');
 var diff=Math.round((d-anchor)/86400000);
 return diff>=0&&diff%14===0;
}
