 s+='<div class="poc" style="margin:0 auto;max-width:680px;"><div class="pott">PRODUCTION SUMMARY (live, real tags)</div>';
 s+=row('Inlet Flow',(PI.flow||0).toFixed(1),'MMSCFD',sparkline('flow',70,18,'#5fa8f5'));
 s+=row('Residue Sales Flow',(V.resRate||0).toFixed(1),'MMSCFD',sparkline('resrate',70,18,'#e08a3f'));
