 eqRows.forEach(function(r){var tagged=r[2]&&PLANT.redtag&&PLANT.redtag[r[2]];var fk=r[3];
  s+='<div class="por" '+(fk?'data-act="flyto3d" data-k="'+fk+'" style="cursor:pointer;"':'')+'><span>'+r[0]+(fk?' \u2197':'')+'</span><b style="color:'+(tagged?'#c0392b':(r[1]?'#1ea84a':'#8a9098'))+';">'+(tagged?'RED TAGGED':(r[1]?'RUNNING':'STANDBY/STOPPED'))+'</b></div>';});
 s+='</div>';
