function mSVG(inner){return '<div class="mwrap"><svg viewBox="0 0 1040 565" style="width:100%;height:auto;max-height:56vh;background:#0d1116;border:1px solid #1c242c;border-radius:6px;display:block;">'+inner+'</svg><div class="mlegend">&#9656; Valves: <span style="color:#3fae5f">green = open</span>, <span style="color:#c0504a">red = closed</span> &mdash; click a valve to operate it. Live values track the plant.</div></div>';}
function mPipe(d,on){return '<path d="'+d+'" fill="none" stroke="'+(on===false?'#46505a':'#8a96a2')+'" stroke-width="3"/>';}
function mDrum(x,y,w,hh,lab){var r=hh/2;return '<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+hh+'" rx="'+r+'" ry="'+r+'" fill="#1b2530" stroke="#9fb0c0" stroke-width="2"/><text x="'+(x+w/2)+'" y="'+(y+hh/2+4)+'" fill="#cfe0f0" font-size="11" text-anchor="middle">'+lab+'</text>';}
function mCol(x,y,w,hh,lab){var s='<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+hh+'" rx="7" fill="#1b2530" stroke="#9fb0c0" stroke-width="2"/>';for(var i=1;i<6;i++){var yy=y+hh*i/6;s+='<line x1="'+x+'" y1="'+yy+'" x2="'+(x+w)+'" y2="'+yy+'" stroke="#33414e" stroke-width="1"/>';}return s+'<text x="'+(x+w/2)+'" y="'+(y+hh+14)+'" fill="#bcd6ee" font-size="11" text-anchor="middle">'+lab+'</text>';}
function mExch(x,y,w,hh,lab){var s='<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+hh+'" fill="#172029" stroke="#9fb0c0" stroke-width="2"/>';var zg='M'+(x+6)+' '+(y+hh/2);for(var i=0;i<6;i++){zg+=' L'+(x+6+(i+0.5)*(w-12)/6)+' '+(y+(i%2?hh-8:8))+' L'+(x+6+(i+1)*(w-12)/6)+' '+(y+hh/2);}s+='<path d="'+zg+'" fill="none" stroke="#5d6b78" stroke-width="2"/>';return s+'<text x="'+(x+w/2)+'" y="'+(y+hh+13)+'" fill="#bcd6ee" font-size="10" text-anchor="middle">'+lab+'</text>';}
function mComp(x,y,lab){return '<circle cx="'+x+'" cy="'+y+'" r="21" fill="#202a36" stroke="#9fb0c0" stroke-width="2"/><path d="M'+(x-11)+' '+(y-10)+' L'+(x+13)+' '+y+' L'+(x-11)+' '+(y+10)+' Z" fill="#3a4a5c"/><text x="'+x+'" y="'+(y+36)+'" fill="#bcd6ee" font-size="10.5" text-anchor="middle">'+lab+'</text>';}
