    '<text x="'+(rbx+72)+'" y="'+(rby+63)+'" fill="#283038" font-size="7.5" text-anchor="middle">Stabilizer</text>'+
    '<text x="'+(rbx+72)+'" y="'+(rby+74)+'" fill="#283038" font-size="7.5" text-anchor="middle">Reboiler</text>'+
    '<text x="'+(rbx+72)+'" y="'+(rby+108)+'" fill="#eef6ff" font-size="10" font-family="Consolas,monospace" text-anchor="middle" font-weight="700">'+rebLvl.toFixed(2)+'%</text>';
 s+=pt(rbx-98,315,'LIT-5040A',rebLvl.toFixed(2),'%',['L','H']);
 /* Tower bottoms enter E-5040; vapor returns to tower middle, stabilized liquid continues through E-5020 shell side then AC-5055. */
 s+=mPipe('M'+(tx+tw)+' '+(ty+th*0.75)+' H'+rbx);
 s+=mPipe('M'+rbx+' '+(rby+35)+' H'+(tx+tw)+' V'+(ty+th*0.47));
 s+='<text x="500" y="250" fill="#283038" font-size="6.5">E-5040 VAPOR RETURN → T-5030 MIDDLE</text>';
 s+=mPipe('M'+(rbx+145)+' '+(rby+92)+' H920 V495 H345');
 /* E-5020 shell-side process is represented by the exchanger core itself; do not draw a pipe across the exchanger face. */
