 keys.forEach(function(k){var r=PB[k],S=SPECIES[k];if(r){caught++;var col=GCOL[r.g]||'#cdd2da';rows+='<div style="display:flex;justify-content:space-between;align-items:center;padding:3px 0;border-bottom:1px solid rgba(255,255,255,0.05);"><span style="color:#dde3ea;">'+S.n+(r.dia?' ◆':'')+'</span><span style="white-space:nowrap;"><b>'+r.len.toFixed(1)+'″</b> <span style="color:#9aa3b0;">'+r.wt.toFixed(1)+'lb</span> <span style="font-size:9.5px;font-weight:700;color:#10131a;background:'+col+';padding:1px 7px;border-radius:20px;">'+r.g+'</span></span></div>';}else{rows+='<div style="display:flex;justify-content:space-between;padding:3px 0;border-bottom:1px solid rgba(255,255,255,0.05);color:#5b636d;"><span>'+S.n+'</span><span>—</span></div>';}});
 pbpanel.innerHTML='<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;"><span style="font-weight:600;font-size:14px;">Personal Best Log</span><span id="pbclose" style="cursor:pointer;color:#9aa3b0;font-size:18px;line-height:1;">×</span></div><div style="font-size:11px;color:#9aa3b0;margin-bottom:8px;">'+caught+'/'+keys.length+' species · '+(PB.__landed||0)+' landed · '+(PB.__snapped||0)+' lines snapped</div><div style="font-size:11.5px;max-height:46vh;overflow:auto;">'+rows+'</div>';
