 xv1040a:{title:'XV-1040A',items:[
  {tag:'Plant_ESD',desc:'Main Plant ESD',ok:function(){return !PLANT.esd;}},
  {tag:'PIT-1040A',desc:'Vortex Separator (V-1040) Inlet Gas Pressure High-High Shutdown (setpoint Requires Verification)',ok:function(V,L){return (V.pit1040b==null?446.90:V.pit1040b)<650;} /* V-1040 is the vortex separator near the slug catchers, upstream of XV-1410/V-1410 -- correctly tied to the same ~445 psig inlet pressure zone as the real PIT-1040A display, not V-1410's separate ~995 psig zone downstream. Caught during testing: an earlier version of this check mistakenly used V.p1410 (V-1410's pressure, a different vessel further downstream), which would have permanently shown this permissive as failed against the real 995.9 psig reading -- fixed before shipping. */},
  {tag:'LIT-1040B',desc:'Vortex Separator (V-1040) Level High-High Shutdown',ok:function(V){return V.lit1040b<85;},
   cause:'V-1040 liquid level exceeded the shutdown limit.',
   purpose:'Prevent liquid carryover to the inlet compressors.',
   possibleCauses:['High liquid loading','Drain valve failed','Outlet blocked','Stabilizer unavailable','Pipeline slug'],
   operatorActions:['Verify LIC-1040A.','Check the outlet drain.','Verify the stabilizer is accepting liquids.','Monitor compressor suction.'],
   protects:['Inlet Compressors','V-1410','F-1412','Dehydration System'],
   affectedBy:['Plant ESD','V-1040 Level','V-1040 Pressure','Instrument Air']},
  {tag:'PIT-9241A',desc:'Instrument Air Header Pressure Low-Low Shutdown — PIT-9241A verified LOLO 75 psig facility ESD; LO 90 psig; HI 160 psig; normal ~126.6 psig',ok:function(){return true;}},
  {tag:'LDAHH-1020',desc:'Slug Catcher #1 Level Rate-of-Change High-High Shutdown (setpoint Requires Verification -- no rate-of-change tracking exists yet for this level, so shown healthy by default rather than guessed)',ok:function(){return true;}},
  {tag:'LDAHH-1025',desc:'Slug Catcher #2 Level Rate-of-Change High-High Shutdown (same limitation as LDAHH-1020)',ok:function(){return true;}},
  {tag:'LDAHH-1030',desc:'Slug Catcher #3 Level Rate-of-Change High-High Shutdown (same limitation as LDAHH-1020)',ok:function(){return true;}},
 ]},
 xv1040b:{title:'XV-1040B (V-1040 drain valve)',items:[
  {tag:'Plant_ESD',desc:'Main Plant ESD',ok:function(){return !PLANT.esd;}},
  {tag:'LIT-1040B',desc:'Vortex Separator (V-1040) Level Low-Low Shutdown',ok:function(V){return V.lit1040b>3;},
   cause:'V-1040 liquid level dropped to the low-low limit.',
   purpose:'Stop draining before the drain valve can pass gas (gas blow-through / drain-valve cavitation risk), and protect against loss of the liquid seal.',
   possibleCauses:['Drain valve stuck open','Level transmitter fault','Unusually low liquid inflow','LIC-1040A tuning/setpoint issue'],
   operatorActions:['Verify LIC-1040A output and mode.','Confirm XV-1040B has actually closed.','Check LIT-1040B against LIC-1040 for agreement.','Do not force the drain open until level recovers.'],
   protects:['Downstream drain/vent piping from gas blow-through'],
   affectedBy:['Plant ESD','V-1040 Level (low side only)'],
   note:'This is a LOCAL trip -- confirmed behavior: low-low here closes ONLY XV-1040B and stops draining. It does not by itself ESD the facility. A separate V-1040 HIGH-HIGH level condition (see the XV-1040A interlock list, LIT-1040B high-high) is the one that escalates further -- the same transmitter drives two different consequences depending on which limit is crossed.'},
  {tag:'PIT-9241A',desc:'Instrument Air Header Pressure Low-Low Shutdown — PIT-9241A verified LOLO 75 psig facility ESD; LO 90 psig; HI 160 psig; normal ~126.6 psig',ok:function(){return true;}},
  {tag:'LSHH-8100',desc:'Closed Drain Tank (V-8100/TK-8100) Level High-High Shutdown (setpoint Requires Verification -- no V-8100 level physics modeled yet, so shown healthy by default rather than guessed)',ok:function(){return true;}},
  {tag:'PIT-8100A',desc:'Closed Drain Tank Pressure High-High Shutdown (setpoint Requires Verification -- using 20 psig as a placeholder against the real modeled ~4.3 psig normal operating pressure)',ok:function(V){return (V.pit8100a==null)||V.pit8100a<20;}},
  {tag:'XV1040B_PID_CTRL_PERMISSIVE',desc:'LIC-1040A output not at 0% (required for opening logic, same pattern as ESD-1000D/PIC-1010A)',ok:function(V,L){return L.LIC1040.out>0.5;}},
 ]},
