 /* Dedicated bottom controller strip: keep process drawing clear and preserve the plant HMI convention. */
 s+='<rect x="18" y="565" width="1044" height="185" rx="4" fill="#b8c0c7" stroke="#7a858f"/><text x="540" y="582" fill="#283038" font-size="9.5" font-weight="700" text-anchor="middle">REFRIGERATION CONTROLLERS — SUCTION SP '+Number(QHD.capSP).toFixed(2)+' PSIG</text>';
 s+=ctl(35,592,'PIC-1441A','PIC1441','PSIG');
