 var isRes=c.type==='residue';var nInl=(PLANT.cmp.c41.run?1:0)+(PLANT.cmp.c42.run?1:0);function _ldStep(c){return c&&c.run?cfLoadFraction(c)*100:0;} var inlLd=(_ldStep(PLANT.cmp.c41)+_ldStep(PLANT.cmp.c42))/100;
 var ch=[];
 ch.push(['Facility ESD not active',!PLANT.esd,'An ESD is latched \u2014 the whole facility is tripped. Press RESET on the alarm bar at the bottom, then start.']);
