var CF_SOURCE_12KK={"build":"12KK","baseline":"12KJ","date":"2026-10-13","policy":"Source-qualified geometric mounting and delta-only reference update. Preserve process controls, operating limits, saved history, component identities and existing relief piping. No fabricated feedback, engineering certification or new plant procedure. Photos and PDF bytes are not bundled.","instrumentMounts":[{"key":"it_te5020f","tag":"TE-5020F","pipeKey":"hm_stab_e5020_to_ac5055","routeId":"pipe12hn_348","oldCenter":[83,5.4,-107.6],"center":[89.5,5.9,-107.6],"direction":[0,0,1],"normal":[1,0,0],"radius":0.16666666666666666,"leg":4,"service":"E-5020 cooled process-bottoms outlet after shell nozzle N2, before AC-5055 N1"},{"key":"it_ti5020e","tag":"TI-5020E","pipeKey":"hm_stab_e5020_to_ac5055","routeId":"pipe12hn_348","oldCenter":[83,5.4,-110.8],"center":[89.5,5.9,-110.8],"direction":[0,0,1],"normal":[1,0,0],"radius":0.16666666666666666,"leg":4,"service":"E-5020 cooled process-bottoms local temperature indication on the same 1181 line"},{"key":"it_pi5020b","tag":"PI-5020B","pipeKey":"hm_stab_e5020_to_ac5055","routeId":"pipe12hn_348","oldCenter":[83,3.2,-112],"center":[89.5,3.2,-112],"direction":[0,1,0],"normal":[1,0,0],"radius":0.16666666666666666,"leg":3,"service":"E-5020 cooled process-bottoms local pressure gauge on the 1181 riser"}],"mountingBasis":"Retained M2514 (12IT) identifies the three instruments on cooled bottoms after E-5020 N2. The 12IV M2520 correction moved their named host 1181 line to x89.5/y5.9 but reinstalled only the shell outlet manual valve, leaving these three old instrument coordinates. Move the existing owned assemblies and labels to that exact named host; do not choose a nearby unrelated line. Physical elevations remain schematic.","plate":{"id":"PLATE-PSV6302-IMG0710-12KK","key":"nameplate_psv6x02_12kk","sourcePhoto":"IMG_0710.jpeg","sha256":"1d563748cb61a010c1b83db25b287287536c22630bbcfb61504454c31d5f0fab","primaryTag":"PSV-6302","sharedTags":["PSV-6202","PSV-6102"],"manufacturer":"Anderson Greenwood Crosby","otherMarking":"EMRT","model":"45312N46/S1","serial":"1101-1909-206741","setPressurePSIG":845,"capacitySCFMAir":78005,"sizeMarking":"4 IN","trimRaw":"S V V V","fields":[["Manufacturer","Anderson Greenwood Crosby"],["Additional marking","EMRT"],["Model","45312N46/S1"],["Set pressure","845 PSIG"],["Capacity","78,005 SCFM AIR (plate rating medium)"],["Size marking","4 IN"],["Trim marking","S V V V"],["Visible certification marks","ASME / UV / NB marks; no separate readable registration number in the crop"]],"association":"Operator identifies IMG_0710 as PSV-6302 and states all specification values apply to PSV-6202 and PSV-6102 except serial number. Plant tags are not visible on this close-up. Photograph serial belongs only to PSV-6302; sister serials remain independent.","limits":["SCFM AIR is the printed capacity-rating medium, not proof of instrument-air service, installed gas flow, relief adequacy or a natural-gas capacity conversion.","Size 4 IN does not by itself establish both end sizes/classes or orifice area. Retain 4-inch Class600 inlet / 6-inch Class150 outlet / N-orifice only as existing drawing evidence.","Protected V-6103/V-6203/V-6303 first-stage discharge pressure zones, isolation identities and modeled V-8110 continuation remain drawing-derived. No current lineup, certified hydraulics or test status is established.","845 psig agrees with the retained reference setting; no live alarm/trip, logic, setpoint, PSV geometry or flow path is changed."],"missing":["Individual serial-number plates for PSV-6102 and PSV-6202, unless independently recorded later.","Current controlled relief/test records and wide tagged views confirming plate-to-valve identity, protected equipment, isolation and actual outlet destination."]},"petroSkills":{"sourceFile":"2026-07-29 17-36(3).pdf","sha256":"5cfd471e3e74b9f87a50aa957987fbc031265a8a7ab8fc6e5b97a32e88a9da94","printedRange":"26-3 through 26-19","pdfPages":17,"distinctPrintedPages":17,"duplicateViews":0,"existingSummaryKey":"ps_key_adsorbers","associatedCategory":"Dehydration & Regen","addedDetails":[{"id":"PS26-12KK-01","targetInfoKey":"ps_ads_materials_12kk","title":"Capacity, efficiency and adsorbent form","sourceFile":"2026-07-29 17-36(3).pdf","printedPages":["26-4"],"pdfPages":[2],"text":"The source defines capacity as contaminant mass held between regenerations, often stated relative to desiccant mass; efficiency is the separation achieved in the passing stream, reported in ppm or dewpoint. Its examples are roughly 15-20% water by mass for new molecular sieve and very low dewpoint capability. These are source examples, not usable cyclic capacity, a guaranteed dewpoint, or a replacement criterion for Clear Fork media. The particles contain internal pores; their external bead or pellet outline is not their available adsorption area.","sourceClass":"PETROSKILLS_TRAINING_REFERENCE_NOT_PLANT_SPECIFICATION","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS26-12KK-02","targetInfoKey":"ps_ads_materials_12kk","title":"Table 26-1: commercial adsorbent uses and qualifications","sourceFile":"2026-07-29 17-36(3).pdf","printedPages":["26-5"],"pdfPages":[3],"text":"Table 26-1 distinguishes activated alumina, activated carbon, silica gel and molecular sieves 3A, 4A, 5A and 13-X. Alumina examples include drying and sacrificial/buffer duty; carbon examples include hydrocarbons and selected contaminants; silica gel includes drying and C5+ recovery. The sieve examples distinguish water-selective 3A, more broadly used 4A, normal-paraffin and selected sweetening uses of 5A, and larger-aperture 13-X uses. Asterisks denote non-regenerable examples: the table is not a statement that every listed use can be regenerated. Printed regeneration ranges include 390-570 F for 3A and 400-600 F for 4A and 5A; these are not Clear Fork heater settings or an installed-media selection.","sourceClass":"PETROSKILLS_TRAINING_REFERENCE_NOT_PLANT_SPECIFICATION","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS26-12KK-03","targetInfoKey":"ps_ads_materials_12kk","title":"Activated carbon: guard duty, carryover and filtration","sourceFile":"2026-07-29 17-36(3).pdf","printedPages":["26-5","26-6"],"pdfPages":[3,4],"text":"The source describes activated carbon upstream of another adsorbent as a buffer for heavy organics such as compressor lubricant. It distinguishes specialty regeneration from common removal/replacement and describes mercury-capture service as presenting spent-media handling/disposal concerns. Liquid slugging may redistribute or carry contaminants through the bed. Pre-filtration may protect pores from fouling, while post-filtration removes carbon fines; the cited 3-micron-absolute filtration is a conditional process example, not the rating of an installed Clear Fork filter.","sourceClass":"PETROSKILLS_TRAINING_REFERENCE_NOT_PLANT_SPECIFICATION","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS26-12KK-04","targetInfoKey":"ps_ads_materials_12kk","title":"Activated alumina: physical tolerance and unwanted reactions","sourceFile":"2026-07-29 17-36(3).pdf","printedPages":["26-6"],"pdfPages":[4],"text":"Activated alumina is identified as aluminum oxide, available in different purities, capacities and granule/bead forms. The source describes attraction to water, alcohols, glycols and heavy hydrocarbons, and relatively greater tolerance of liquid-slug damage than silica gel or molecular sieve. Alumina may be a whole drying bed or buffer layer. Its catalyst-carrier uses explain the warning that oxygen and/or higher temperature may permit unwanted reactions, fouling or permanent deactivation. This does not authorize liquid carryover or establish the material loaded at Clear Fork.","sourceClass":"PETROSKILLS_TRAINING_REFERENCE_NOT_PLANT_SPECIFICATION","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS26-12KK-05","targetInfoKey":"ps_ads_selectivity_12kk","title":"Molecular-size examples and Table 26-2","sourceFile":"2026-07-29 17-36(3).pdf","printedPages":["26-7"],"pdfPages":[5],"text":"The source contrasts uniform sieve cavities with the varying alumina cavities and illustrates 5A selectivity using normal butane versus isobutane. Table 26-2 labels the following as nominal molecular diameters using the Lennard-Jones relation, in angstroms: H2 2.89; O2 3.46; N2 3.64; CO2 3.30; H2O 2.65; NH3 2.60; CH4 3.80; C3H8 4.30; CH3OH 3.76; n-C4H10 4.30; i-C4H10 5.28; H2S 3.60. Retain the stated definition and table values; they are not a stand-alone specification for media selection or proof of contaminant removal in this plant.","sourceClass":"PETROSKILLS_TRAINING_REFERENCE_NOT_PLANT_SPECIFICATION","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS26-12KK-06","targetInfoKey":"ps_ads_selectivity_12kk","title":"Co-loading, displacement and binder integrity","sourceFile":"2026-07-29 17-36(3).pdf","printedPages":["26-7","26-8"],"pdfPages":[5,6],"text":"Two retention factors are distinguished: molecule size relative to the pore and interaction strength with the internal pore surface. The source gives water displacing more weakly retained CO2 as a competition/co-loading example when pore size and active sites permit both to enter. The clay-like binder must allow transport while supporting the formed particles. Fouling or binder degradation reduces effectiveness; clean feed and exclusion of free liquid therefore concern the formed particle as well as the sieve crystals. The source describes polarity and uses rate-of-adsorption wording; its treatment of CO2 is retained as an unresolved terminology issue, not independently verified molecular-polarity data.","sourceClass":"PETROSKILLS_TRAINING_REFERENCE_NOT_PLANT_SPECIFICATION","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS26-12KK-07","targetInfoKey":"ps_ads_selectivity_12kk","title":"Table 26-3: pore size, equilibrium capacity and bead-screen basis","sourceFile":"2026-07-29 17-36(3).pdf","printedPages":["26-9"],"pdfPages":[7],"text":"The table lists nominal pores of 3, 4, 5 and 10 angstroms for 3A, 4A, 5A and 13X respectively. Its equilibrium H2O capacities by mass distinguish powder from formed material: 3A 26% versus 21%; 4A 27.5% versus 22%; 5A 26% versus 21.5%; 13X 30% versus 26%. The footnote states 2.333 kPa and 25 C (0.34 psia and 77 F) for the capacity measurements. These are equilibrium sample values, not plant working capacity. The 4-8 and 8-12 labels refer to Tyler screen sizes; the source gives approximate 3.2 mm (1/8 inch) and 1.6 mm (1/16 inch) bead equivalents and warns that vendors customize basic sieve types. Acid-resistant grades are mentioned; no installed grade is inferred.","sourceClass":"PETROSKILLS_TRAINING_REFERENCE_NOT_PLANT_SPECIFICATION","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS26-12KK-08","targetInfoKey":"ps_ads_materials_12kk","title":"Silica gel: water sensitivity, guard layer and hydrocarbon recovery","sourceFile":"2026-07-29 17-36(3).pdf","printedPages":["26-9","26-10"],"pdfPages":[7,8],"text":"The source distinguishes silica-gel granules from small spheres and states that silica gel cannot dry gas as completely as molecular sieve. Rapid uptake of a free-water droplet may break ordinary silica gel; a special water-resistant grade may be placed at the inlet. C5+ adsorption can accompany dehydration or hydrocarbon-dewpoint control. Granular silica gel is described as less prone to coking in heavy-hydrocarbon service. These are source comparisons, not permission to admit oil or liquid to the installed dryers.","sourceClass":"PETROSKILLS_TRAINING_REFERENCE_NOT_PLANT_SPECIFICATION","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS26-12KK-09","targetInfoKey":"ps_ads_applications_12kk","title":"Application classes and Figure 26-2 operating-range comparison","sourceFile":"2026-07-29 17-36(3).pdf","printedPages":["26-10"],"pdfPages":[8],"text":"Dehydration removes water; separation recovers removed material; purification discards unwanted material to improve the main stream. Adsorbent choice depends on stream composition, inlet temperature, required dewpoint and additional design factors. Figure 26-2 compares molecular sieve (about -100 C outlet dewpoint / 65 C inlet), activated alumina (-80 C / 52 C) and silica gel (-65 C / 50 C). These approximate figure endpoints are generic comparisons, not Clear Fork temperature limits or guarantees; material selection belongs to the design/media supplier.","sourceClass":"PETROSKILLS_TRAINING_REFERENCE_NOT_PLANT_SPECIFICATION","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS26-12KK-10","targetInfoKey":"ps_ads_applications_12kk","title":"Hydrocarbon recovery and Figure 26-3 vapor-recovery arrangement","sourceFile":"2026-07-29 17-36(3).pdf","printedPages":["26-11"],"pdfPages":[9],"text":"Short-cycle adsorption can recover natural-gasoline fractions with water; the source cites adsorption periods of roughly 30 minutes to 2 hours for that application. Its HRU/HARU or vapor-condensing-unit example alternates two adsorption towers and includes a vacuum pump, recovery tower, supply pump, recovery pump and tank connections. Open/closed symbols in Figure 26-3 illustrate that example only; none of those extra devices or lineups is asserted to be installed at Clear Fork.","sourceClass":"PETROSKILLS_TRAINING_REFERENCE_NOT_PLANT_SPECIFICATION","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS26-12KK-11","targetInfoKey":"ps_ads_applications_12kk","title":"Purification, liquid service and concentrated regeneration waste","sourceFile":"2026-07-29 17-36(3).pdf","printedPages":["26-11","26-12"],"pdfPages":[9,10],"text":"The source positions adsorption sweetening mainly as polishing where a bulk amine process may be more economical for larger acid-gas loads. It gives less than 500 ppm sulfur compounds and less than 1-2% CO2 as example contexts, not feed limits. Adsorption in LPG/liquid service is described as slower than in gas service and regeneration occurs with gas after draining liquid. Capturing a dilute non-condensable contaminant can concentrate it in the regeneration stream, so regeneration source, recycle, disposal or downstream treatment must be considered together. The example amine-removal percentage is not Clear Fork performance.","sourceClass":"PETROSKILLS_TRAINING_REFERENCE_NOT_PLANT_SPECIFICATION","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS26-12KK-12","targetInfoKey":"ps_ads_cycles_12kk","title":"Parallel regenerable beds versus non-regenerable lead/lag","sourceFile":"2026-07-29 17-36(3).pdf","printedPages":["26-12","26-13"],"pdfPages":[10,11],"text":"Figure 26-4 distinguishes pretreatment, adsorption, post-treatment and closed-cycle regeneration with gas compression, cooling, water separation and recycle. The parallel configuration permits a bed to regenerate while other beds treat gas. Source examples include two beds online with a third regenerating and typical 8-, 12- or 24-hour cycles; these are not Clear Fork timers. Non-regenerable lead/lag puts a fresh downstream bed behind a lead bed so the lead media can be more fully used while the lag bed maintains treatment during changeout. A lead/lag arrangement is not the same operating sequence as cyclic regeneration.","sourceClass":"PETROSKILLS_TRAINING_REFERENCE_NOT_PLANT_SPECIFICATION","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS26-12KK-13","targetInfoKey":"ps_ads_vessel_support_12kk","title":"Vessel internals, distribution and pressure-temperature design","sourceFile":"2026-07-29 17-36(3).pdf","printedPages":["26-14"],"pdfPages":[12],"text":"The source shows a vertical vessel with fill/dump manways, inlet distribution, bed support and process nozzles. Gas commonly flows top-to-bottom during adsorption and liquid service bottom-to-top. Distribution prevents inlet jetting from grinding the top layer and spreads flow across the bed. The source discusses coincident high pressure and regeneration temperature, and distinguishes individual thermal/fire relief examples from upstream blocked-flow protection. These are source design explanations, not a verified Clear Fork nozzle schedule, pressure-temperature envelope or new relief assignment.","sourceClass":"PETROSKILLS_TRAINING_REFERENCE_NOT_PLANT_SPECIFICATION","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS26-12KK-14","targetInfoKey":"ps_ads_vessel_support_12kk","title":"Bed support load, graded layers and Example 26-1","sourceFile":"2026-07-29 17-36(3).pdf","printedPages":["26-15","26-16"],"pdfPages":[13,14],"text":"The support carries adsorbent weight plus the force caused by pressure drop and must allow uniform flow without particles wedging into openings. Figures 26-8/26-9 show wedge-wire or screen/grating support on beams, with perforated plate and graded support balls as alternatives/components. The source cautions against putting small adsorbent directly onto much larger balls because it fills voids and raises DP. Example 26-1 places 5 mm alumina above roughly 10 mm then 20 mm support layers. This is the book example, not an approved loading instruction for V-1413/1414/1415.","sourceClass":"PETROSKILLS_TRAINING_REFERENCE_NOT_PLANT_SPECIFICATION","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS26-12KK-15","targetInfoKey":"ps_ads_vessel_support_12kk","title":"Printed BASF loading example and top hold-down","sourceFile":"2026-07-29 17-36(3).pdf","printedPages":["26-16"],"pdfPages":[14],"text":"The illustrated loading example is a 7.00-ft-diameter, 10.50-ft-bed-height arrangement: 0.50 ft top ceramic, 1.00 ft Sorbead WS, 8.50 ft Siliporite NK-10 sieve and 0.50 ft bottom ceramic. It labels 1,654 lb Sorbead WS and 15,435 lb Siliporite NK-10, with floating screens and ceramic support/hold-down. The top silica-gel layer is described as heavy-hydrocarbon buffer protection. Uniform layer height, appropriate screens and avoiding rapid pressure/flow change preserve layer placement. Product names, quantities, densities and dimensions belong only to this source example; none are assigned to a Clear Fork vessel.","sourceClass":"PETROSKILLS_TRAINING_REFERENCE_NOT_PLANT_SPECIFICATION","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS26-12KK-16","targetInfoKey":"ps_ads_cycles_12kk","title":"Internal can/cast insulation versus external insulation","sourceFile":"2026-07-29 17-36(3).pdf","printedPages":["26-17"],"pdfPages":[15],"text":"Figure 26-10 distinguishes an internal can with dead-gas space from cast refractory, while Figure 26-11 shows external insulation. The source says internal insulation reduces steel heating and may reduce heater size by 25-50%, at the cost of construction/maintenance complexity. Expansion/contraction and insulation integrity remain design considerations. The printed large-diameter example pairs more than 10 ft with 2.5 m; this inconsistent conversion is retained as a source issue, not silently corrected. The text also cites below 650 F as a common design context, not a Clear Fork allowable temperature.","sourceClass":"PETROSKILLS_TRAINING_REFERENCE_NOT_PLANT_SPECIFICATION","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS26-12KK-17","targetInfoKey":"ps_ads_cycles_12kk","title":"Figures 26-12/26-13: process versus regeneration valve paths","sourceFile":"2026-07-29 17-36(3).pdf","printedPages":["26-17","26-18"],"pdfPages":[15,16],"text":"The three-bed example includes inlet coalescing, four switching valves per bed, regeneration heater/cooler/separator and dry-gas filtration. Its sequence key distinguishes adsorption A1/A2, heating H, cooling C, depressurization and repressurization. The two-tower manifold example labels Tower 1 adsorbing and Tower 2 regenerating with separate process-in/process-out and regen-in/regen-out connections. These diagrams explain the circuits; they do not replace plant-specific A/B/C/D tag assignments, feedback, permissives, or approved switching timing.","sourceClass":"PETROSKILLS_TRAINING_REFERENCE_NOT_PLANT_SPECIFICATION","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS26-12KK-18","targetInfoKey":"ps_ads_switching_12kk","title":"Regeneration flow, switching-valve duty and actuator damping","sourceFile":"2026-07-29 17-36(3).pdf","printedPages":["26-19"],"pdfPages":[17],"text":"The source cites regeneration flow of approximately 10-20% of process flow, normally counter-current and low enough not to lift the bed; this is not an installed flow setpoint. LPG service needs additional draining/refilling steps. It contrasts the usually lower differential across closed valves in temperature-swing regeneration (often less than 50 psi in its example) with pressure-swing service, and cites valve temperature changes as large as 300 C (572 F). Figure 26-14 identifies an Orbit rising-stem ball-valve assembly with position indication, solenoid/regulator panel and an oil damper controlling stroke to limit slamming. Its pictured XV-5442A is a textbook tag, not a new Clear Fork device. No installed valve type, stroke time, DP limit or control sequence is inferred.","sourceClass":"PETROSKILLS_TRAINING_REFERENCE_NOT_PLANT_SPECIFICATION","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"}],"topicTitles":{"ps_ads_materials_12kk":"PetroSkills Section 26 - Adsorbent materials and capacity","ps_ads_selectivity_12kk":"PetroSkills Section 26 - Molecular-sieve selectivity and source tables","ps_ads_applications_12kk":"PetroSkills Section 26 - Adsorption applications and regeneration-stream integration","ps_ads_cycles_12kk":"PetroSkills Section 26 - Bed arrangements, insulation and circuit examples","ps_ads_vessel_support_12kk":"PetroSkills Section 26 - Vessel distribution and bed support","ps_ads_switching_12kk":"PetroSkills Section 26 - Switching-valve duty and damping"},"alreadyRetained":["Adsorption versus absorption and the need for very low dewpoint before cryogenic processing.","Basic capacity/efficiency troubleshooting, mass-transfer-zone movement and breakthrough.","Regeneration temperature/flow/time/quality fundamentals and counter-current operation.","Carryover, fouling, dust, bed-DP trends, rapid switching damage and aging-bed diagnosis."],"sourceIssues":["Printed page26-8 groups CO2 among substances with polar forces; retain as source terminology pending technical review, not an independently verified polarity classification.","Printed page26-17 pairs10ft with2.5m; retain the inconsistent units visibly, not a validated conversion.","Figure/table values and media-loading quantities are source examples, not manufacturer specifications for the plant."]},"newReferenceKeys":["nameplate_psv6x02_12kk","instrument_mount_review_12kk","petroskills_adsorbers_review_12kk","ps_ads_materials_12kk","ps_ads_selectivity_12kk","ps_ads_applications_12kk","ps_ads_cycles_12kk","ps_ads_vessel_support_12kk","ps_ads_switching_12kk"],"baselineIndexSHA256":"d7b4c9ef79aa27123ede9fb52db90eef08727274be951717b32bb95442ea8563","baselineRyanSHA256":"852416fc7119011fa9e27400b4a8d20180d2817661e44bab796b9555f2f478bf"};
/* 12KK: three explicitly source-associated mounts, never nearest-service guesses. */
function cfRepairInstrumentMounts12KK(H,S){
 'use strict';
 var report={build:'12KK',updated:[],errors:[],pipeRoutesChanged:0,newInstruments:0};
 function vec(p){return new H.THREE.Vector3(p[0],p[1],p[2]);}
 function eq(a,b){return a.length===b.length&&a.every(function(x,i){return Math.abs(x-b[i])<1e-7;});}
 function attached(m){for(var p=m;p;p=p.parent)if(p===H.root)return true;return false;}
 S.instrumentMounts.forEach(function(q){try{
  var defs=H.fields.filter(function(f){return f.key===q.key&&f.installed;});if(defs.length!==1)throw Error(q.tag+': expected one installed field definition, found '+defs.length);
  var f=defs[0],runs=H.runs.filter(function(r){return r.key===q.pipeKey&&r.routeId12HN===q.routeId;});if(runs.length!==1)throw Error(q.tag+': exact host route is missing/ambiguous');
  var run=runs[0],a=run.points[q.leg],b=run.points[q.leg+1],p=vec(q.center),d=b.clone().sub(a),len=d.length(),u=d.clone().normalize(),t=p.clone().sub(a).dot(u);
  if(f.pipeKey!==q.pipeKey||Math.abs(run.r-q.radius)>1e-7||!eq(f.direction,q.direction)||!eq(f.normal,q.normal))throw Error(q.tag+': source host/axes/radius changed; re-review required');
  if(p.distanceTo(a.clone().addScaledVector(u,t))>1e-7||t<=f.half+.08||len-t<=f.half+.08)throw Error(q.tag+': target is not inset on the specified host straight');
  if(!eq(f.center,q.oldCenter)&&!eq(f.center,q.center))throw Error(q.tag+': unexpected prior mount; refusing broad relocation');
  var own=Array.from(new Set((H.byKey[q.key]||[]).concat((H.sprites||[]).filter(function(m){return m.userData&&m.userData.key===q.key;})))).filter(attached);
  if(!own.length)throw Error(q.tag+': no attached owned assembly');
  own.forEach(function(m){var x=m.userData||{};if(x.key!==q.key&&x.fieldDevice!==q.key)throw Error(q.tag+': shared/unowned geometry detected');if(x.pipeRouteIds12HN||x.sharedPipeKeys||x.psvKey||x.controlValveTag)throw Error(q.tag+': unexpected process-pipe/valve mesh');});
  var set=new Set(own),tops=own.filter(function(m){for(var n=m.parent;n&&n!==H.root;n=n.parent)if(set.has(n))return false;return true;}),delta=p.clone().sub(vec(f.center)),changed=delta.length()>1e-8;
  H.root.updateMatrixWorld(true);
  if(changed)tops.forEach(function(m){var start=H.root.worldToLocal(m.getWorldPosition(new H.THREE.Vector3())),world=H.root.localToWorld(start.add(delta));m.position.copy(m.parent.worldToLocal(world));m.updateMatrix();m.updateMatrixWorld(true);});
  if(!f.mountHistory12KK)f.mountHistory12KK={center:f.center.slice(),installedTap:f.installedTap?JSON.parse(JSON.stringify(f.installedTap)):null};
  f.center=q.center.slice();f.routeStart=run.points[0].toArray();f.routeEnd=run.points[run.points.length-1].toArray();f.leg=q.leg;
  if(f.installedTap){if(changed)['root','head','pipeCenter'].forEach(function(k){if(Array.isArray(f.installedTap[k]))f.installedTap[k]=vec(f.installedTap[k]).add(delta).toArray();});f.installedTap.pipeCenter=q.center.slice();f.installedTap.hostKey=q.pipeKey;}
  f.mountingReview12KK={hostKey:q.pipeKey,routeId:q.routeId,center:q.center.slice(),basis:S.mountingBasis};
  f.location=q.service+'; current 12KK mount '+q.center.join(', ')+'. Schematic, not field-surveyed.';
  if(H.anchors[q.key])H.anchors[q.key].top=p.clone();else H.anchors[q.key]={top:p.clone()};
  var r=H.records[q.key];if(r){r.location=f.location;r.sourceRecord=f;r.mountingReview12KK=f.mountingReview12KK;r.status='SOURCE_HOST_MOUNTED / SCHEMATIC_12KK';}
  own.forEach(function(m){m.userData.mountReview12KK=true;});
  report.updated.push({key:q.key,tag:q.tag,hostKey:q.pipeKey,routeId:q.routeId,from:q.oldCenter.slice(),to:q.center.slice(),objects:own.length,moved:changed,rootOnHost:true});
 }catch(e){report.errors.push(String(e.message||e));}});
 return report;
}
function cfPatchInstrumentTrace12KK(T,S,allowed){
 'use strict';if(T.sourceUpdate12KK)return T.sourceUpdate12KK;
 var out={build:'12KK',mounts:[],pipeRoutesChanged:0,edgesSplit:0},permit=allowed||S.instrumentMounts.map(function(q){return q.key;});
 function near(a,b){return a.every(function(x,i){return Math.abs(x-b[i])<1e-7;});}
 function distance(a,b){return Math.sqrt(a.reduce(function(s,x,i){return s+(x-b[i])*(x-b[i]);},0));}
 function between(p,a,b){var d=b.map(function(x,i){return x-a[i];}),l=d.reduce(function(s,x){return s+x*x;},0);if(l<1e-12)return false;var t=p.reduce(function(s,x,i){return s+(x-a[i])*d[i];},0)/l;return t>1e-7&&t<1-1e-7&&near(p,a.map(function(x,i){return x+t*d[i];}));}
 // Keep original edge indices stable. Expand any stored path using a split edge.
 function paths(o,index,newIndex,seen){if(!o||typeof o!=='object'||seen.has(o))return;seen.add(o);
  if(Array.isArray(o)){for(var i=0;i<o.length;i++){var v=o[i];if(v&&v.edge===index&&typeof v.forward==='boolean'){var extra=Object.assign({},v,{edge:newIndex});if(v.forward)o.splice(i+1,0,extra);else o.splice(i,0,extra);i++;}else paths(v,index,newIndex,seen);}}else Object.keys(o).forEach(function(k){if(k!=='edges'&&k!=='nodes')paths(o[k],index,newIndex,seen);});}
 S.instrumentMounts.filter(function(q){return permit.indexOf(q.key)>=0;}).forEach(function(q){
  var ri=T.routes.findIndex(function(r){return r.id===q.routeId&&r.key===q.pipeKey;}),c=T.components[q.key];if(ri<0||!c)throw Error('12KK missing trace identity '+q.key);
  var candidates=T.edges.map(function(e,i){return{e:e,i:i};}).filter(function(x){return x.e.r===ri;});
  var existing=candidates.flatMap(function(x){return[x.e.a,x.e.b];}).find(function(n){return near(T.nodes[n],q.center);}),node=existing;
  if(node==null){var match=candidates.filter(function(x){return between(q.center,T.nodes[x.e.a],T.nodes[x.e.b]);});if(match.length!==1)throw Error('12KK exact trace station not unique '+q.tag);
   var item=match[0],old=Object.assign({},item.e),end=old.b;node=T.nodes.length;T.nodes.push(q.center.slice());item.e.b=node;item.e.length=distance(T.nodes[old.a],q.center);
   var ni=T.edges.length;T.edges.push(Object.assign({},old,{a:node,b:end,length:distance(q.center,T.nodes[end])}));paths(T,item.i,ni,new Set());out.edgesSplit++;
  }
  if(!c.mountHistory12KK)c.mountHistory12KK={host:c.host||null,ports:(c.ports||[]).slice()};
  c.host={node:node,routes:[ri]};c.mountingReview12KK={hostKey:q.pipeKey,routeId:q.routeId,center:q.center.slice(),basis:S.mountingBasis};c.status='SOURCE_HOST_MOUNTED / SCHEMATIC_12KK';
  out.mounts.push({key:q.key,tag:q.tag,node:node,route:ri,center:q.center.slice()});
 });
 T.sourceUpdate12KK=out;if(T.counts){T.counts.nodes=T.nodes.length;T.counts.edges=T.edges.length;}return out;
}

var CF_MOUNT_RESULT_12KK=cfRepairInstrumentMounts12KK({THREE:THREE,root:plant,fields:CF3D_FIELD_DEVICES,runs:CF3D_PIPE_RUNS,byKey:byKey,sprites:sprites,anchors:ANCH,records:CF3D_DEVICE_RECORDS},CF_SOURCE_12KK);
window.CFInstrumentMounts12KK={status:function(){return JSON.parse(JSON.stringify(CF_MOUNT_RESULT_12KK));}};
if(CF_MOUNT_RESULT_12KK.errors.length){console.error("12KK instrument mount",CF_MOUNT_RESULT_12KK.errors);var mountAlert12KK=document.createElement("div");mountAlert12KK.setAttribute("role","alert");mountAlert12KK.textContent="12KK instrument mounting requires review: "+CF_MOUNT_RESULT_12KK.errors.join(" | ");document.body.appendChild(mountAlert12KK);}
/* END 12KK INSTRUMENT MOUNTS AND SOURCE */

cfFinishPerformance12JG();







var CF_SOURCE_12KM={"build":"12KM","baseline":"12KL","date":"2026-10-13","policy":"Preserve plant controls, process routes and previously reviewed knowledge. Operator identifies XV-6300A photo and equivalent XV-6100A/XV-6200A specifications, except individual serials. Place/reconcile each existing suction block upstream of its corresponding inlet PV on its own retained source branch, not at a guessed nearby pipe. Field dimensions and actuator details remain schematic/unverified. No new trips, inferred pressure units, assumed end-switch feedback or copied serials. PetroSkills adds missing source detail only; source examples are not plant procedures or operating targets.","plate":{"key":"suction_xv_plate_12km","sourcePhoto":"IMG_0715.jpeg","sha256":"094f5365ccb1b3404fcfedb108774dcd6fca34bf5b295cf4f5f46b931977e315","primaryTag":"XV-6300A","sharedTags":["XV-6100A","XV-6200A"],"manufacturer":"PBV / FORUM","figure":"C-6730-71-2200-GH-NB","serial":"1482089","assemblyDate":"01 20","manufacturingOrderReading":"Prefix unclear; visible ending REL006154 (pending clearer readback)","sizeMarking":"16","classMarking":"300","fields":[["Brand / assembly marking","P.B.V. / FORUM; ASSEMBLED IN USA"],["Figure","C-6730-71-2200-GH-NB"],["Size / class","16 / 300"],["First MOP marking","740 MOP AT -20F (pressure unit not printed in this row)"],["Second MOP marking","655 MOP AT 280F (pressure unit not printed in this row)"],["Body","A105/A350 LF2"],["Ball / stem","CS ENP / CS ENP"],["Seat / seal","G/PTFE / HNBR"],["Other visible markings","DBB NACE API 607/6FA QSL-1; API symbol / 6D-0129"]],"limits":["Photograph is operator-associated with XV-6300A; plant tag is not visible on this close-up.","Body plate only. Do not copy the 6x55A Class600 body or Bettis actuator data onto these 6x00A suction valves.","The MOP rows do not print a pressure unit; retain their raw markings rather than silently supply PSI/PSIG. Not control limits or PSV settings.","Shared model/size/class/material specifications are operator-reported for XV-6100A/XV-6200A. Serial1482089 belongs only to the photographed XV-6300A body.","Assembly date01 20 and the partly legible manufacturing order are individual photographed fields, not independently verified sister-unit identity.","Printed standard/DBB/NACE markings are retained source information, not independently certified compliance."],"missing":["Individual XV-6100A and XV-6200A body serials and independently tagged plates.","Actuator / solenoid / end-switch identification as fitted for each 6x00A assembly; do not substitute nearby 6x55A plates.","Full MO field, controlled valve datasheet including pressure units and field installation dimensions."]},"valves":[{"unit":6100,"owner":"c6100","xvKey":"cf3d_xv6100","tag":"XV-6100A","pvKey":"cf3d_c6100suctioncontroltagpending","pvTag":"PV-6100A","vendorAlias":"","vendorPVAlias":"","pipeKey":"pipeTo_c6100suc","routeStart":[-83.33333333333334,3,-111.3],"routeEnd":[-69.3,-0.5,-117.8],"center":[-81.25630341880343,5,-111.3],"pvCenter":[-69.3,1.6724999999999994,-119.6],"direction":[1,0,0],"stemDirection":[0,1,0],"basis":"Operator confirms the suction XV sits upstream of this same unit inlet PV; retained M2610 / M26x6B role and original same-branch mounting points preserve that order. Exact plant-to-vendor correspondence is identified as a role crosswalk, not a new source tag."},{"unit":6200,"owner":"c6200","xvKey":"cf3d_c6200suctionesdtagpending","tag":"XV-6200A","pvKey":"cf3d_c6200suctioncontroltagpending","pvTag":"PV-6200A","vendorAlias":"ABV-6202","vendorPVAlias":"ACV-6203","pipeKey":"pipeTo_c6200suc","routeStart":[-108.66666666666667,3,-111.3],"routeEnd":[-99.3,-0.5,-117.8],"center":[-106.39316666666667,5,-111.3],"pvCenter":[-99.3,1.6724999999999994,-119.6],"direction":[1,0,0],"stemDirection":[0,1,0],"basis":"Operator confirms the suction XV sits upstream of this same unit inlet PV; retained M2610 / M26x6B role and original same-branch mounting points preserve that order. Exact plant-to-vendor correspondence is identified as a role crosswalk, not a new source tag."},{"unit":6300,"owner":"c6300","xvKey":"cf3d_c6300suctionesdtagpending","tag":"XV-6300A","pvKey":"cf3d_c6300suctioncontroltagpending","pvTag":"PV-6300A","vendorAlias":"ABV-6302","vendorPVAlias":"ACV-6303","pipeKey":"pipeTo_c6300suc","routeStart":[-134,3,-111.3],"routeEnd":[-129.3,-0.5,-117.8],"center":[-131.92916666666667,5,-111.3],"pvCenter":[-129.3,1.6724999999999994,-119.6],"direction":[1,0,0],"stemDirection":[0,0,1],"basis":"Operator confirms the suction XV sits upstream of this same unit inlet PV; retained M2610 / M26x6B role and original same-branch mounting points preserve that order. Exact plant-to-vendor correspondence is identified as a role crosswalk, not a new source tag."}],"bindingsByKey":{"cf3d_xv6100":{"type":"screen-binary","path":["cmp","c61","run"],"basis":"Existing C-6100 compressor screen derives its Suction Valve indication from this unit RUN Boolean. Operator-associated upstream isolation role; screen-derived display only, NOT independent end-switch feedback."},"cf3d_c6200suctionesdtagpending":{"type":"screen-binary","path":["cmp","c62","run"],"basis":"Existing C-6200 compressor screen derives its Suction Valve indication from this unit RUN Boolean. Operator-associated upstream isolation role; screen-derived display only, NOT independent end-switch feedback."},"cf3d_c6300suctionesdtagpending":{"type":"screen-binary","path":["cmp","c63","run"],"basis":"Existing C-6300 compressor screen derives its Suction Valve indication from this unit RUN Boolean. Operator-associated upstream isolation role; screen-derived display only, NOT independent end-switch feedback."}},"petroSkills":{"sourceFile":"2026-07-29 17-27(3).pdf","sha256":"aee5b0568088009aa6136e7273b4a76e83ee3f80f69b7c5a553d5dfe78782795","printedRange":"16-52 through 16-66","pagesReviewed":15,"existingCategory":"PetroSkills - Fractionation & Mass Transfer","topicTitles":{"ps_fractionation_bottoms_12kh":"Bottom temperature, product quality and minimum-control example","ps_fractionation_reflux_12kh":"Reflux, internal traffic and source comparison cases","ps_condenser_control_12kh":"Condensers and tower pressure - Section 16 source arrangements","ps_reflux_accumulator_12kh":"Reflux accumulator - source inventory and control arrangements","ps_fractionator_guide_12km":"Fractionator operating guide and control economics","ps_fractionator_cascade_12km":"Fractionator cascade / feedforward control and side reboilers","ps_fractionator_level_12km":"Fractionator bottoms-level geometry and inventory smoothing"},"addedDetails":[{"id":"PS16-12KM-01","targetInfoKey":"ps_fractionation_bottoms_12kh","title":"Bottoms temperature: bubble point, latent heat and response lag","printedPages":["16-52","16-53"],"pdfPages":[1,2],"sourceFile":"2026-07-29 17-27(3).pdf","text":"The source links bottoms composition and boiling/bubble-point temperature at a given tower pressure. For unchanged feed/bottoms compositions, greater feed requires additional reboiler energy but the source explains that latent vaporization can increase without a new boiling temperature. Feed/reflux changes can cause temporary temperature excursions; repeatedly changing the setpoint can over-control the slow response. It cites one-to-two-hour response in some fractionators and conditionally discusses rerun handling while control settles. These are textbook response examples, not Clear Fork timers, approved routing or a temperature-to-purity calibration.","existingCoverageNotRepeated":"Existing heat-removes-light-components and minimum-energy concepts are cross-referenced; the transient versus steady boiling-point distinction and cited lag are added.","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS16-12KM-02","targetInfoKey":"ps_condenser_control_12kh","title":"Tower-pressure influence and lower-pressure constraints","printedPages":["16-53","16-54"],"pdfPages":[2,3],"sourceFile":"2026-07-29 17-27(3).pdf","text":"For its typical total-condenser column, the source describes pressure changes as affecting boiling points throughout the trays, reboiler, condenser and accumulator; corresponding bottoms-temperature/reflux adjustments can produce a prolonged upset. It treats pressure as normally fixed rather than a product-composition control point in that example. The feasible low pressure is limited by overhead condensation/cooling, product transfer pressure and compression expense; it describes seasonal settings where ambient condenser capability requires them. This framing does not replace the different pressure objectives of Clear Fork cryogenic recovery/rejection or authorize a setpoint change.","existingCoverageNotRepeated":"Earlier notes describe condenser pressure control; the explicit whole-column interaction and qualified lower-pressure constraints are the delta.","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS16-12KM-03","targetInfoKey":"ps_fractionation_reflux_12kh","title":"Reflux change: transient bottoms response versus sustained overhead duty","printedPages":["16-54"],"pdfPages":[3],"sourceFile":"2026-07-29 17-27(3).pdf","text":"The source says increased reflux cools and condenses/absorbs heavier overhead components, increases descending liquid and can initially lower bottoms temperature. In its controlled-column example the bottoms-temperature loop subsequently restores temperature, leaving bottoms quality practically unchanged. It therefore reserves reflux for overhead composition, while recognizing that added reflux raises both reboiler and condenser load and may force a higher condensing pressure. The text recommends only the reflux needed for the specified overhead in that example, not a universal minimum setpoint.","existingCoverageNotRepeated":"Generic reflux-separation/energy concepts remain; the temporary versus settled bottoms interaction is added.","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS16-12KM-04","targetInfoKey":"ps_fractionator_guide_12km","title":"Table16-5: inspect both products and fix the bottoms first","printedPages":["16-55"],"pdfPages":[4],"sourceFile":"2026-07-29 17-27(3).pdf","text":"The operator guide uses two manipulated control points: bottoms temperature and reflux. When both ends require a change, it says address the bottoms first and wait to observe the overhead response. For its95% purity example the table gives: top/bottom95/95 normal, no action;93/97 both heavy, reduce bottoms temperature;93/95 heavy top, increase reflux;97/95 light top, reduce reflux;95/93 light bottom, increase bottoms temperature;95/97 heavy bottom, reduce bottoms temperature;97/93 both light, increase bottoms temperature;93/93 heavy top/light bottom, increase bottoms temperature then reflux;97/97 light top/heavy bottom, reduce bottoms temperature then reflux. The source discusses average8-12-hour shift quality; this is not permission to relax actual product contracts or plant procedures.","existingCoverageNotRepeated":"No retained nine-case source table or sequencing explanation was present; existing general heat/reflux purpose is not restated as a new chapter.","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS16-12KM-05","targetInfoKey":"ps_fractionator_guide_12km","title":"Figures16-48/49: overpurification and rerun cost boundaries","printedPages":["16-56","16-57","16-58"],"pdfPages":[5,6,7],"sourceFile":"2026-07-29 17-27(3).pdf","text":"The source describes how excess boil-up/reflux can consume column capacity and reviews why operators historically overpurified. It conditions that strategy on energy cost, production-rate need, or circumstances preventing tighter control. Figure16-48 qualitatively plots falling operating cost as allowed impurity rises to the specification boundary; Figure16-49 subtracts rerun costs from selling price and attainable profit. The text includes energy, pumping, transfer and lost productive capacity as rerun costs. These are source economic examples, not current prices, optimization guarantees or permission to intentionally ship off-spec product.","existingCoverageNotRepeated":"Overpurification cost already exists; the qualified exceptions, capacity effect and rerun/opportunity-cost diagrams are the new detail.","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS16-12KM-06","targetInfoKey":"ps_fractionator_guide_12km","title":"Table16-6: controlled and manipulated variables","printedPages":["16-58","16-59"],"pdfPages":[7,8],"sourceFile":"2026-07-29 17-27(3).pdf","text":"Excluding feed rate and feed condition, Table16-6 pairs bottoms composition/temperature with reboiler heat input; distillate composition/temperature with reflux flow; tower pressure with condenser heat removal; tower-bottom level with bottoms flow; and reflux-accumulator level with distillate flow. The following text qualifies that actual schemes vary with total versus partial condensation and vapor versus liquid product; reboiler geometry affects controller locations. This is a textbook mapping, not added Clear Fork loops or a reason to apply a total-condenser level strategy to every reflux drum.","existingCoverageNotRepeated":"Prior Table16-4 listed five example control functions. The explicit16-6 controlled/manipulated pairing and configuration caveat are added separately.","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS16-12KM-07","targetInfoKey":"ps_fractionator_cascade_12km","title":"Reboiler temperature cascade: faster inner flow loop","printedPages":["16-59","16-60","16-61"],"pdfPages":[8,9,10],"sourceFile":"2026-07-29 17-27(3).pdf","text":"The source discusses temperature sensing in reboiler return vapor, at the bottom, or several trays above it, favoring a location with high temperature sensitivity to key composition (T/C in the text). A direct hot-oil valve output does not hold constant flow when supply conditions change. In the cascade example, the temperature master instead sends a remote setpoint to a hot-oil flow slave that rejects those disturbances. The inner flow loop must be much faster than the slow temperature loop for stable operation; tuning, instrumentation and operator understanding are prerequisites. The source keeps heating-medium temperature adequately high and relatively constant instead of using its slow response as the routine manipulated variable. No actual control configuration or tuning is changed.","existingCoverageNotRepeated":"Cascade and this master/slave disturbance explanation were absent from the retained source notes; existing reboiler roles remain cross-references.","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS16-12KM-08","targetInfoKey":"ps_fractionator_cascade_12km","title":"Side reboiler draw-off and two-phase return","printedPages":["16-61"],"pdfPages":[10],"sourceFile":"2026-07-29 17-27(3).pdf","text":"The source describes recovering otherwise-lost process heat with side reboilers to reduce bottom-reboiler heat demand. Liquid is withdrawn from a draw-off tray above the bottom, heated and partly vaporized, and returned as liquid plus vapor below the draw-off tray. The selected heat exchange temperature matches the tower profile at that location. This is a source arrangement and energy-integration principle; no additional Clear Fork nozzle, phase transition or routing is inferred.","existingCoverageNotRepeated":"Generic reboiler heat integration already exists; the explicit draw/return elevation and two-phase return description is the delta.","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS16-12KM-09","targetInfoKey":"ps_fractionator_cascade_12km","title":"Figure16-52: feedforward reflux and delay requirements","printedPages":["16-61","16-62"],"pdfPages":[10,11],"sourceFile":"2026-07-29 17-27(3).pdf","text":"The source explains that a reflux flow controller alone holds its set flow even when feed-rate changes alter internal vapor traffic. Figure16-52 sends feed FT through a multiplier relay and a delay timer to the reflux controller remote setpoint. It lists requirements: avoid chasing frequent minor feed changes; understand and tune the feed/composition/reflux relationship; maintain the loop; and keep the receiving reflux controller independently stable. The delay may suppress small frequent fluctuations while retaining response to longer-term changes. No fixed ratio, time delay, auto tuning or new plant control is prescribed.","existingCoverageNotRepeated":"No retained feedforward chain or requirements list was present; general internal reflux behavior is not duplicated.","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS16-12KM-10","targetInfoKey":"ps_condenser_control_12kh","title":"Figure16-53: partial-condenser vapor-product backpressure","printedPages":["16-63","16-64"],"pdfPages":[12,13],"sourceFile":"2026-07-29 17-27(3).pdf","text":"The source describes limited condenser cooling and the overhead product vapor-pressure curve as setting the feasible operating pressure. For a vapor overhead product with partial condensation, Figure16-53 throttles the reflux-drum vapor outlet for backpressure control, while liquid is reserved for reflux; tower pressure is approximately drum pressure plus condenser pressure drop. The pictured outlet is marked F.O., a diagram annotation not a fail-action assignment to a Clear Fork valve. The text separately notes that total condensation need not mean a fully flooded condenser.","existingCoverageNotRepeated":"Partial/total definitions were already retained. This explicit vapor-product pressure path, differential and drawing qualification is added.","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS16-12KM-11","targetInfoKey":"ps_fractionator_level_12km","title":"Bottoms level: weir geometry, controller location and smooth outlet","printedPages":["16-64","16-65"],"pdfPages":[13,14],"sourceFile":"2026-07-29 17-27(3).pdf","text":"For a kettle with a product weir, the source says tower-bottom liquid level is tied to the installed reboiler/weir geometry; the product-side level controller is downstream of that weir, as in Figure16-54. For a thermosyphon, two-phase return goes back to the tower and the bottoms-level controller is on the tower. Level is not presented as a composition adjustment: high level can impede vapor generation/return, while low level can permit vapor through the bottoms line. Within established high/low bounds the source favors smoothing outlet flow to a following tower or waste-heat exchanger rather than tight level chasing. No plant alarm bands or weir elevation are supplied.","existingCoverageNotRepeated":"Earlier weir descriptions remain. Configuration-specific controller locations, vapor escape and downstream smoothing are the added qualifications.","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"},{"id":"PS16-12KM-12","targetInfoKey":"ps_reflux_accumulator_12kh","title":"Accumulator level: partial, flooded-total and nonflooded-total cases","printedPages":["16-65","16-66"],"pdfPages":[14,15],"sourceFile":"2026-07-29 17-27(3).pdf","text":"For the partial-condenser example the source uses reflux-drum level to change condenser cooling: greater reflux withdrawal lowers level and calls for more cooling. For its flooded-total example the accumulator is normally liquid-filled; noncondensables can collect and displace liquid, and the source describes a level-operated vent to flare as a stop-gap that also loses product vapor. It then distinguishes a nonflooded total condenser with product draw, backpressure, hot-gas bypass for overcooling and high-pressure vent control. Figures16-55/16-56 are supplied; the referenced16-57 diagram is not. These are different source examples, not an instruction to open a plant flare valve or a claim that every drum uses the same control.","existingCoverageNotRepeated":"Accumulator inventory and other condenser alternatives already exist; this level-specific configuration comparison and noncondensable caveat are the delta.","authority":"SOURCE_DERIVED_TRAINING_NOT_PLANT_SPECIFICATION"}],"alreadyRetained":["Existing heat/reflux/product-role and overpurification principles; no duplicate generic chapter.","Section16-25 through16-51 condenser/reboiler and material-balance examples retained.","Kettle/thermosyphon definitions, surge inventory and partial/total condenser distinctions retained."],"sourceIssues":["16-59 cites Figure16-26 and Figure16-38 in a reboiler-control discussion while the local figures are16-50/16-51; preserve the citation discrepancy rather than silently repair it.","Figure16-50 on16-60 is titled Simple Reboiler Temperature Control while the following prose discusses adding a flow controller; the explicit cascade diagram is Figure16-51 on16-61.","16-65 refers to Figure16-57, which is NOT present in this upload ending with Figures16-55/16-56 on16-66. No unseen figure is reconstructed.","Table16-5 uses a95-percent example purity at each end. Its heavy/light labels and actions are retained for that textbook case, not converted into Clear Fork product specifications or an operator command table.","16-55 discusses average product composition over an8-12-hour shift; retained as source framing, not authorization to bypass contractual instantaneous limits or off-spec handling procedures."]},"summary":{"pdfPagesReviewed":15,"distinctPrintedPages":15,"addedPetroDetails":12,"valveBodyRecordsUpdated":3,"suctionValvePairsReconciled":3,"newPhysicalValveIdentities":0,"controlChanges":0,"sourceMediaBundled":false}};
/* BEGIN 12KM RESIDUE SUCTION VALVE RECONCILIATION */
function cfMountSuctionValves12KM(H,S){
 'use strict';
 var out={build:'12KM',pairs:[],updated:[],reused:[],restored:[],errors:[],newPhysicalIdentities:0,pipeRoutesChanged:0,plantWrites:0};
 function arr(p){return Array.isArray(p)?p:p.toArray();}
 function near(a,b){return a.every(function(v,i){return Math.abs(v-b[i])<1e-5;});}
 function station(run,p){var length=0;for(var i=0;i<run.points.length-1;i++){var a=arr(run.points[i]),b=arr(run.points[i+1]),d=b.map(function(v,j){return v-a[j];}),l=Math.hypot.apply(null,d),u=l?d.map(function(v){return v/l;}):[0,0,0],t=p.reduce(function(v,n,j){return v+(n-a[j])*u[j];},0);if(l&&t>=-1e-6&&t<=l+1e-6&&near(p,a.map(function(v,j){return v+u[j]*t;})))return {arc:length+t,leg:i,t:t,length:l};length+=l;}return null;}
 function aliases(r,names){r.aliases=r.aliases||[];names.filter(Boolean).forEach(function(a){if(r.aliases.indexOf(a)<0)r.aliases.push(a);[a,a.toUpperCase().replace(/[^A-Z0-9]/g,'')].forEach(function(k){var owner=H.aliases[k];if(owner&&owner!==r.assetId)throw Error('Ambiguous source alias '+k);H.aliases[k]=r.assetId;});});}
 S.valves.forEach(function(q){try{
  var run=H.runs.find(function(r){return r.key===q.pipeKey&&near(arr(r.points[0]),q.routeStart)&&near(arr(r.points[r.points.length-1]),q.routeEnd);});
  if(!run)throw Error('Retained host route changed: '+q.pipeKey);
  var xv=H.controls.find(function(v){return v.key===q.xvKey;}),pv=H.controls.find(function(v){return v.key===q.pvKey;});
  if(!xv||!pv)throw Error('Existing suction-pair definition missing '+q.unit);
  var xs=station(run,xv.center),ps=station(run,pv.center);
  if(!xs||!ps||xs.arc+xv.half>=ps.arc-pv.half)throw Error('Suction XV/PV order or clearance failed '+q.unit);
  [[xv,q.tag,q.vendorAlias],[pv,q.pvTag,q.vendorPVAlias]].forEach(function(item){
   var v=item[0],tag=item[1],key=v.key,r=H.records[key];if(!r)throw Error('Existing valve record missing '+key);
   var previousTag=r.tag,parts=(H.byKey[key]||[]).filter(function(m){return m.parent&&m.geometry&&!m.isSprite&&!(m.userData||{}).positionPart12KI;});
   var body=parts.find(function(m){return (m.userData||{}).valvePart==='inline-bore';});
   if(!body){delete v.installedSpool;v.tag=tag;H.install(v);parts=(H.byKey[key]||[]).filter(function(m){return m.parent&&m.geometry&&!m.isSprite;});body=parts.find(function(m){return (m.userData||{}).valvePart==='inline-bore';});if(!body)throw Error('No attached inline body after restoration '+tag);out.restored.push(key);}else out.reused.push(key);
   if(!near(arr(body.position),v.center))throw Error('Body and source station disagree '+tag);
   if(!r.geometryHistory12KM)r.geometryHistory12KM={tag:previousTag,referenceRecordOnly:!!r.referenceRecordOnly,modelKey:r.modelKey||null,status:r.status||'',location:r.location||''};
   v.tag=tag;v.aliases=Array.from(new Set((v.aliases||[]).concat([previousTag,item[2],tag]).filter(Boolean)));v.referenceRecordOnly=false;v.packagePending=false;v.identityStatus='OPERATOR_CONFIRMED_TAG_12KM / retained source host';v.placementNote='Retained exact '+q.pipeKey+' station; '+q.tag+' upstream of '+q.pvTag+'. Field coordinates and actuator dimensions remain schematic.';
   r.tag=tag;r.tagConfirmed=true;r.valveNumber=tag;r.referenceRecordOnly=false;r.referenceOnly=false;r.modelKey=key;r.parent=q.owner;r.parentAssetId=q.owner;r.equipment='C-'+q.unit;
   r.location=tag+' on '+q.pipeKey+'; '+(key===q.xvKey?'upstream of '+q.pvTag:'downstream of '+q.tag)+'; retained source-associated schematic station.';
   r.status='SOURCE_HOST_MOUNTED / OPERATOR_TAG_CROSSWALK_12KM';r.point12KM=v.center.slice();r.placement=r.location+' Exact field distances/actuator dimensions remain unverified.';
   r.suctionArrangement12KM={owner:q.owner,upstreamXV:q.tag,downstreamPV:q.pvTag,hostKey:q.pipeKey,center:v.center.slice(),authority:q.basis};
   aliases(r,[key,tag,previousTag,item[2]].concat(v.aliases));
   parts.forEach(function(m){m.userData=m.userData||{};m.userData.controlValveTag=tag;m.userData.sourceMount12KM=true;if(key===q.xvKey&&/^(rotary-body|connection-neck|inline-bore)$/.test(m.userData.valvePart||'')){var mat=m.material&&m.material.clone?m.material.clone():null;if(mat&&mat.color){mat.color.set(0x258c89);m.material=mat;}}});
   H.anchors[key]={top:H.vector(v.center),mid:H.vector(v.center)};
   H.replaceLabel(key,tag,v);H.deviceData[key]=Object.assign({},H.deviceData[key]||{},r);
   out.updated.push({key:key,tag:tag,center:v.center.slice(),pipeKey:q.pipeKey,station:station(run,v.center).arc,bodyParts:parts.length});
  });out.pairs.push({unit:q.unit,xv:q.tag,pv:q.pvTag,host:q.pipeKey,xvStation:xs.arc,pvStation:ps.arc,order:'XV -> retained strainer/line details -> PV -> compressor suction'});
 }catch(e){out.errors.push({unit:q.unit,error:String(e.message||e)});}});return out;
}
function cfPatchSuctionTrace12KM(T,S,allowed){
 'use strict';var out={build:'12KM',hosts:[],errors:[],routeChanges:0},allow=allowed||[];
 S.valves.forEach(function(q){[[q.xvKey,q.tag,q.center,q.vendorAlias],[q.pvKey,q.pvTag,q.pvCenter,q.vendorPVAlias]].forEach(function(a){if(allow.indexOf(a[0])<0)return;
  var c=T.components[a[0]],ri=T.routes.findIndex(function(r){return r.key===q.pipeKey;}),candidates=[];
  if(!c||ri<0){out.errors.push('Missing trace record '+a[1]);return;}
  T.edges.forEach(function(e){if(e.r!==ri)return;[e.a,e.b].forEach(function(n){if(T.nodes[n].every(function(x,j){return Math.abs(x-a[2][j])<1e-5;})&&candidates.indexOf(n)<0)candidates.push(n);});});
  if(candidates.length!==1){out.errors.push('Exact same-route host node missing/ambiguous '+a[1]);return;}
  if(!c.suctionHistory12KM)c.suctionHistory12KM={tag:c.tag,host:c.host||null,modelKey:c.modelKey||null,referenceOnly:!!c.referenceOnly};
  c.tag=a[1];c.modelKey=a[0];c.referenceOnly=false;c.referenceRecordOnly=false;c.host={node:candidates[0],routes:[ri]};c.aliases=Array.from(new Set((c.aliases||[]).concat([a[1],a[3],c.suctionHistory12KM.tag]).filter(Boolean)));c.status='SOURCE_HOST_MOUNTED / OPERATOR_TAG_CROSSWALK_12KM';
  c.aliases.concat([c.key]).forEach(function(alias){[alias,alias.toUpperCase().replace(/[^A-Z0-9]/g,'')].forEach(function(k){if(!T.aliases[k]||T.aliases[k]===a[0])T.aliases[k]=a[0];});});out.hosts.push({key:a[0],tag:a[1],node:candidates[0],route:ri});
 });});T.sourceUpdate12KM=out;return out;
}
var CF_SUCTION_MOUNT_12KM=cfMountSuctionValves12KM({runs:CF3D_PIPE_RUNS,controls:CF3D_CONTROL_VALVES,records:CF3D_DEVICE_RECORDS,deviceData:CF3D_DEVICE_DATA,byKey:byKey,anchors:ANCH,aliases:CF3D_DEVICE_ALIASES,install:cf3dInstallValve,vector:function(a){return V(a[0],a[1],a[2]);},replaceLabel:function(k,t,v){
 sprites.filter(function(s){return s.userData&&s.userData.key===k;}).forEach(function(s){if(s.parent)s.parent.remove(s);var i=picks.indexOf(s);if(i>=0)picks.splice(i,1);});sprites=sprites.filter(function(s){return !(s.userData&&s.userData.key===k);});
 var p=V.apply(null,v.center).addScaledVector(V.apply(null,v.stemDirection||[0,1,0]),v.visualScale*4.45);label(t,p.x,p.y,p.z,.85,k,v.kind==='shutdown'?'#ffab73':'#b6a9ff');
}},CF_SOURCE_12KM);
if(CF_SUCTION_MOUNT_12KM.errors.length)console.error('12KM suction valve geometry',CF_SUCTION_MOUNT_12KM.errors);
/* END 12KM RESIDUE SUCTION VALVE RECONCILIATION */

