 var endpointMap={};plans.forEach(function(p){[0,p.q.oldPoints.length-1].forEach(function(j){var from=sig(p.q.oldPoints[j]),to=sig(j===0?p.q.points[0]:p.q.points[p.q.points.length-1]);if(endpointMap[from]&&endpointMap[from]!==to)throw Error('12LD separated common endpoint '+p.q.key);endpointMap[from]=to;});});
 // Update service-path start markers from their actual remapped first edges.
