  [['nameplate_f1050_12ke','F-1050 plate'],['nameplate_758054_12ke','Unallocated 758054-1 plate'],['filter_plate_assignment_12ke','Ownership / remaining gaps']].forEach(function(q){var b=el('button',q[1],box);b.type='button';b.onclick=function(){library(q[0]);};});
