 'use strict';
 var I=H.info,R=H.records,D=H.deviceData||{},T=H.trace||{},C=H.categories||[],F=H.reviewFlags||{},Q=H.quiz||[],A=H.audit;
 if(!I||!R||!I[S.notebookKey]||!S.ownerKeys.every(function(k){return !!R[k];}))throw Error('12KU requires the retained Frick manual and three existing compressor owners');
 var out={build:'12KU',newReferenceRecords:0,newReferenceNotes:0,questionsAdded:0,questionsSkipped:0,canonicalFacts:S.newEntries.length,existingInformationLinks:S.crossReferences.length,existingManualOwnerReused:true,modelConfirmationsAdded:0,sourceClarifications:[],newPhysicalEquipment:0,geometryWrites:0,plantWrites:0,storageWrites:0};
 function cp(v){return JSON.parse(JSON.stringify(v));}
 function uq(a,v){if(!a.some(function(x){return JSON.stringify(x)===JSON.stringify(v);}))a.push(v);}
 function cat(name,key){var c=C.find(function(x){return x[0]===name;});if(!c){c=[name,[]];C.push(c);}uq(c[1],key);}
