  if(!R[k]){R[k]={assetId:k,key:k,tag:title,service:title,kind:'reference',referenceOnly:true,referenceRecordOnly:true,tagConfirmed:false,status:'OEM_FAMILY_REFERENCE_NOT_INSTALLED_EVIDENCE',aliases:[],sourceStorageMode:'learn-only',sourceMediaRetained:false};out.newReferenceRecords++;}
