 var report=cfApplyCompressionReview12MT({info:INFO,records:CF3D_DEVICE_RECORDS,deviceData:CF3D_DEVICE_DATA,trace:CF_TRACE_DATA_12IZ.components,sourceDefinitions:cfSourceDefinitions12HO()},CF_SOURCE_12MT);
