function cfRenderPetroStudy12NC(host,key){
 'use strict';var S=CF_PETRO_STUDY_12NC;if(!host||S.referenceKeys.indexOf(key)<0)return null;
 var old=host.querySelector('[data-petro-study12nc]');if(old)old.remove();
 var doc=host.ownerDocument;function el(t,text,p){var e=doc.createElement(t);if(text!=null)e.textContent=text;if(p)p.appendChild(e);return e;}
 var box=el('section');box.setAttribute('data-petro-study12nc',key);box.style.cssText='margin:12px 0;padding:14px;border:1px solid #47748d;border-radius:10px;background:#102431;color:#e0edf7;font:14px/1.6 Segoe UI,Arial,sans-serif;overflow-wrap:anywhere';host.insertBefore(box,host.firstChild);
 el('strong','PetroSkills source-linked practice',box);el('p','32 new practical questions across four retained subjects. These uploads match the existing sources exactly; this original Library entry remains the owner of its information.',box);
 var b=el('button','Practice the new 32-question pool',box);b.type='button';b.style.cssText='min-height:44px;padding:9px 14px;max-width:100%;white-space:normal';b.onclick=cfStartPetroPractice12NC;
 var d=el('details',null,box);el('summary','Source matches, page references and qualifications',d);
 S.intakes.forEach(function(i){el('p',i.filename+' | PDF 1-'+i.pages+' | printed '+i.printed+' | existing '+i.definition+'.'+i.path.join('.'),d);var h=el('small','SHA-256 '+i.sha256,d);h.style.wordBreak='break-all';});
 S.sourceQualifications.forEach(function(t){el('p',t,d);});el('p','Study only. These pages do not add installed components, change controls, or establish a field operating procedure.',d);
 return box;
}
