 if(Q){var ids=new Map(Q.map(function(q){return[q.id,q];})),texts=new Set(Q.map(function(q){return q.q.trim().toLowerCase().replace(/\s+/g,' ');}));S.quiz.questions.forEach(function(q){var old=ids.get(q.id),t=q.q.trim().toLowerCase().replace(/\s+/g,' ');if(old){if(JSON.stringify(old)!==JSON.stringify(q))throw new Error('12ND question ID collision '+q.id);return;}if(texts.has(t))throw new Error('12ND repeated question '+q.id);var v=JSON.parse(JSON.stringify(q));Q.push(v);ids.set(v.id,v);texts.add(t);added++;});}
