function cfPointArray12NE(p){return Array.isArray(p)?p.slice(0,3):[p.x,p.y,p.z];}
function cfPointGap12NE(a,b){return Math.hypot(a[0]-b[0],a[1]-b[1],a[2]-b[2]);}
function cfMapSlugPoint12NE(p,key){var d=CF_SLUG_PLAN_12NE.dimensions,z=d.centres[key];return[d.cx+(p[0]-d.cx)*d.sx,d.cy+(p[1]-d.oldCY)*d.sr,z+(p[2]-z)*d.sr];}
function cfMapRoutePoint12NE(p,route){
 var best=Infinity,answer=p.slice();
 // Exact shared tees take precedence over interpolation along a shortened collector.
 for(var ri=0;ri<CF_SLUG_PLAN_12NE.routes.length;ri++){var rr=CF_SLUG_PLAN_12NE.routes[ri];for(var vi=0;vi<rr.old.length;vi++){if(cfPointGap12NE(p,rr.old[vi])<.0002)return rr.points[vi].slice();}}
 for(var i=0;i<route.old.length-1;i++){
  var a=route.old[i],b=route.old[i+1],v=b.map(function(x,j){return x-a[j];}),vv=v.reduce(function(t,x){return t+x*x;},0);
  if(vv<1e-12)continue;
  var t=Math.max(0,Math.min(1,p.reduce(function(s,x,j){return s+(x-a[j])*v[j];},0)/vv)),q=a.map(function(x,j){return x+t*v[j];}),dist=cfPointGap12NE(p,q);
  if(dist<best){best=dist;answer=p.map(function(x,j){return x+route.points[i][j]+t*(route.points[i+1][j]-route.points[i][j])-q[j];});}
 }
 return answer;
}
